return {
  [1147961275165952] = "Estou aqui.",
  [1130369089678848] = "Você...",
  [1152495149648128] = "Esta linha de texto grande aparece no palco: Na verdade há um ( ) aqui!",
  [1152495149658368] = "O pingente de cristal amarelo gira no sentido anti-horário, movendo-se lentamente. \n... A resposta é negação...",
  [1152359321714944] = "Por que você acordou de repente?",
  [813709740591616] = "Está aqui para tomar uma bebida? Ainda não estamos abertos, mas posso deixar você provar primeiro.",
  [1152359321463040] = "Uma estátua de pedra desgastada; no escuro, você sente vontade de <P_Yellow> prestar homenagem </> a ele.",
  [1152359321321728] = "...Uma explicação forçada. A minha atitude em relação à comida gourmet não mudou, vou relatar com sinceridade as questões que descobri hoje... mas, você não quer provar que a sua atitude em relação às artes culinárias não mudou... Rei dos Chefs?",
  [1152359321307392] = "Massimo? Aquela gourmet conhecida por sua língua venenosa? Como ela poderia escrever um artigo elogiando outra pessoa?",
  [1152359322108160] = "Você tem força, mas infelizmente a está usando no lugar errado.",
  [1152359321977088] = "Não, não, acabei de lembrar que Benson precisa de uma gravata colorida. Dessa forma, ele pode não parecer tão chato quando for a um banquete.",
  [1152359321846016] = "...Então o verdadeiro amigo por correspondência é - o tio?!",
  [1152359321830656] = "Como Aprendiz, eu queria usar um 'método especial' para atravessar a parede e pegar um baú de tesouro, mas... como você pode ver, fiquei preso. Ajude-me, e o baú do tesouro e a chave serão todos seus!",
  [1139301010194944] = "Você?",
  [1139165182393856] = "Multar.",
  [519177257511169] = "Hum? O que está errado?",
  [519177257766145] = "Não-!",
  [818107786696448] = "Faça isso!",
  [818107786648320] = "Hum?!",
  [818107786767872] = "Este Artefato Selado deve ser usado por um Beyonder de Sequência 7 ou superior para resistir às alucinações que ele produz.",
  [818107787034624] = "David, esqueci, quando você se apaixonou por Aslan...",
  [1152359321690624] = "Atualmente, o Reino Goose está temporariamente <P_Yellow> desfrutando de um clima favorável </>. Você pode realizar <P_Yellow> duas </> tarefas hoje. O que você pretende fazer?",
  [1152495149669632] = "Cinco minutos depois...",
  [1152495149669376] = "Um dia depois...",
  [1152495149669120] = "Estranho Tingen, polícia estranha; Verei o que ele quer de mim amanhã.",
  [1152495149668864] = "Animação de entrada \"Drill\"",
  [1152495149668608] = "O serial killer \"Face-Ripper\" Johnny de repente solta um uivo arrepiante.",
  [1152495149668096] = "Droga, por que você está em um caixão?",
  [1152495149667840] = "Onde você está?",
  [1152495149667584] = "Jesse desamarrou a pulseira de empatia e trouxe a bruxa de volta para a Blackthorn Security Company...",
  [1152495149667328] = "Você conta a Jesse o que aconteceu.",
  [1152495149667072] = "O jogador saiu da Iron Cross Street. Atrás dela, Hayley estava sentada debaixo do plátano, rodeada de gatos selvagens, com um rato cinzento agachado sobre a mesa. Ela virou um cartão e sorriu para o novo convidado à sua frente.",
  [1152495149666816] = "O jogador chegou à Montanha Nevada e descobriu que já havia nevasca aqui.",
  [1152495149666560] = "Debaixo de uma árvore murcha à beira do lago, Hayley sentou-se no chão. Na frente dela estava uma velha usando um vestido de pano azul desbotado. Vários gatos selvagens jaziam silenciosamente nas proximidades.",
  [1152495149666304] = "O velho aponta casualmente e a estaca de madeira ao lado dele estala em resposta.",
  [1152495149666048] = "Edwin joga fora o anel da Sra. Meg com força.",
  [1152495149665792] = "O balão de ar quente do alto desce lentamente.",
  [1152495149665280] = "O canalha foge e você pode ouvir um leve \"baque\" - ele tropeçou novamente.",
  [1152495149665024] = "Parece que você não compreendeu o essencial da luta; vamos observar com mais atenção...",
  [1152495149664768] = "A névoa cinzenta começou a surgir diante de seus olhos e o jogador chegou em Castelo Sefirá .",
  [1152495149664512] = "Martin foi até a porta da frente e olhou para trás. Sob a luz da rua, o psiquiatra já havia se virado e ido embora. De repente, ele sentiu que esta noite poderia não ser tão difícil de suportar, afinal.",
  [1152495149664256] = "Quando alguém pergunta que música era, ele diz: \"Não pergunte. Você entenderá quando ouvir.\"",
  [1152495149664000] = "Mais tarde, ouvi dizer que o jovem realmente se deu bem com a caixa. \n Ele conta a todos que encontra que uma pessoa estranha cantou uma música para ele naquele dia; foi terrível, mas ele realmente não estava mais com medo.",
  [1152495149663744] = "Depois de algum tempo...",
  [1152495149663488] = "Massimo sai correndo do restaurante e o som de vômito vem de fora.",
  [1152495149663232] = "Depois de uma noite...",
  [1152495149662976] = "A luz das velas tremula ao vento até que o último raio de luz se apague.",
  [1152495149662720] = "Sussurros, suspiros suaves, farfalhar de roupas...",
  [1152495149662464] = "As roupas de Luna escorregaram, expondo parcialmente seus ombros cheirosos. As cortinas transparentes tremulavam ao vento, obscurecendo a figura na cama.",
  [1152495149662208] = "Antes mesmo que as palavras desaparecessem, Carmen saiu correndo da parede como um pedaço fino de papel.",
  [1152495149661952] = "Acompanhada pelo grito de um macaco, a parte inferior do corpo de Carmen retorna como um raio.",
  [1152495149661696] = "A parte inferior do corpo de Carmen pisca e desaparece em meio a seus gritos...",
  [1152495149661440] = "O babuíno reluta em se separar da parte inferior do corpo de Carmen, mas felizmente não ataca mais Carmen. \n Carmen, tendo recuperado sua liberdade, rapidamente se liberta...",
  [1152495149661184] = "Depois de um período de tempo...",
  [1152495149660928] = "Uma semana depois, você está passeando pela praça...",
  [1152495149660672] = "Shermin derrama a bebida no vaso sanitário, acompanhado pelo som da descarga...",
  [1152495149660416] = "Você explica a Shermin a situação indutora de diarréia da bebida.",
  [1152495149660160] = "Você corre para o banheiro e realiza alegremente um ato de eliminação de resíduos metabólicos.",
  [1152495149659904] = "O Messenger parece bastante confiável.",
  [1152495149659648] = "Ignorando as inúmeras “besteiras” sobre os rascunhos descartados.",
  [1152495149659392] = "Quando o sol da manhã nasce, você finalmente conclui um primeiro rascunho bastante decente.",
  [1152495149659136] = "Então, você foi pressionado pelo Mensageiro, revisando o novo capítulo da Escritura do Louco por uma noite inteira.",
  [1152359321944064] = "Além disso, este é o meio catalítico que usaremos a seguir. Fique à vontade para visualizá-lo e coloque-o de volta no ritual depois de terminar. Está bem ali.",
  [1152359322224640] = "<P_Heart> (A herança familiar que Ray Bieber obteve deve ser o Caderno Antigonus.) </>",
  [1152359321618688] = "Como você pode ver, meu mestre é conselheiro. Como ele poderia estar relacionado a um banheiro... hmm.",
  [1152495149657856] = "O pingente de cristal amarelo gira no sentido horário, movendo-se lentamente. \n... A resposta é afirmação...",
  [1152495149657600] = "O pingente de cristal amarelo gira no sentido horário, movendo-se rapidamente. \n... A resposta é uma afirmação muito forte...",
  [1152495149657344] = "O policial sai cheio de ânimo.",
  [1152495149657088] = "Três dias depois, você recebe notícias da polícia; os criminosos estão presos e o dinheiro foi recuperado.",
  [1152495149656832] = "A polícia afasta os dois golpistas...",
  [1152495149656576] = "Toda a cena cai em um breve silêncio, e então...",
  [1152495149656320] = "O macaco Haki não diz mais nada, comendo tudo que está na mesa em grandes bocados até ficar completamente limpo.",
  [1152495149656064] = "Carmen empurra o baú do tesouro para você e sai apressado, com as costas cheias de vergonha.",
  [1152495149655808] = "Carmen de repente percebe, e no segundo seguinte ele é \"cuspido\" do outro lado da parede.",
  [1152495149655552] = "A figura de Carmen pisca, saindo da parede como uma sombra desbotada.",
  [1152495149655296] = "Carmen foi empurrada para fora com um som de “pop”, caindo de bunda no chão, coberta de poeira.",
  [1152495149655040] = "Ah!—\n Um grito acorda completamente as duas pessoas na cama.",
  [1152495149654784] = "Você deixou para ele uma refeição completa, um teto sobre sua cabeça e uma noite de sono.",
  [1152495149654272] = "Os dois estudantes se afastam cada vez mais, desaparecendo no final da rua...",
  [1152495149654016] = "【Espaço reservado】O cristal amarelo no final da corrente se move suavemente, girando no sentido horário.",
  [1152495149653760] = "Você olha obsessivamente para o fundo do vaso sanitário, uma onda de tontura atinge sua mente e você cai nela, perdendo a consciência.",
  [1152495149653504] = "Você abre a porta e convida Ladis para entrar.",
  [1152495149653248] = "Depois de uma noite em que a lua de sangue estava excepcionalmente brilhante, muitas antiguidades relacionadas ao “Imperador Roselle” apareceram em Tingen, desencadeando continuamente eventos extraordinários. O Departamento de Polícia do Condado de \n transferiu os arquivos do caso para o esquadrão Vigias Noturnos, e você está atualmente iniciando uma investigação...",
  [1152495149652992] = "【Espaço reservado para desempenho】\nUm enorme rugido e fogo explodiram, e toda a prisão foi reduzida a cinzas! \nVocê está livre!",
  [1152495149652736] = "Alguns dias depois.",
  [1152495149652480] = "Há rumores de que o Imperador Roselle ascendeu ao trono divino antes de morrer, e isso é um sinal de sua ressurreição. \n Há rumores de que... \n O Departamento de Polícia de Tingen transferiu alguns casos anormais para o esquadrão Vigias Noturnos. Como recém-chegado ao esquadrão Vigias Noturnos, você está iniciando uma investigação.",
  [1152495149652224] = "Por que? \nComo isso é possível? \nO que isso significa?",
  [1152495149651968] = "Em uma noite em que a lua de sangue estava excepcionalmente brilhante, uma grande quantidade de conhecimento sobre o “Imperador Roselle” apareceu de repente em Tingen. Os livros de história, as revistas e os jornais pareciam ter voltado a mais de cem anos atrás, ao momento de maior glória de Roselle.",
  [1152495149651712] = "Num clarão de luz brilhante, você sentiu a torrente de conhecimento fluindo sob seus pés. Tingen na história apareceu no céu acima, e você foi levado pela torrente para Tingen durante a era da Revolução do Vapor e perdeu a consciência.",
  [1152495149651456] = "【Espaço reservado para animação de nível A】 À medida que o jogador canta o texto secreto, todos os livros flutuam, formando uma entrada materializada para o espaço.",
  [1152495149651200] = "【Espaço reservado】 Flashback da cena antes de Winnie desaparecer no sonho adivinhação .",
  [1152495149650944] = "A cena muda; depois que Winnie murmura na frente da escultura do conhecimento, ela desaparece como um fantasma... tela preta... Winnie desmaia em uma fábrica.",
  [1152495149650688] = "À noite, no distrito fabril, Winnie está conversando com um homem elegantemente vestido. O homem só é visto por trás e seu rosto não pode ser visto com clareza.",
  [1152495149650432] = "【Espaço reservado para animação de nível C】 O jogador vê algumas imagens borradas através do sonho adivinhação.",
  [1152495149650176] = "O Sr. Speer entregou-lhe o roteiro escrito e você voltou ao palco para continuar a apresentação.",
  [1152495149649920] = "Mais tarde, vocês dois mandaram Jess para o hospital. Felizmente, ele ficou apenas atordoado e não sofreu ferimentos graves. \n O líder da trupe, Brown, admirou suas habilidades de atuação; ele pensou que você era uma estrela brilhante para o futuro da trupe e convidou você para se juntar a eles. \n Mas você recusou essa gentileza; afinal, você é apenas um cidadão comum com um senso de justiça de passagem.",
  [1152495149649664] = "\"Ripper Jess\" finalmente caiu no chão após seu esforço, inconsciente. \nNeste momento, uma voz feminina familiar e uma voz masculina soaram atrás de você...",
  [1152495149649408] = "Jace tirou uma adaga afiada de seu casaco e, sob a luz fraca, mergulhou a ponta no peito de Liana. \n Tudo aconteceu tão de repente que quando você recuperou os sentidos, Liana já havia caído no chão à esquerda de Jace. O luar desceu silenciosamente como sangue.",
  [1152495149649152] = "Você não ganhou a confiança do transeunte, tente novamente.",
  [1152495149648896] = "Klein pulou na carruagem com pressa.",
  [1152495149648640] = "Sua improvisação viola o desenvolvimento do enredo da peça, por favor escolha novamente.",
  [1152495149648384] = "As luzes acendem e o desempenho volta ao normal.",
  [1152359321618944] = "<P_Heart> (Existe mesmo?) </>",
  [1152359321944320] = "O Sr. Leonard, da empresa de segurança, me ajudou antes. Ouvi dizer que ele também é um 'poeta nobre' e copiei alguns poemas... você poderia me ajudar a transmiti-los?",
  [1152359322224896] = "<P_Heart> (Eu o conheço pela memória do Sr. Louco... deveria estar relacionado a Beyonders , e a notícia foi selada.) </>",
  [818107787035136] = "Velho senhor, o vento e a neve estão muito fortes aqui, por que você está aqui sozinho?",
  [1152359322309888] = "Ore por sua graça",
  [1152359322308608] = "Tudo bem, adeus! Obrigado pelo seu entusiasmo! Que você tenha um dia maravilhoso!",
  [1152359322308352] = "Obrigado pela sua gentileza, vou me despedir agora!",
  [1152359322308096] = "Se você estiver disposto, poderemos estudar este livro juntos no futuro e experimentar pessoalmente o verdadeiro significado dele.",
  [1152359322307840] = "Acredito que após treinamento e coaching suficientes, você também entenderá tudo isso e compreenderá esta arte.",
  [1152359322307584] = "Disciplina é treinamento, treinamento é disciplina. Compreender a arte da disciplina é também compreender o domínio do treinamento.",
  [1143563229129216] = "Medo de quê? Não vou pregar nenhuma peça, pelo menos não agora.",
  [1152359322307328] = "Treinamento?!",
  [1152359322307072] = "Por que? Ah, isso é naturalmente para treinar melhor os membros do clube que precisam da minha ajuda!",
  [1152359322306816] = "Sr. Oros, gostaria de perguntar... por que comprou este livro?",
  [1152359322306560] = "Olhando para a sua expressão, você tem alguma dúvida?",
  [1152359322306304] = "<P_Heart> (Ele admitiu isso tão diretamente?) </>",
  [1152359322306048] = "Ah, é meu livro. Muito obrigado, não acredito que incomodei você para me ajudar a consegui-lo.",
  [1152359322305792] = "<P_Heart> (Clube...?) </>",
  [1152359322305536] = "Se ao menos houvesse alguém que pudesse facilmente ir para aquele clube.",
  [1152359322305280] = "Suspiro... o que devo fazer? Esses livros não podem ser empilhados aqui.",
  [1152359322304256] = "Sim, aqui sempre faz sol, ao contrário de Backlund, que está sempre coberto de chuva e neblina espessa.",
  [1152359322304000] = "O cenário aqui é muito bom. Foi só porque eu estava em uma viagem de negócios aqui que felizmente escapei do desastre daquela grande poluição e também conheci você.",
  [1152359322303488] = "Papai não volta há sete anos... Eu realmente espero que papai apareça na nossa porta amanhã.",
  [1152359322303232] = "Ele foi para Backlund para ganhar dinheiro; pode demorar muito até que ele possa voltar.",
  [1152359322301696] = "<P_Heart> (Suspirando) </> Pai... seu velho hábito reapareceu novamente.",
  [1152359322300672] = "Isso mesmo! Esse é o ângulo, essa é a pose!",
  [1152359322300416] = "Assim?",
  [1152359322300160] = "É isso mesmo, venha, por favor, sente-se e então olhe para essas montanhas...",
  [1152359322299904] = "Apenas sente-se?",
  [1152359322299648] = "Desta vez é muito simples, por favor vá até a cadeira da frente e sente-se... Ah, por favor, tome cuidado!",
  [1152359322299136] = "Perfeito! Perfeito demais!",
  [1152359322298880] = "Oitenta! Oitenta!",
  [1152359322298624] = "Quarenta! Quarenta!",
  [1152359322298368] = "Por que quarenta e oitenta... Vou tentar.",
  [1152359322298112] = "Sua força não é flexível o suficiente... Que tal isso, eu grito quarenta e você usa força moderada, eu grito oitenta e você usa força maior, que tal!",
  [1152359322297600] = "Venha, por favor, pegue o machado que lhe dei e ataque esta pilha de escombros!",
  [1152359322297088] = "Cada uma de suas penas brilha com o brilho da liberdade!",
  [1152359322296832] = "Perfeito! Perfeito demais! Até esses pombos voando...",
  [1152359322296576] = "Então olhe com os braços bem abertos... mostre uma expressão embriagada... bom, é isso!",
  [1152359322295552] = "Venha, por favor, fique de frente para a fonte... deixe as gotas de água caírem em seu rosto...",
  [1152359322295040] = "\"À nossa amizade, felicidades!\"",
  [1152359322294784] = "Perfeito! Perfeito demais! Quase dá vontade de levantar os braços e gritar...",
  [1152359322294528] = "Então olhe para a lente... Bom, é isso!",
  [1152359322294016] = "Isso mesmo... isso mesmo...",
  [1152359322293760] = "Assim?",
  [1152359322293504] = "Venha, por favor, levante a taça de vinho na sua frente.",
  [1152359322293248] = "Então, como devo posar?",
  [1152359322292992] = "Vou manter um negativo e o outro é para você. Feliz dia rastejante. Talvez nos encontremos novamente no próximo ano.",
  [1152359322292736] = "Negativos perfeitos. Para ser sincero, esses quatorze dias com você foram mais interessantes do que eu esperava.",
  [1152359322291712] = "Durante esses quatorze dias, você ajudou um corvo a coletar vestígios históricos. Então, estritamente falando, devo agradecer pessoalmente em nome do corvo.",
  [1152359322290944] = "Considere-me o fotógrafo especial de hoje. Ouvi dizer que outras pessoas tiraram fotos para você nos últimos treze dias. No último dia, por que não mudar o ângulo e pegar um para você?",
  [1152359322290432] = "Você tirou tantas fotos ajudando um corvo a coletar vestígios de espiritualidade . Você já teve curiosidade... sobre quem manteve aquele corvo espiritual vivo até agora?",
  [1152359322290176] = "Não é nada, também estou em busca de oportunidades para melhorar meu desempenho mágico. Vamos encontrar a Sra. Miriam agora.",
  [1152359322289920] = "Obrigado, Mágico {Sr.{Sra.|}}.",
  [1152359322289664] = "Este chapéu foi feito pela própria minha mãe. A comida, as risadas e aqueles dias bons de nossa família foram todos evocados neste chapéu.",
  [1152359322289408] = "Um chapéu muito requintado. Seus pais devem ter gostado disso.",
  [1152359322289152] = "Se você não se importa, por favor use este chapéu para se apresentar para minha mãe.",
  [1152359322288896] = "Este é o chapéu que meu pai usava nas apresentações. Quando eu era criança, antes de ele sair, ele deixava que minha mãe e eu nos revezássemos no uso deste chapéu. Ele disse que era uma preparação antes da apresentação.",
  [1152359322288640] = "Você sabe fazer mágica? Por favor, venha comigo.",
  [1152359322288384] = "Talvez eu possa ajudá-lo.",
  [1152359322288128] = "<P_Heart> (Olhando para baixo) </> Eu gostaria de saber como fazer mágica. Se eu conseguisse soltar seis pombos daquele chapéu, ela poderia parar de olhar. Essa é a única coisa que ela lembra agora.",
  [1152359322287872] = "O pai faleceu há seis anos e este ano... era para ser o quinquagésimo aniversário deles.",
  [1152359322287616] = "Meu pai era artista de rua nesta área antes de falecer, e seu melhor truque era a mágica do chapéu. Todo aniversário, ele evocava um pombo do chapéu para minha mãe.",
  [1152359322287360] = "Essa é... a promessa do meu pai.",
  [1152359322287104] = "Ela continua resmungando sobre seis pombos.",
  [1152359322286848] = "<P_Heart> (Suspirando) </> Não consegui encontrá-la em casa, imaginei que ela tenha ido à praça. Obrigado por fazer esta viagem, irei agora mesmo.",
  [1152359322286592] = "Você é filha da Sra. Miriam? Ela está parando as pessoas na praça. Talvez você precise ir buscá-la.",
  [1152359322286336] = "Se quiser ajudar, você pode ir até a casa dela e chamar a filha. É a casa que fica no segundo beco atrás da praça com um loureiro plantado na entrada.",
  [1152359322286080] = "Todos nesta rua a conhecem: a Sra. Míriam. Ela costumava ser uma senhora muito gentil, mas está cada vez mais confusa nos últimos anos. Sempre que ela vê alguém usando chapéu, ela diz que eles estão escondendo pombos nele e insiste que os deixem sair.",
  [1152359322285824] = "Você a conhece?",
  [1152359322285568] = "Este {Sr. | Sra.}, por favor, não ligue para ela, não adianta falar com ela.",
  [1152359322285312] = "A pomba está no chapéu do Mágico. Há mais seis que não foram divulgados. Seis! Eu estive contando.",
  [1152359322285056] = "Por que deve haver um chapéu?",
  [1152359322284800] = "Você nem tem chapéu na cabeça. Pessoas sem chapéu não saberão onde estão os pombos.",
  [1152359322284544] = "Você não pode parar as pessoas na rua assim. Quaisquer que sejam os pombos, posso ajudá-lo a encontrá-los.",
  [1152359322284288] = "<P_Heart> (Surpreso) </> Sério? Você pode me deixar tocar a luz?",
  [1152359322284032] = "Talvez eu possa ajudá-lo.",
  [1152359322283776] = "Adeus, caloroso {Sr. | Sra.}!",
  [1152359322283520] = "<P_Heart> (Movido) </> ...Vou valorizá-lo bem. Obrigado, Emilly.",
  [1152359322283264] = "Assim, quando sentir frio, você pode abri-lo e deixar aquecer seu coração.",
  [1152359322283008] = "Isso mesmo! Você me deu o sol e eu quero contar a história para você!",
  [1152359322282752] = "<P_Heart> (Acenando com a mão) </> Não, por favor, fique com ele. Este é o pequeno sol que Emily quer dar a você.",
  [1152359322282496] = "Este é o seu...",
  [1152359322282240] = "<P_Heart> (Movido) </> Emily...",
  [1152359322281984] = "Está... está muito quente. Como uma lareira no inverno, como a mão do papai.",
  [1152359322281728] = "Isso é o suficiente.",
  [1152359322281472] = "E daí? Lembro-me de tudo antes de morrer e posso continuar administrando a livraria e lidando com o conhecimento.",
  [1152359322281216] = "Isto é apenas conhecimento agindo como “você”.",
  [1152359322280960] = "Poder continuar vivendo é uma coisa boa, não é?",
  [1152359322280704] = "Depois que o “eu” humano faleceu, o Característica de Beyonder combinou-se com o conhecimento dos livros, dando origem ao “eu” atual.",
  [1152359322280448] = "Você percebeu. Bem, na verdade, sou um fantasma feito de conhecimento.",
  [1152359322280192] = "Mas você... não tem cheiro humano...",
  [1152359322279936] = "Meu? Eu sou, claro, o dono desta loja.",
  [1152359322279680] = "Você é...",
  [1152359322279424] = "Porque finalmente toquei a luz hoje! E eu tenho uma nova história!",
  [1152359322279168] = "Obrigado, {Sr. | Sra.}. Emily raramente fica tão feliz.",
  [1152359322278912] = "<P_Heart> (Tímido) </> Hehe, sério?",
  [1152359322278656] = "Sua história é o sol mais brilhante que já vi.",
  [1152359322278400] = "Uma história muito calorosa, já terminei de escrevê-la também.",
  [1152359322278144] = "Cansei de contar!",
  [1152359322277888] = "<P_Heart> (Sorriso brilhante) </> No final, a escuridão foi dissipada! Todos que vivem à noite reunidos no mundo da luz!",
  [1152359322277632] = "O sol foi passado de uma pessoa para outra e a noite escura gradualmente iluminou-se.",
  [1152359322277376] = "Ela disse a todos: “Isso me foi dado por alguém e agora é seu também”.",
  [1152359322277120] = "Então ela amassou a luz em muitas, muitas bolinhas e as deu para outras pessoas que estavam com medo do frio, perdidas ou tristes.",
  [1152359322276864] = "A menina segurou o pedaço de sol, sentiu seu calor e lembrou-se de sua aparência.",
  [1152359322276608] = "Aquele pedaço de sol era muito leve, como o peso de uma pena, mas iluminou todo o seu sonho.",
  [1152359322276352] = "Mais tarde, num inverno, alguém veio de longe e colocou um pequeno pedaço de sol na palma da mão dela.",
  [1152359322276096] = "Ela guardou tudo isso em seu coração, pensando: Um dia tocarei o sol.",
  [1152359322275840] = "A menina tateava seu caminho na noite escura todos os dias. Ela tocou paredes ásperas de pedra, pétalas macias e chuva fria.",
  [1152359322275584] = "Ela nunca tinha visto luz, mas sabia que a luz devia existir. Porque mamãe disse que a coisa mais quente do mundo é o sol.",
  [1152359322275328] = "Depois vou começar a contar... Era uma vez uma menina que vivia na noite escura.",
  [1152359322275072] = "Claro, ficarei feliz em ajudar.",
  [1152359322274816] = "<P_Heart> (Balançando a cabeça) </> Não, desta vez deixe este {Sr.|Sra.} escrever. Tudo bem?",
  [1152359322274560] = "Tudo bem, papai vai escrever para você...",
  [1152359322274304] = "Pai! Quero contar uma nova história!",
  [1152359322274048] = "Já toquei a rugosidade das paredes de pedra, a frieza da chuva, a suavidade das pétalas... mas como é a luz? Eu não posso tocá-lo, não importa o que aconteça.",
  [1152359322273792] = "Papai fica sentado ao lado da cama todas as noites, me ouvindo contar histórias e depois as anotando palavra por palavra em um caderno.",
  [1152359322273536] = "Emily é uma pequena escritora. Ela quer tocar o mundo, escrever como é e contá-lo para quem também não consegue ver.",
  [1152359322273280] = "Desculpe, {Sr.|Sra.}. Minha filha... ela não pode ver.",
  [1152359322273024] = "Procurando por luz?",
  [1152359322272768] = "Estou procurando luz!",
  [1152359322272512] = "Garotinha, você está procurando alguma coisa?",
  [1152359322272256] = "Olá? Lightning Express, documento urgente!",
  [1152359322272000] = "Hum! Lily protege os cidadãos e nós guardaremos \"Lightning Lily\"!",
  [1152359322271744] = "Quanto aos Aprendizes de caça à gangue, vou acabar com todos eles!",
  [1152359322271488] = "Deixe este Beyonder selvagem continuar a ser seu \"Lírio Relâmpago\"!",
  [1152359322271232] = "Você sabia? Obrigado, Rebecca, e obrigado, capitão Frye.",
  [1152359322270976] = "Você não precisa se preocupar, ela não será presa e sua segurança está garantida.",
  [1152359322270720] = "Eu já havia notado esse “Aprendiz” e discutido isso com o Capitão Frye.",
  [1152359322270464] = "Passando a negócios. A carta foi recebida; O capitão Frye me pediu para explicar isso a você.",
  [1152359322270208] = "Rebeca?! Por que você está aqui?",
  [1152359322269952] = "Miau miau... miau miau miau... miau...",
  [1152359322269696] = "Absolutamente não – Lightning Lily, missão cumprida!",
  [1152359322269440] = "Tudo bem, eu entendo. Vá em frente, não se atrase!",
  [1152359322269184] = "Shh, não conte para mais ninguém, eles vão ficar com ciúmes...",
  [1152359322268928] = "É grátis para você! Você salvou minha vida.",
  [1152359322268672] = "Claro, vou te dar um desconto! Não, espere...",
  [1152359322268416] = "Se houver uma entrega urgente na próxima vez, posso ir até você?",
  [1152359322268160] = "Tão rápido! Obrigado, deixe-me ajudá-lo a organizar os pacotes.",
  [1152359322267904] = "Que tal isso? Lightning Lily é tão rápida!",
  [1152359322267648] = "Não tem problema, está bem perto, de graça, volto em cinco minutos, espere por mim!",
  [1152359322267392] = "Tudo bem! Lily, você pode me ajudar a entregar uma carta na rua Zoutland, 2?",
  [1152359322267136] = "Obrigada... perdi tanto tempo, preciso organizar meus pedidos!",
  [1152359322266880] = "Não se preocupe, tipo selvagem Beyonders não deveria ser trancado no subsolo.",
  [1152359322266624] = "Eu vou cooperar, vou te contar tudo, só não me prenda.",
  [1152359322266368] = "Vou escrever uma carta ao capitão e pedir-lhe que fique de olho na sua segurança.",
  [1152359322266112] = "Você não machucou ninguém; quem está em perigo é na verdade você.",
  [1152359322265856] = "Usar suas próprias habilidades para ajudar os outros não é uma coisa ruim.",
  [1152359322265600] = "...Realmente? Você me salvou, eu... confio em você.",
  [1152359322265344] = "Selvagem Beyonders precisa de supervisão, mas não vou levar você embora.",
  [1152359322265088] = "Se eu for levado e preso, o que acontecerá com essas pessoas?",
  [1152359322264832] = "Se alguém estiver gravemente doente ou ferido e a enfermaria próxima estiver com falta de remédios, posso comprá-los o mais rápido possível...",
  [1152359322264576] = "Há um casal de idosos em Lamd Town que escreve para a neta no Distrito Leste todos os dias...",
  [1152359322264320] = "Eu só quero entregar pacotes, só quero ajudar os outros...",
  [1152359322264064] = "Ouvi dizer que algumas pessoas que foram levadas nunca mais voltaram.",
  [1152359322263808] = "Beyonders deve ser registrado e supervisionado; selvagem Beyonders será removido.",
  [1152359322263552] = "...Por que você acha que eu iria te pegar?",
  [1152359322263296] = "Você quer me prender e me trancar em um lugar escuro masmorra ?",
  [1152359322263040] = "Tudo bem, na verdade eu... sou um funcionário Beyonder ...",
  [1152359322262784] = "Espere! E você? Você é oficial ou é um ladino?",
  [1152359322262528] = "Nesse caso, Beyonders oficial ou selvagem pode facilmente prender você.",
  [1152359322262272] = "Esse segredo foi descoberto por você também? Eu também tenho um pequeno item místico...",
  [1152359322262016] = "É mediano. Além disso, você corre muito rápido, o que não é algo que uma pessoa normal possa fazer.",
  [1152359322261760] = "Muitas vezes finjo tomar atalhos, minha atuação é tão ruim assim?",
  [1152359322261504] = "Nunca contei a ninguém, nem mesmo à minha família...",
  [1152359322261248] = "Sim, Sequência 9 Aprendiz, Porta Aberta, Teleporte de curta distância.",
  [1152359322260992] = "Sua velocidade relâmpago vem das habilidades do Aprendiz Caminho.",
  [1152359322260736] = "Você me salvou e agora conhece meu segredo, certo?",
  [1152359322260480] = "...Esqueça, deixe que eles me usem, de volta ao posto de entrega.",
  [1152359322260224] = "Eles devem estar de olho em você há muito tempo, aproveitando sua gentileza.",
  [1152359322259968] = "Droga, eu realmente caí em uma armadilha. Por que existem tantas pessoas más!",
  [1152359322259712] = "Eu, hehe... eu apenas disse isso aleatoriamente, tentando assustá-los.",
  [1152359322259456] = "De nada. O “apoio” que você mencionou agora não seria eu, seria?",
  [1152359322259200] = "Ufa, ufa... estou salvo. Obrigado...",
  [1152359322258944] = "O chefe quer um Aprendiz Característica de Beyonder , tenho que conseguir para ele!",
  [1152359322258688] = "Carregue as mercadorias! O chefe disse: \"Aprendizes são muito úteis\", entendeu?",
  [1152359322258432] = "...Eu sou um mensageiro oficial, não um mensageiro Aprendiz.",
  [1152359322258176] = "Já configuramos; é especificamente para caçar Aprendizes!",
  [1152359322257920] = "Quer correr? Você está planejando \"Abrir Porta\" ou \"Teletransportar\"?",
  [1152359322257664] = "O que você quer dizer? Você está me interceptando? Não pense que você pode me impedir...",
  [1152359322257408] = "O documento é apenas papel usado, você é o ‘expresso’ urgente.",
  [1152359322257152] = "Eu amo mais o esconde-esconde! Somente se você me pegar você estará qualificado para investigar meus segredos.",
  [1152359322256896] = "Prejudicar os cidadãos? Que tipo de piada é essa! Tenho que ajudar aquela senhora, não há tempo a perder.",
  [1152359322256640] = "Eu não tenho maldade. Mas preciso ter certeza: você causará danos aos cidadãos?",
  [1152359322256384] = "Isso é um segredo. Quando você verificou com Visão Espiritual , eu também olhei para você com Visão Espiritual , Beyonder !",
  [1152359322256128] = "O bondoso Lírio Relâmpago, chegando à Cidade dos Nenúfares em vinte e cinco minutos, há alguma magia envolvida?",
  [1152359322255872] = "Muito obrigado, Lílian. Dobre o valor do frete, tudo depende de você!",
  [1152359322255616] = "Emoldurado? Ok... então deixe comigo! Garanto que será entregue no prazo.",
  [1152359322255360] = "Por favor, alguém incriminou meu marido, ele precisa urgentemente do documento para provar sua inocência.",
  [1152359322255104] = "Cidade dos Nenúfares? Isso é nos subúrbios, e faltam apenas vinte e cinco minutos...",
  [1152359322254848] = "Os documentos precisam ser entregues na Cidade Nenúfar até as três horas. O endereço está na capa.",
  [1152359322254592] = "Lily, depressa! Ajude-me... salve meu marido!",
  [1152359322254336] = "Basta trabalhar... colá-los aqui pode atrair mais clientes.",
  [1152359322254080] = "Parece que você ajudou algumas pessoas... Lírio Relâmpago?",
  [1152359322253824] = "Se você não quer que as pessoas vejam, por que colocá-los em um lugar tão visível?",
  [1152359322253568] = "Apenas notas comuns, nada de especial...",
  [1152359322253312] = "Ei, por que você está espiando! Eles são... escritos por clientes.",
  [1152359322253056] = "Contrabando, absolutamente recusado! Se você não acredita em mim, fique à vontade para olhar!",
  [1152359322252800] = "E eu sou apenas um... entregador normal que corre um pouco rápido!",
  [1152359322252544] = "Claro que não! Só entrego encomendas que posso carregar, não posso carregar você nas costas.",
  [1152359322252288] = "É diferente? Você não entregou pessoas, ou até coisas mais estranhas?",
  [1152359322252032] = "Eu ouvi isso errado? Que pedido estranho! Não sou motorista de carruagem.",
  [1152359322251776] = "Você poderia me levar até a estação de trem? Eu... estou prestes a perder o trem.",
  [1152359322251520] = "Enviando um pacote? Preço justo, rápido a um nível exorbitante!",
  [1152359322251264] = "Na verdade, eu não corri muito, apenas atuando, hehe.",
  [1152359322251008] = "Recebi mais de trinta pedidos hoje, minhas pernas estão quebradas—",
  [1152359322250752] = "Mimi, miau miau... Não pegou rato de novo hoje?",
  [1152359322250496] = "Esqueça, vou descansar um pouco, entrego rápido mesmo.",
  [1152359322250240] = "Deusa, tantos pedidos, qual devo entregar primeiro?",
  [1152359322249984] = "Há uma estação de correio perto da Lower Street, onde ela costuma descansar.",
  [1152359322249728] = "Magia? Não é impossível... Ela tem local de trabalho fixo?",
  [1152359322249472] = "A última vez que alguém questionou se ela usava magia, ela ficou com tanta raiva que não atendeu os pedidos daquela pessoa por três dias.",
  [1152359322249216] = "Não se preocupe com isso, Lily tem um temperamento teimoso. Se você perguntar, ela apenas dirá que pega atalhos e anda rápido.",
  [1152359322248960] = "Tão rápido?! Até mesmo uma carruagem teria dificuldade em atingir essa velocidade...",
  [1152359322248704] = "O slogan para \"Entrega Relâmpago\" é - dentro de Tingen, entregue em meia hora!",
  [1152359322248448] = "Todos os pedidos urgentes na minha loja, ela sempre consegue entregar antes do prazo!",
  [1152359322248192] = "Ela é Lightning Lily, a principal entregadora do 'Lightning Express'!",
  [1152359322247936] = "Com licença, posso perguntar sobre aquela garota agora há pouco...",
  [1152359322247680] = "Tão rápido que nem consigo ver de onde ela saiu...",
  [1152359322247424] = "É inimaginável! Da Iron Cross Street até a estação de trem, leva apenas dez minutos!",
  [1152359322247168] = "Deusa! Ela deveria estar em uma corrida de velocidade, não trabalhando como mensageira!",
  [1152359322246912] = "Olhar! 'Lírio Relâmpago' apareceu!",
  [1152359322245888] = "Esta cidade está podre até o âmago. Mas alguém tem que desenterrar essa carne podre, mesmo que eu seja o único que restou.",
  [1152359322245632] = "Falando nisso, brigas entre animais contam como combate, certo? Se você tiver sorte, poderá aprender algumas técnicas de combate com ele.",
  [1152359322245376] = "Este rato parece que está prestes a lutar contra um gato...",
  [1152359322242816] = "<P_Heart> (Eles estão chantageando aquele velho? Vamos ajudar!) </>",
  [1152359322242560] = "Estou falando com você! Seja honesto e entregue o dinheiro, caso contrário...",
  [1152359322240256] = "Parece que você concluiu todas as avaliações intermediárias de moda. Nada mal, a Fashion Association reconheceu o seu gosto. Agora você pode conversar com juízes seniores sobre correspondência real.",
  [1152359322240000] = "Você passou em todas as avaliações primárias. Sua compreensão de roupas é melhor do que a da maioria das pessoas. Você obteve a qualificação para associação intermediária. Vá e experimente avaliações de nível superior.",
  [1152359322237440] = "Isso é um grande negócio, deixe-me considerar...",
  [1152359322237184] = "Eu também, eu também!",
  [1152359322236672] = "Todos esses são segredos da Gangue dos Caçadores de Dragões; nem todo mundo está qualificado para saber.",
  [1152359322236416] = "Ouvi dizer que a carne de dragão é picante, é verdade?",
  [1152359322236160] = "Você encontrou o tesouro do dragão?",
  [1152359322235904] = "É verdadeiro ou falso? Onde está a cabeça do dragão? Você pode nos mostrar?",
  [1152359322235392] = "Isso é incrível demais...",
  [1152359322235136] = "Trezentas rodadas...",
  [1152359322234880] = "Então todos nós corremos e lutamos contra o dragão por trezentos rounds!",
  [1152359322234624] = "Ele segurou seu escudo bem na frente e desviou todo o fogo do dragão.",
  [1152359322234368] = "Mas quem é o nosso chefe ? Kevin Stock, é claro que ele não poderia recuar.",
  [1152359322234112] = "Naquele momento, o dragão desceu do céu, abriu a boca ensanguentada e o fogo que disparou poderia derreter o aço!",
  [1152359322233856] = "Definitivamente, definitivamente!",
  [1152359322233600] = "<P_Heart> (Pega a carteira) </> Se eu pegar você 'brincando' de novo, hmph, você sabe as consequências.",
  [1152359322233344] = "<P_Heart> (Imediatamente oferece a carteira com as duas mãos) </> Ah, é tudo um mal-entendido! Um mal-entendido! Estávamos apenas brincando, apenas brincando...",
  [1152359322233088] = "Ouvi de Terry que você o intimidou de novo? Sua carteira...",
  [1152359322232832] = "<P_Heart> (Um pouco nervoso) </> Ah, eu?",
  [1152359322232576] = "Espere, Baker, há mais uma coisa.",
  [1152359322232320] = "Vamos primeiro voltar ao acampamento, o ‘Manifesto da Caça ao Dragão’ ainda está lá, não podemos perdê-lo.",
  [1152359322232064] = "<P_Heart> (Para poder persistir depois de experimentar tudo isso... parece que eles realmente amam caçar dragões...) </>",
  [1152359322231808] = "Não será extinto!",
  [1152359322231552] = "Bom! Voltaremos e começaremos de novo. Até o momento do sucesso, a chama da caça ao dragão não se apagará!",
  [1152359322231296] = "Isso mesmo, trabalhe duro para ficar mais forte e recomeçar!",
  [1152359322231040] = "Está tudo bem, chefe . Depois de voltarmos, podemos continuar trabalhando duro!",
  [1152359322230784] = "<P_Heart> (Aperta o punho) </> Se voltarmos de mãos vazias assim, é simplesmente, é simplesmente...",
  [1152359322230528] = "Baker foi espancado diversas vezes por roubo e Seymour ainda está preso na delegacia...",
  [1152359322230272] = "Mas não estou reconciliado... Trabalhamos muito para economizar nas despesas de viagem.",
  [1152359322230016] = "Não somos páreo para o dragão. Já é uma sorte não termos sido mortos por isso agora.",
  [1152359322229760] = "Voltar para Tingen? Basta voltar assim?",
  [822439798257664] = "O que você está fazendo?",
  [1152359322229504] = "Melhor voltar ao acampamento para fazer as malas e voltar para Tingen o mais rápido possível.",
  [1152359322229248] = "Como esperado de... um dragão...",
  [1152359322228992] = "Chefe , tome cuidado... o escudo foi perfurado...",
  [1152359322228736] = "Levante-se, Kevin, levante-se, você ainda pode continuar...",
  [1152359322228480] = "Espere, vocês são todos pessoas comuns, não conseguem lidar com isso!",
  [1152359322228224] = "Então pegue suas armas, siga-me e vá lutar!",
  [1152359322227968] = "Sim!",
  [1152359322227712] = "Você... ainda quer caçar o dragão?",
  [1152359322227456] = "Com medo...",
  [1152359322227200] = "<P_Heart> (Voz ligeiramente trêmula) </> Você está com medo?",
  [1152359322226944] = "<P_Heart> (Chocado) </> Depois de perseguir por tantos anos, finalmente... eu vi...",
  [1152359322226688] = "É um dragão? Existe realmente um dragão? Os dragões podem realmente voar...",
  [1152359322226432] = "É um dragão.",
  [1152359322226176] = "O que é isso?!",
  [1130369089387264] = "Preciso que você me faça um favor: leve-me para ver todos da sua organização que estiveram no Lago Tingen.",
  [1152359322225920] = "Devo persistir, nunca desistirei—",
  [1152359322225664] = "Então devo caçar um dragão. Devo completar o nosso ideal, devo fazer com que o seu nome seja lembrado!",
  [1152359322225408] = "<P_Heart> (Eles são apenas pessoas comuns, sem vestígios de Beyonder poder... então foram dispensados...) </>",
  [1152359322225152] = "<P_Heart> (Quanto à Gangue de Caçadores de Dragões...) </>",
  [1152495149647360] = "Entre no cérebro da outra parte",
  [1152495149658624] = "O pingente de cristal amarelo para ali, imóvel. \n... O adivinhação foi afetado e nenhum resultado pode ser obtido...",
  [1152359322224384] = "Depois que a tempestade se acalmou, voltamos para Tingen para perguntar em todos os lugares, <P_Heart> (suspira) </> mas ele parecia ter evaporado...",
  [1152359322224128] = "Se eu soubesse que aquela coisa iria matá-lo, eu deveria ter ido ao fundo da questão... ou simplesmente amarrado ele à Gangue de Caçadores de Dragões.",
  [1152359322223872] = "Saia de Tingen, evite esta tempestade!",
  [1152359322223616] = "...Correr.",
  [1152359322223360] = "O grupo de irmãos que o seguiram estão todos mortos, e o irmão Riel parece ter também... <P_Heart> (Com uma voz chorosa) </> O que devemos fazer, chefe ...",
  [1152359322223104] = "Ele está no cais, não sei como provocou a polícia!",
  [1152359322222592] = "Chefe , é ruim! O irmão R-Riel está em apuros!",
  [1152359322222336] = "Dragão gigante aparecendo...",
  [1152359322222080] = "Dragon Hunter City é um antigo campo de batalha da Quarta Época... há figuras gigantes de dragões aparecendo, simbolizando o poder dos Quatro Imperadores...",
  [1152359322221824] = "Existem tantas lendas sobre dragões. Este é sobre Dragon Hunting City...",
  [1152359322221568] = "Ray insistiu em ir embora. Não houve escolha, eu tive que assumir a liderança da Gangue de Caçadores de Dragões. Quem sabia...",
  [1152359322221312] = "O Imperador Roselle disse: 'A riqueza e a honra devem sempre ser buscadas longe do perigo.' Não posso perder esta oportunidade!",
  [1152359322221056] = "Existe realmente uma coisa tão boa? Haverá perigo...",
  [1152359322220800] = "Glória, riqueza, poder... tanto quanto eu quiser!",
  [1152359322220544] = "<P_Heart> (Expressão fanática) </> Isso mesmo, contanto que eu possa herdá-lo, posso mudar o destino de todos!",
  [1152359322220288] = "Herança?",
  [1152359322220032] = "Recebi um presente, uma herança da minha família e agora preciso estudar isso com todas as forças.",
  [1152359322219776] = "Deixe-me ser o chefe da gangue Dragon Hunter, por quê? Você está desistindo da caça ao dragão?",
  [1152359322219520] = "Com a Gangue Dragon Hunter, a vida tinha um objetivo. Nós nos preparamos seriamente para o negócio de caça ao dragão até...",
  [1152359322219264] = "<P_Heart> (Bêbado) </> Gangue de Caçadores de Dragões! Dragão... Caçador! Você é o chefe!",
  [1152359322219008] = "Este lugar se chama Evil Dragon Bar, vamos formar uma Gangue de Caçadores de Dragões!",
  [1152359322218752] = "Existem muitos tesouros no covil de um dragão. Se conseguirmos caçar um dragão com sucesso, poderemos nos tornar heróis e figurões!",
  [1152359322218496] = "...Dragão?",
  [1152359322218240] = "Já entendi... vamos caçar um dragão!",
  [1152359322217984] = "Bem dito... mas onde podemos conseguir essas coisas...",
  [1152359322217728] = "Deixe-me mudar meu próprio destino, mudar o destino de todos, mudar – o destino de todos!",
  [1152359322217472] = "Eu realmente não estou reconciliado... Dê-me algum poder ou riqueza...",
  [1152359322217216] = "Como formigas... qualquer um pode pisar em nós...",
  [1152359322216960] = "Esqueça, cujos ancestrais não eram gloriosos? Agora, você é seu joalheiro e eu sou meu estivador...",
  [1152359322216704] = "Não me olhe assim agora; na verdade, meus ancestrais foram muito gloriosos. Nossa família... hum...",
  [1152359322216448] = "<P_Heart> (Suspiros) </> Originalmente, ele deveria estar aqui como eu...",
  [1152359322216192] = "Isso é apenas superficial. Na realidade, ele é o fundador da Gangue Dragon Hunter e também o primeiro chefe.",
  [1152359322215936] = "Já ouvi falar dele. Lembro que ele era joalheiro...",
  [1152359322215680] = "Você o conhece?",
  [1152359322215424] = "Caçador de Dragões... Ray Bieber?! Ele também é membro da gangue Dragon Hunter?",
  [1152359322215168] = "...Ofereça sua vida e seu coração! Missão cumprida!",
  [1152359322214912] = "Eu tenho um, eu tenho um. Lembro-me da primeira frase, 'The Dragon's Roar is Coming'...",
  [1152359322214656] = "Ah, não... nem consigo ver as palavras com clareza. Quem trouxe uma caneta?",
  [1152359322214400] = "<P_Heart> (arranca-o) </> Manifesto de Caça ao Dragão!",
  [1152359322214144] = "<P_Heart> (Pega o Manifesto de Caça ao Dragão e o sacode) </> Fazendo exercícios a ponto de perder até isso?",
  [1152359322213888] = "Quem, quem fugiu?! Estávamos apenas exercitando nossos corpos, nos preparando para a caça ao dragão!",
  [1152359322213632] = "Parece legal, mas não foi assim quando você estava fugindo agora há pouco.",
  [1152359322213376] = "Ofereça sua vida e coração ao Caçador de Dragões!",
  [1152359322213120] = "Glória! Glória!",
  [1152359322212864] = "Cace o dragão! Cace o dragão!",
  [1152359322212608] = "Eu me tornarei o grande Caçador de Dragões Kevin, alcançando grande glória!",
  [1152359322212352] = "Mas nada disso importa mais. Quando tivermos sucesso, teremos dinheiro e status.",
  [1152359322212096] = "<P_Heart> (Encolhe os ombros) </> Caçar dragões requer dinheiro. Não roubamos nem roubamos, então deveríamos confiar na caridade dos políticos, nas esmolas dos ricos ou nas dádivas dos deuses?",
  [1152359322211840] = "Amigo? Não se esqueça, seus subordinados roubaram minhas coisas.",
  [1152359322211584] = "Mas como você tem coragem de vir aqui, significa que está qualificado para ser nosso amigo.",
  [1152359322211328] = "Então foi você, o cara que se atreveu a ir contra a Gangue dos Caçadores de Dragões.",
  [1152359322211072] = "Bo-bo- chefe ! É {ele{ela|}}! Aquela que sempre estraga nossas boas ações!",
  [1152359322210816] = "Não sei o que a Gangue dos Caçadores de Dragões está tramando de novo... É melhor dar uma olhada.",
  [1152359322210560] = "Louvado seja a Senhora! Minha carruagem finalmente está salva!",
  [1152359322210304] = "Eles fugiram!",
  [1152359322210048] = "Tem um mapa também? Deixe-me ver.",
  [1152359322209792] = "...Você disse tudo sozinho!",
  [1152359322209536] = "O chefe sempre sonhou em caçar dragões. Nos preparamos por muito tempo e finalmente partimos hoje. Como as despesas de viagem não eram suficientes, eles partiram primeiro e nos deixaram procurar uma carruagem para alcançá-los. Este é o plano e o mapa, tudo escrito no papel!",
  [1152359322209280] = "Não estou falando, hein? Deixe-me ver, não parece muito longe da delegacia aqui...",
  [1152359322209024] = "Vamos ver quem se atreve a falar desta vez!",
  [1152359322208768] = "Qual é o plano específico?",
  [1152359322208512] = "Sim... agora mesmo eles correram de repente para agarrar a carruagem, gritando coisas como caça ao dragão e glória...",
  [1152359322208256] = "...Plano de caça ao dragão? Vamos mesmo caçar um dragão?",
  [1152359322208000] = "Idiota, você expôs isso também!",
  [1152359322207744] = "Nunca contaremos a você sobre o plano de caça ao dragão mais importante do chefe!",
  [1152359322207488] = "Por que você está indo para Dragon Hunting City?",
  [1152359322207232] = "Idiota, você expôs isso!",
  [1152359322206976] = "...Cidade Caçadora de Dragões?",
  [1152359322206720] = "É isso mesmo, nunca vamos contar que ele foi para Dragon Hunting City com o chefe !",
  [1152359322206464] = "Tosse, tosse... Nem pense em nos fazer trair nossos irmãos!",
  [1152359322206208] = "Como esperado, é preciso muito esforço para lembrar. Onde está aquele... Baker da última vez?",
  [1152359322205952] = "Me lembro agora, você é aquele da última vez... aquele que lutou...",
  [1152359322205696] = "Então direi de novo: sua gangue de caçadores de dragões, você me provocou.",
  [1152359322205440] = "Já perguntei isso uma vez, você não lembra?",
  [1152359322205184] = "Quem? Ousa interferir nos negócios da Gangue dos Caçadores de Dragões!",
  [1152359322204928] = "Existe, amigo, existe.",
  [1152359322204672] = "Grite, grite o mais alto que puder. Mesmo se você gritar até sua garganta quebrar, ninguém irá—",
  [1152359322204416] = "<P_Heart> (Lutando) </> Besteira de glória, isso é roubo! Deixe-me ir...",
  [1152359322204160] = "Isso mesmo, será uma testemunha da glória do chefe e uma medalha gloriosa!",
  [1152359322203904] = "Nosso chefe disse, ser requisitado pela Gangue de Caçadores de Dragões é uma honra para a carruagem.",
  [1152359322203648] = "Seus ladrões, devolvam a carruagem!",
  [1152359322203392] = "É Baker?",
  [1152359322203136] = "M-me ajude—",
  [1152359322202880] = "Em direção à estação! O-obrigado, gentil {Sr.{Sra.|}}...",
  [1152359322202624] = "Não se preocupe, vou buscá-lo de volta para você. Em que direção ele foi?",
  [1152359322202368] = "<P_Heart> (Baker... Gangue de Caçadores de Dragões... a dívida anterior ainda não foi saldada...) </>",
  [1152359322202112] = "Sim, minha carteira foi roubada de novo... Ai...",
  [1152359322201856] = "<P_Heart> (Lembro-me agora, ele é Terry) </> Você foi intimidado pela gangue Dragon Hunter novamente?",
  [1152359322201088] = "O que você está fazendo? Eu comprei esse ingresso.",
  [1152359322200832] = "Desta vez eles não me deixaram nem um centavo. Isso é demais...",
  [1152359322200576] = "<P_Heart> (Feliz) </> Eu lembro de você, você me ajudou porque a Gangue dos Caçadores de Dragões roubou meu ingresso... ai...",
  [1152359322200320] = "Está tudo bem, ainda posso me mover... <P_Heart> (Olha para cima) </> É você!",
  [1152359322200064] = "O que aconteceu com você? Você precisa de ajuda?",
  [1152359322198016] = "Que pena. Se os detalhes pudessem ser reajustados, talvez o resultado fosse diferente.",
  [1152359322195968] = "O equilíbrio de cores, materiais e acessórios é perfeito; essa estética é bastante rara.",
  [1152359322195712] = "Tudo bem... Cuide-se. Descer a montanha é mais difícil do que subir...",
  [1152359322195456] = "Jovem, ainda tenho que acompanhar o David o dia todo. Obrigado por me acompanhar aqui.",
  [1152359322195200] = "Não, não consigo me lembrar. Devo esquecer. No próximo mês, começarei novamente do sopé da montanha...",
  [1152359322194944] = "<P_Heart> (Mas ele insiste em escalar a montanha há décadas para isso, e ele se lembra de tudo nesta estrada...) </>",
  [1152359322194688] = "<P_Heart> (Casar com David e enterrá-lo aqui... São todas memórias fabricadas do velho cavalheiro?) </>",
  [1152359322194432] = "<P_Heart> (Tão caótico, tão estranho... O velho cavalheiro estava originalmente apaixonado por David, mas David se apaixonou por Aslam?) </>",
  [1152359322194176] = "Eu me lembro, você e Aslan... Aslan, aquele homem...",
  [1152359322193920] = "Somos casados? Parece que não... Você conheceu Aslan...",
  [1152359322193664] = "David, você é meu amante ou meu irmão, minha esposa ou meu marido?",
  [1152359322193408] = "Está bem aqui, eu lembro... Não, não me lembro. Eu lembrei errado?",
  [1152359322193152] = "Independentemente de haver sinais de trânsito, pedras vermelhas ou belas esculturas...",
  [1152359322192896] = "Lembro-me que, durante décadas, este lugar, o seu túmulo, esteve aqui mesmo.",
  [1152359322192640] = "Deve haver algo errado em algum lugar. Meus olhos estão cegos, mas minha memória também ficou cega?",
  [1152359322192384] = "Mas como poderia não haver sepultura? Enterrei David com minhas próprias mãos e eu mesmo esculpi o epitáfio...",
  [1152359322192128] = "Posso ver tudo nesta estrada; Nunca tropecei nem caí de um penhasco.",
  [1134696805174016] = "Quem?",
  [1152359322191872] = "Será que eu realmente não consigo ver? O médico disse que eu estava cego há mais de doze anos, mas não sou cego.",
  [1152359322191616] = "Eu não estou mentindo para você; tudo nesta estrada é diferente do que você descreveu.",
  [1152359322191360] = "Não? Nem mesmo um túmulo? Eu... você não está mentindo para mim, está?",
  [1152359322191104] = "Senhor, você deve sentir muita falta de David, mas não há túmulo aqui.",
  [1152359322190848] = "O epitáfio que esculpi para ele: 'David, aquele que persegue o vento e a neve.'",
  [1152359322190592] = "Estamos aqui! Olha, a lápide é muito nova. Sempre o mantive bem conservado.",
  [519109612045824] = "Obrigado.",
  [1152359322190336] = "Eu sei, eu sei, ele adorava dizer coisas bobas...",
  [1152359322190080] = "O tempo mudará tudo; a pedra irá deteriorar-se, as esculturas irão deteriorar-se e ficarão cobertas de musgo.",
  [1152359322189824] = "Perguntei-lhe porquê e ele disse... os flocos de neve derreterão, mas a escultura não envelhecerá.",
  [1152359322189568] = "Ele me disse que depois de morrer, seria enterrado aqui, derretendo como neve.",
  [1152359322189312] = "No ano em que ele ficou doente, eu o carreguei até aqui. Essa foi a última vez que ele se sentou no cacho de flores.",
  [1152359322189056] = "Essas flores que resistem ao frio intenso também florescem bem. David sempre escolhia alguns.",
  [1152359322188800] = "Danificado? Talvez já tenha passado muito tempo, mas as cores ainda devem estar lá.",
  [1152359322188544] = "Aquela estátua... já está muito quebrada, e até faltando algumas partes.",
  [1152359322188288] = "<P_Heart> (Aquela estátua de pedra quebrada? E... como poderia haver flores aqui?) </>",
  [1152359322188032] = "Vê aquela escultura? As cores são vivas e estão rodeadas de flores frescas.",
  [1152359322187776] = "<P_Heart> (Eu... não há nada aqui, mas ele parece realmente ver?) </>",
  [1152359322187520] = "Jovem, há algo errado com seus olhos? Você não consegue ver nada.",
  [1152359322187264] = "Mas realmente não há sinal de trânsito aqui. Talvez tenha sido destruído por alguma coisa.",
  [1152359322187008] = "David disse uma vez que a coisa mais romântica da vida é perseguir o vento e a neve.",
  [1152359322186752] = "A sinalização rodoviária é muito resistente. Nós mesmos fizemos isso e eu gravei as palavras.",
  [1152359322186496] = "Como isso poderia ser? Olhe novamente, diz 'Aquele que persegue o vento e a neve'.",
  [1152359322186240] = "Senhor... não há sinal de trânsito aqui. Poderia ter sido derrubado pelo vento e pela neve?",
  [1152359322185984] = "Você vê este sinal de trânsito? Precisamos seguir sua direção.",
  [1152359322185728] = "<P_Heart> (...Este velho senhor, seus olhos... não são muito bons?) </>",
  [1152359322185472] = "Esculpimos nossos desejos na pedra vermelha e até desenhamos grafites feios...",
  [1152359322185216] = "Isso não pode ser. Tenho andado por aí há décadas. David disse uma vez que parecia um coração.",
  [1152359322184960] = "Realmente não existe um. Embora esta estrada seja difícil de percorrer, não há pedras bloqueando o caminho.",
  [1152359322184704] = "Como poderia não haver? Ele se projeta do penhasco e há grafites de desejos nele.",
  [1152359322184448] = "Pedra vermelha escura? Há rochas cinzentas por toda parte e muitas estão cobertas de neve.",
  [1152359322184192] = "Tenha cuidado aqui, há uma pedra vermelha escura bloqueando o caminho. Contorne isso.",
  [1152359322183936] = "...Tudo bem, raramente encontro pessoas com quem possa conversar, caminhar comigo.",
  [1152359322183680] = "...Vou acompanhá-lo até lá, até estradas familiares podem sofrer acidentes.",
  [1152359322183424] = "Tudo bem... <P_Heart> (Ele mencionou um poste de madeira agora há pouco? Não há postes de madeira aqui?) </>",
  [1152359322183168] = "Não se preocupe, conheço essa estrada muito, muito bem. Eu poderia andar de olhos fechados.",
  [1152359322182912] = "Mas é muito perigoso subir a montanha com este tempo e é muito difícil caminhar pela estrada coberta de neve.",
  [1152359322182656] = "<P_Heart> (Esposa? Ele? O que está acontecendo... David, um nome masculino?) </>",
  [1152359322182400] = "Ele está enterrado no local com melhor vista da montanha. Esta foi a nossa promessa quando éramos jovens.",
  [1152359322182144] = "Vou subir a montanha para encontrar minha esposa, David. Venho todos os meses, há décadas.",
  [1152359322181632] = "Deixe isso comigo. Vou desbloquear as Algemas da Empatia.",
  [1152359322181376] = "Houve muitos casos semelhantes de perda de controle recentemente, e a fonte parece apontar para o mesmo lugar... \"Rose Paradise\". Passarei a informação ao Trevor; você só precisa estar ciente disso.",
  [1152359322181120] = "Aliás, você notou algo incomum durante a escolta? Por exemplo, ela mencionou “Rose Paradise” ou um nome chamado “Bonnie”?",
  [1152359322180352] = "Você está dizendo que o policial Trevor pediu para você usar as \"Algemas de Empatia\" para suprimir a perda de controle de um Beyonder?",
  [1152359322180096] = "Você finalmente está aqui. Como está a situação?",
  [1152359322179840] = "Mesmo que todos envelheçamos, essas promessas continuarão sob outras formas.",
  [1152359322179584] = "Quando eu acordar amanhã, posso esquecer de novo, mas tudo bem. O campo de abóboras ainda está aqui, a bebida do Velho Chuck ainda está sendo vendida e a neta de Colley ainda está correndo.",
  [1152359322179328] = "{Sr.{Sra.|}}, obrigado por me ajudar a encontrar isso de volta. Vou anotar tudo isso.",
  [1152359322179072] = "<P_Heart> (Aliviado) </> ...Então é assim. Achei que tinha quebrado minha promessa, pensei que o tempo tinha me deixado para trás na estrada. Mas isso não aconteceu; apenas percorreu outro caminho para mim.",
  [1152359322178816] = "Você não perdeu. O você do passado já havia retornado.",
  [1152359322178560] = "O pequeno Colley... realmente cultivou a maior abóbora.",
  [1152359322178304] = "A vovó disse que a coisa mais feliz da vida dela foi conseguir aquelas sementes.",
  [1152359322178048] = "A vovó disse que essas sementes de abóbora lhe foram dadas há muito, muito tempo por uma amiga que voltou de uma viagem distante. Aquele viajante também trouxe uma receita muito especial de destilado, que agora é vendida em todo o Golden Autumn Lake!",
  [1152359322177792] = "Olhar! Estas são as abóboras que a vovó plantou!",
  [1152359322177536] = "Claro! Me siga!",
  [1152359322177280] = "Você pode nos levar para ver?",
  [1152359322177024] = "Essa é minha avó! Ela foi incrível; ela cultivou as maiores abóboras de Loen! O canteiro de abóboras da nossa família é o mais famoso de todo o Golden Autumn Lake!",
  [1152359322176768] = "Colley... qual é a sua relação com Colley?",
  [1152359322176256] = "Espere! Garotinha, qual é o seu nome?",
  [1152359322175744] = "Venha e me pegue!",
  [1152359322175488] = "Nara Colley! Não corra!",
  [1152359322175232] = "<P_Heart> (Tristeza) </> Que piada cruel o tempo fez. Nos meus anos de ignorância, todos os meus amigos foram levados embora.",
  [1152359322174976] = "<P_Heart> (Chocado) </> Não, impossível... setenta anos se passaram? O Velho Chuck e o Pequeno Colley... Eles já...",
  [1152359322174720] = "O que?! Deixe-me ver! Lago Dourado do Outono... setenta anos atrás...",
  [1152359322174464] = "Palino, eu encontrei. Então... Golden Autumn Lake é sua cidade natal.",
  [1152359322174208] = "Ótimo! Então vamos comprar a bebida primeiro. Quanto às sementes... descobriremos mais tarde.",
  [1152359322173952] = "Não desanime. Vi anteriormente que a loja em Golden Autumn Lake vende bebidas destiladas Feysac. Pelo menos o problema do licor forte pode ser resolvido.",
  [1152359322173696] = "E minha cidade natal... eu nem sei onde fica minha cidade natal.",
  [1152359322173440] = "Devo cumprir essas promessas, mas não me lembro onde coloquei as coisas. Talvez... essas coisas tenham se perdido junto com minhas memórias.",
  [1152359322173184] = "O que você planeja fazer? O que está escrito aqui parece um acordo entre você e eles.",
  [1152359322172928] = "<P_Heart> (Confuso) </> Esses nomes são familiares, mas não consigo lembrar quem são.",
  [1152359322172672] = "Licor forte, sementes de abóbora, Old Chuck, Little Colley...",
  [1152359322172416] = "Você encontrou? Muito obrigado! Deixe-me ver...",
  [1152359322172160] = "Lembre-se, a beleza sempre tem um preço... mas você descobrirá que o preço vale muito a pena.",
  [1152359322171904] = "Este é um convite oficial. Se você estiver disposto a se juntar a nós, leve esta carta.",
  [1152359322171648] = "Tecemos nossa própria rede nas sombras em nome da beleza.",
  [1152359322171392] = "Uma escolha sábia. Os membros do Baile Noturno de Primavera estão espalhados por todos os cantos desta cidade: perfumistas, alfaiates, farmacêuticos...",
  [1152359322171136] = "E você... você tem essa determinação?",
  [1152359322170880] = "Não tememos a zombaria do destino, porque todo infortúnio é uma transformação magnífica.",
  [1152359322170624] = "O Baile Noturno de Primavera serve como avatar do infortúnio e da beleza. Acreditamos que somente sendo batizados através do desastre as flores mais brilhantes poderão florescer.",
  [1152359322170368] = "Dançar graciosamente sob o luar, vislumbrando a verdade em meio à fragrância – esta é a nossa arte.",
  [1152359322170112] = "Abaixo da superfície desta cidade, inúmeros segredos estão escondidos, e somos nós que buscamos a beleza e a verdade.",
  [1152359322169856] = "Eu sou a guia do Baile Noturno de Primavera, Lise Evans.",
  [1152359322169600] = "Oh? Parece que você recebeu aquela carta... O destino da beleza e da destruição realmente favorece você.",
  [1152359322169344] = "No entanto, pelo menos posso enfrentar Andy agora. Vou ao túmulo dele para... tomar uma bebida.",
  [1152359322169088] = "A delegacia está podre até a medula. Eu também não sei o que fazer.",
  [1152359322168832] = "<P_Heart> (Atordoado) </> Acabou, e Andy também...",
  [1152359322168576] = "Hmm, o ritual de avanço falhou. Mas esse “mestre” parece ser outra pessoa...",
  [1152359322168320] = "Acabou?",
  [1152359322168064] = "Vamos entrar juntos. Este assunto precisa de um fim.",
  [1152359322167808] = "Se você estiver com medo, você pode voltar atrás. Afinal, este é o meu caso.",
  [1152359322167552] = "O ‘Mestre’ que ele mencionou provavelmente está realizando um ritual lá dentro. Devemos entrar e detê-lo imediatamente!",
  [1152359322167296] = "Caramba! Ele era originalmente meu superior. Eu nunca esperei que a toupeira fosse ele.",
  [1152359322167040] = "Parece que ele já enlouqueceu.",
  [1152359322166784] = "Hahahaha... Mestre... sim... quem é o Mestre? Sou eu? Ou é você? Hahahaha...",
  [1152359322166528] = "Quem exatamente é esse maldito 'Mestre' de quem você está falando?",
  [1152359322166272] = "Hehe, você não entende. Uma batata frita como você não entenderia!",
  [1152359322166016] = "Droga, a morte de Andy, as mortes daquelas pessoas, foram todas por esse chamado avanço?",
  [1152359322165760] = "Contanto que o mestre avance para se tornar um Alquimista, poderemos obter tudo!",
  [1152359322165504] = "O que você está falando! Que sacrifícios! Droga, acorde! O que aconteceu aqui!",
  [1152359322165248] = "Quase lá... está prestes a ter sucesso... todos esses sacrifícios são necessários...",
  [1152359322164992] = "Caramba! Fil! Como poderia ser você! Você não me pediu para investigar este caso...",
  [1152359322164736] = "Esta é a igreja que você mencionou? Ele é...",
  [1152359322164480] = "Caramba! Não importa o que aconteça, eu tenho que ir ver. Mencionou uma igreja agora há pouco, e acho que sei onde ela fica.",
  [1152359322164224] = "Acabou de dizer avanço? Parece que realmente há um Beyonder por trás disso causando problemas.",
  [1152359322163968] = "Parece uma criação da Igreja do Vapor. Estranho, como a Igreja se envolveu?",
  [1152359322163712] = "Esse cara está guardando as mercadorias aqui?",
  [1152359322163456] = "Essas pessoas... todas morrerão... todas morrerão...",
  [1152359322163200] = "Igreja... ritual... avanço...",
  [1152359322162944] = "Vamos entrar e ver quais ratos estão causando problemas.",
  [1152359322162688] = "Conheço todas as mercadorias que entram e saem daqui, mas nunca as vi. Provavelmente são essas balas.",
  [1152359322162432] = "Várias remessas chegaram à fábrica recentemente. A quantidade de cada vez não era grande e eles eram enviados para toda Tingen.",
  [1152359322162176] = "Isso mesmo. Estou investigando as mercadorias aqui.",
  [1152359322161920] = "Esta é a fábrica de aço?",
  [1152359322161664] = "Vamos. Precisamos acelerar.",
  [1152359322161408] = "A polícia também está metida nisso... Droga, o que esses desgraçados da delegacia estão tentando fazer!",
  [1152359322161152] = "<P_Heart> (Isso parece algum tipo de ritual) </>",
  [1152359322160896] = "Alguém está espalhando essas balas e fazendo as pessoas matarem de acordo com suas exigências.",
  [1152359322160640] = "Só isso.",
  [804913647078656] = "Sim.",
  [822505833666560] = "Parabéns.",
  [822505833500672] = "Boa tarde, {{PlayerName}}, tive a premonição de que você apareceria.",
  [1152359322160384] = "Espere por uma oportunidade de entrar correndo mais tarde e ver se consegue descobrir alguma coisa.",
  [1152359322160128] = "Suspeito que ele tenha algumas evidências importantes sobre ele. A Força de Segurança e a polícia estão trabalhando juntas para silenciá-lo!",
  [822505833449984] = "Chegou a hora marcada, meu ouvinte e testemunha desta história.",
  [1152359322159872] = "Não, a delegacia está apenas sob lei marcial, e eles deram uma ordem estrita: apenas fiquem de guarda, não intervenham. A Força de Segurança do Parlamento está a tratar do assunto sozinha.",
  [822505833286144] = "Depende de você, eu... não tenho mais forças...",
  [822505833111552] = "O “Homem Honesto de Tingen” diz que as nossas normas de segurança são como as barbas postiças numa casa de ópera – boas de se ver, mas inúteis.",
  [822505833170944] = "Isso não é nada importante.",
  [822505833004032] = "Almirante do navio do Iceberg? Eu ouvi alguns rumores.",
  [1152359321306624] = "Há algum evento aqui?",
  [360778595054848] = "Por que o tanque de água está vazio?",
  [360778595267584] = "Hmm... ir para Golden Autumn Lake não parece ter um bom resultado.",
  [360778595239424] = "Mas...",
  [1152359321829888] = "A partir de então, Haji-Ape se tornou o guarda-costas número um de Belle, sempre seguindo-a de perto para sempre.",
  [1152359322159616] = "Então a delegacia está sob lei marcial, preparando-se para prendê-lo?",
  [1152359322159360] = "Este é um serial killer que escapou da Força de Segurança do Parlamento. Ele tem mais de uma dúzia de casos de assassinato em mãos.",
  [1152359322159104] = "<P_Heart> (Entregando um pedaço de papel) </> A delegacia está sob lei marcial. Este é um aviso interno da Força de Segurança do Parlamento.",
  [360778595406336] = "O que?!",
  [360778595307008] = "Eu rezo por seu favor",
  [1152359322158848] = "O clima na entrada da delegacia parece um pouco tenso. O que aconteceu?",
  [1152359322158592] = "Como era de se esperar, parece que o espião da polícia também fez contato com as gangues... Vamos lá! Continue investigando!",
  [1152359322158336] = "<P_Heart> (Entregando uma bala de ouro) </> Isso foi encontrado naquele cara.",
  [1152359322158080] = "Eu me lembro desse cara. Ele é um bandido das 'Luvas Negras', um dos grupos mais violentos entre as três principais gangues. Mas ele não era tão louco antes.",
  [1152359322157824] = "Como um lobisomem poderia estar escondido aqui?",
  [1152359322157568] = "Não estou morto... sou durão. Não posso ajudar muito num momento como este.",
  [1152359322157312] = "Você está bem!",
  [1152359322157056] = "Semelhante à sensação do cemitério, algo está escondido aqui.",
  [1152359322156800] = "Espere, algo não parece certo aqui.",
  [1152359322156544] = "Vamos tentar a sorte e ver se Andy deixou alguma pista.",
  [1152359322156288] = "Você é rápido. Um pouco mais à frente fica a casa ancestral do agente secreto.",
  [1152359322156032] = "Não temos muito tempo. Devemos descobrir a verdade antes que eles o façam.",
  [1152359322155776] = "A última é a siderúrgica; as pistas sobre as balas apontam para lá.",
  [1152359322155520] = "E a entrada da delegacia, onde foi morto.",
  [1152359322155264] = "A casa ancestral do agente secreto. Ele ocasionalmente escondia alguns bens lá.",
  [1152359322155008] = "Você é confiável. Eu não te julguei mal. Vou investigar três lugares a seguir.",
  [1152359322154752] = "Então, o que você precisa que eu faça por você?",
  [1152359322154496] = "Como você pode ver, esta bala é exclusiva da polícia. Não posso confiar em ninguém lá dentro agora.",
  [1152359322154240] = "Droga, eu sabia, essa bala de novo! Deve haver um problema dentro do departamento de polícia!",
  [1152359322153984] = "Vá verificar o cadáver naquele caixão. Esse era o nosso agente secreto. Ele morreu quando voltava para a equipe. Ele deveria ter pistas sobre ele.",
  [1152359322153728] = "É por isso que vim até você. Ouvi dizer que você lidou com assuntos mais complicados. Você pode interpretar isso como uma forma de reconhecimento.",
  [1152359322153472] = "Isso é muito perigoso. Quem exatamente você provocou?",
  [1152359322153216] = "Não tenho certeza... mas tenho a premonição de que o veremos novamente mais tarde.",
  [1152359322152960] = "Então, o que exatamente é esse monstro?",
  [1152359322152704] = "Não fique animado. Pelo menos sua parte traseira ainda está intacta.",
  [1152359322152448] = "Havia um monstro agora há pouco, quase perdi minha vida! Você não mencionou que haveria um!",
  [1152359322152192] = "Esse não é um bom lugar para dormir.",
  [1152359322151936] = "Encontre-me no cemitério amanhã à noite. Lembre-se, não conte a ninguém!",
  [1152359322151680] = "Você poderia dizer isso, mas esta é uma comissão privada.",
  [1152359322151424] = "Você é um policial?",
  [1152359322151168] = "Vamos nos apresentar. Sou Trevor Murphy.",
  [1152359322150912] = "<P_Heart> (Ele descobriu minha identidade? Muito esperto...) </>",
  [1152359322150656] = "Você é da Blackthorn Security Company? Ouvi dizer que você costuma lidar com alguns... casos especiais.",
  [1152359322150400] = "Que bêbado? Droga, não é hora para piadas. Venha e me dê uma mão!",
  [1152359322150144] = "Você é tão bêbado?",
  [1152359322149888] = "<P_Heart> (Pensar que iria encontrá-lo novamente. Talvez ele seja aquela </> <P_Yellow> figura-chave </> <P_Heart> .) </>",
  [1152359322149632] = "<P_Heart> (Este policial parece ser o bêbado de antes.) </>",
  [1152359322149376] = "Observe esse mundo como um espectador num teatro. Se você estiver disposto a tentar fazer algo, talvez possa até trazer a salvação para alguém.",
  [1152359322149120] = "O que devo fazer?",
  [1152359322148864] = "No entanto, como você já encontrou a entrada, é melhor dar uma olhada nesse mundo. Também será benéfico para sua recuperação.",
  [1152359322148608] = "Você poderia entender dessa forma. Suas experiências anteriores podem ter tornado você sensível a essas coisas.",
  [1152359322148352] = "Como um sonho?",
  [1152359322148096] = "Tudo o que acontece lá <P_Yellow> não terá impacto direto na realidade </> .",
  [1152359322147840] = "Origina-se de um lugar oculto - o mundo subconsciente coletivo de Tingen <P_Yellow></>.",
  [1152359322147584] = "Isto foi deixado para trás por um cavalheiro anteriormente.",
  [1152359322147328] = "<P_Heart> (Olhando para a bala dourada em sua mão) </> Sinto algumas espiritualidade flutuações próximas.",
  [1152359322147072] = "Senhorita Justiça, por que está aqui?",
  [1152359322146816] = "Deixe-me pensar. Vamos começar com... o Plano de Recuperação do Anel da Sra. Meg!",
  [1152359322146560] = "Será que a experiência de hoje significa a minha libertação do plano sem fim? É isso mesmo, preciso falar com Heidi e com o pai... mas há coisas mais importantes agora...",
  [1152359322146304] = "... Me desculpe, fui muito impulsivo. Todos os meus planos para hoje foram arruinados, isso não cabe no meu plano...",
  [1152359322146048] = "Já é.",
  [1152359322145792] = "Sempre há um jeito... Papai disse que essas quatro palavras nunca deveriam fazer parte de um plano.",
  [1152359322145536] = "Se forem jogados fora, são jogados fora. Se você se lembrar de amanhã, procure-os; se você não consegue encontrá-los, que assim seja. Sempre há um jeito.",
  [1152359322145280] = "Por que você está me consolando... Joguei fora seus anéis!",
  [1152359322145024] = "O mesmo aconteceu com a proposta. Um dia eu disse: 'Vamos nos casar', e Meg disse: 'Claro', então simplesmente o fizemos. Mais tarde, viemos passar férias no campo de flores. Ela gostou das flores daqui, então ficamos e nos tornamos jardineiros.",
  [1152359322144768] = "Então pare de planejar. Se o tempo estiver bom, aproveite o sol; se chover, durma até tarde. Deixe as preocupações de amanhã para amanhã.",
  [1152359322144512] = "Não está bem... eu planejei propor casamento e Heidi me rejeitou friamente. Planejei encontrar o anel, e o anel estava no meu bolso. Joguei fora sua aliança de casamento e você nem me repreendeu.",
  [1152359322144256] = "Jovem, você está bem?",
  [1152359322144000] = "...Tudo bem, sem plano.",
  [1152359322143744] = "Pare de planejar.",
  [1152359322143488] = "...Vamos. Mas antes de me desculpar, tenho que planejar como dizer isso—",
  [1152359322143232] = "Você acha que, dado o quão tranquilos eles são, eles se importariam com suas ações?",
  [1152359322142976] = "Eles não vão mais me perdoar...",
  [1152359322142720] = "Volte. Você precisa se desculpar com aquele casal de idosos.",
  [1152359322142464] = "Papai vai... me expulsar de casa...",
  [1152359322142208] = "Até preparei o plano de casamento e o plano de educação dos filhos. Tempestades acima, ainda há tantos planos que não fiz – o plano de aposentadoria para nossos pais, o plano de férias, o plano de poupança...",
  [1152359322141952] = "O plano de proposta que fiz foi inútil! O plano para encontrar o anel foi inútil! O plano de estudos que fiz para a escola foi inútil, o plano de exercícios foi inútil...",
  [1152359322141696] = "Você tem ideia do que passei hoje?! Fiz um plano para encontrar a aliança, procurei em todo o campo de flores, passei o dia inteiro rastejando no chão e até joguei fora a aliança de casamento deles, tudo isso enquanto minha própria aliança ficava no bolso o tempo todo!",
  [1152359322141440] = "Não é ótimo?",
  [1152359322141184] = "...Então, quando Heidi jogou o anel, meu coração doeu porque o anel caiu no meu bolso...",
  [1152359322140928] = "Estava no seu bolso o tempo todo?",
  [1152359322140672] = "Este é o meu anel, o anel que procurei o dia todo... no bolso onde guardo meu caderno de planos.",
  [1152359322140416] = "O anel.",
  [1152359322140160] = "...O que é isso?",
  [1152359322139904] = "Perdendo tanto tempo, se eu tivesse seguido meu próprio plano, já teria encontrado o anel há muito tempo! Talvez no pavilhão no meio do lago, talvez na árvore dos desejos...",
  [1152359322139648] = "Olha, meu velho, nossa aliança de casamento está perdida de novo. Não importa, iremos procurá-lo em alguns dias.",
  [1152359322139392] = "Se você não se importa, jogue fora!",
  [1152359322139136] = "Não existe nenhum plano na sua vida?! Isso não é grande coisa?!",
  [1152359322138880] = "Sua aliança de casamento está perdida! E isso não é grande coisa?!",
  [1152359322138624] = "Ah, de qualquer maneira, não é grande coisa; o anel foi comprado casualmente.",
  [1152359322138368] = "Você não disse que se lembrava disso com muita clareza!",
  [1152359322138112] = "Isso aconteceu? Eu esqueci. Tem certeza? Não parece...",
  [1152359322137856] = "Ei, esta não é minha aliança de casamento! Peguei-o debaixo do guarda-roupa semana passada e coloquei-o na caixa de Meg.",
  [1152359322137600] = "Obrigado! Oh! Meu ri... espere, este não é meu anel!",
  [1152359322137344] = "Eu estava prestes a devolvê-los; Eu só queria que ele soubesse que nem todo anel que você procura pode ser encontrado.",
  [1152359322137088] = "Por que você está pegando coisas de outras pessoas? Devolva-os.",
  [1152359322136832] = "Harvey, estes dois estão aqui à procura de um anel.",
  [1152359322136576] = "Seu marido... ainda está vivo...",
  [1152359322136320] = "Já que o anel é tão importante para você, preciso encontrá-lo! Primeiro passo, verifique cada canto do mar de flores; segundo passo, revolva o solo; terceiro passo, peneirar o solo...",
  [1152359322136064] = "Não importa se o anel não for encontrado; o que é importante é que você já o teve.",
  [1152359322135808] = "Entender o quê?",
  [1152359322135552] = "...Sra., eu entendo perfeitamente, não se preocupe, vou formular o plano perfeito!",
  [1152359322135296] = "Seu marido já...",
  [1152359322135040] = "Porque esse foi o último anel que meu marido me deu e lembro-me claramente do padrão.",
  [1152359322134784] = "Como isso é possível!",
  [1152359322134528] = "Parece semelhante, mas não é meu anel.",
  [1152359322134272] = "Senhora, seu anel está aqui!",
  [1152359322134016] = "Tem um ninho de esquilo ali, vamos lá.",
  [1152359322133760] = "Por que não perguntar primeiro: é o plano que é útil ou é a descoberta que é útil?",
  [1152359322133504] = "Você não tem um plano... por que consegue encontrar a direção?",
  [1152359322133248] = "Sr. Edwin, encontrei a direção, siga-me!",
  [1152359322132992] = "Ei! Suas coisas!",
  [1152359322132736] = "Vou encontrar agora!",
  [1152359322132480] = "Pare, meu anel é o mais barato de uma barraca de beira de estrada, com vidro vermelho nele. Quando perdi meu anel, muitas vezes fui tomar sol nos arbustos de flores perto do ninho de esquilo.",
  [1152359322132224] = "Impossível! Sem um plano, não consigo encontrar o anel, e se não conseguir encontrar o anel, minha vida acaba...",
  [1152359322131968] = "Tantos planos? Se você não consegue encontrar, você não consegue encontrar!",
  [1152359322131712] = "Primeiro passo, confirme as características do anel; passo dois, definir o escopo; passo três, crie um cronograma...",
  [1152359322131456] = "Sua aliança de casamento não foi encontrada porque você não tinha um bom plano! Deixe-me fazer isso!",
  [1152359322131200] = "Hmm, eu procuro quando penso nisso, mas acabei pegando um monte de anéis de outras pessoas.",
  [1152359322130944] = "Seu anel também está perdido?",
  [1152359322130688] = "Então vá procurar; encontre minha aliança de casamento há muito perdida e, se você encontrá-la, eu a darei a você.",
  [1152359322130432] = "Devo recuperá-lo!",
  [1152359322130176] = "Olha, aquela caixa de anéis foi toda recolhida no mar de flores. Todo mundo que tem seu anel jogado fora por um amante pensa que sua vida acabou, mas parece que todos ficam bem mais tarde. Não importa quão bom seja o plano, nem sempre funciona no final. Estes são os precedentes.",
  [1152359322129920] = "Anel? Você não é o primeiro a me procurar em busca de um anel.",
  [1152359322129664] = "Com licença, você viu um...",
  [1152359322129408] = "O anel está perto daquela senhora; vá perguntar a ela.",
  [1152359322129152] = "Heidi jogar o anel também não estava nos seus planos.",
  [1152359322128896] = "Ah? Isso não está nos meus planos!",
  [1152359322128640] = "Eu tenho uma pista.",
  [1152359322128384] = "Plano formulado, preciso da sua ajuda!",
  [1152359322128128] = "Dona Meg está bem ali! Ela sempre senta naquele banco ornamentado ali!",
  [1152359322127872] = "O anel foi levado pela Sra. Meg! Que sorte ela tem de receber a benção do mar de flores!",
  [1152359322127616] = "Romântico...",
  [1152359322127360] = "O anel... você não quer dizer o anel romântico que caiu do céu!",
  [1152359322127104] = "...Com licença, você viu um anel cair por aqui?",
  [1152359322126848] = "Ela se foi... não disseram que se você caminhasse pelo caminho em forma de coração em meio ao mar de flores, encontraria seu amante? Estou caminhando há um mês e ninguém se apaixonou por mim!",
  [1152359322126592] = "Shh, estou prestes a encontrar meu amante!",
  [1152359322126336] = "Senhor...",
  [1152359322126080] = "...Você continua com seu plano, eu mesmo vou procurar.",
  [1152359322125824] = "Agir sem um plano reduz a eficiência em mais de quarenta por cento.",
  [1152359322125568] = "Estará escuro quando você terminar seu plano.",
  [1152359322125312] = "Planejar o escopo é o primeiro passo, dividir a grade é o segundo passo e verificar por probabilidade é o terceiro passo...",
  [1152359322125056] = "...Então?",
  [1152359322124800] = "O mar de flores é vasto. Dada a queda do anel da altura do balão de ar quente, considerando o peso, a direção do vento e a trajetória, a área de pouso pode ser reduzida para cinco acres na direção nordeste.",
  [1152359322124288] = "...Tudo bem, vou ajudá-lo a procurar.",
  [1152359322124032] = "<P_Heart> (É tarde demais, não importa o que aconteça!) </>",
  [1152359322123776] = "Esse é um anel de herança de família! Meu pai estipulou que, se eu não tiver feito a proposta com sucesso até os vinte e cinco anos, não poderei herdar o negócio da família e farei vinte e cinco amanhã!",
  [1152359322123520] = "Você não está procurando a Sra. Heidi, mas está com pressa para encontrar um anel?",
  [1152359322123264] = "Agora é hora de encontrar o anel; por favor junte-se ao meu plano.",
  [1152359322122752] = "Mas ela me rejeitou e jogou o anel em mim... Senti uma dor no peito naquele momento, e quando acordei, o anel já havia sumido!",
  [1152359322122496] = "Meu plano para hoje: 9h, o balão de ar quente decola. 9h15, chegada ao melhor local de proposta no mar de flores. 9h30, proposta, Heidi vai às lágrimas. 9:45, coloque o anel na Heidi...",
  [1152359322122240] = "Ah, claro! Eu sou Edwin.",
  [1152359322121984] = "Senhor, você precisa de ajuda?",
  [1152359322121728] = "Heidi! Só por causa de um “Plano Pós-Casamento de Cinquenta Anos”, você quer terminar comigo?!",
  [1152359322121472] = "Eh? O que caiu!",
  [1152359322121216] = "Flores coloridas, caminhos em forma de coração... e românticos balões de ar quente no céu.",
  [1152359322120704] = "Não, você está linda, Sra. Ella.",
  [1152359322120448] = "O que está errado? Minha maquiagem está estragada?",
  [1152359322120192] = "...Eu sei, deixe-me ficar sozinho, {Sr.{Sra.|}}.",
  [1152359322119936] = "Comparada com a sua aparência quando estava vivo, Ella sente mais falta do seu sorriso, Sr.",
  [1152359322119680] = "O que? Com que direito você diz isso?",
  [1152359322119424] = "Mas você sabe, não haverá um chapéu novo.",
  [1152359322119168] = "Sim, ele mesmo fez e prometemos fazer um novo juntos.",
  [1152359322118912] = "Esse chapéu é muito importante, não é?",
  [1152359322118656] = "É isso! Obrigado! Posso cumprimentá-lo em perfeito estado!",
  [1152359322118400] = "Esse chapéu foi feito por ele para mim, e até prometemos que quando ele voltasse faríamos um novo.",
  [1152359322117888] = "Vou transmitir isso para você.",
  [1152359322117632] = "Mas eu estava muito fraco e ele não conseguia ouvir minha voz.",
  [1152359322117376] = "Quero que ele volte a ser aquele homem um pouco rude, mas com um sorriso gentil.",
  [1152359322117120] = "<P_Heart> (Então, durante esses cinco anos, \"Ayla\" à beira do lago era na verdade o marido disfarçado?) </> ... Sim, ele disse que queria se vestir como a versão mais bonita de si mesmo.",
  [1152359322116864] = "Vestindo minhas roupas, penteando os cabelos, como se nunca tivesse saído.",
  [1152359322116608] = "Hmm, Riel ainda está esperando, certo? Aquele idiota.",
  [1152359322116352] = "Você é... Ella?",
  [1152359322116096] = "-Finalmente! Cinco anos! Alguém pode me ouvir!",
  [1152359322115840] = "Eu posso ouvir você.",
  [1152359322115584] = "Tem alguém aí? Alguém pode me ouvir?",
  [1152359322111744] = "Leia; se você não tem medo em seu coração, então esperaremos por você ao toque do sino da meia-noite. Que a Meia Noite proteja você.",
  [1152359322111488] = "Este é o convite para a Sociedade de Poesia Requiem.",
  [1152359322111232] = "Mas se o seu coração estiver preparado, então a Deusa verá a sua piedade.",
  [1152359322110976] = "Isto requer coragem. Enfrentar a morte, abraçar a escuridão, guardar segredos... isso não é fácil.",
  [1152359322110720] = "E nós os confortamos com a poesia, os abraçamos com a noite e os libertamos com a paz.",
  [1152359322110464] = "Neste mundo barulhento, as pessoas e os espíritos são atormentados por preocupações, presos pelo horror e perturbados por segredos.",
  [1152359322110208] = "Acreditamos que a morte não é o fim, mas o início de outro tipo de paz.",
  [1152359322109952] = "Sim, a Sociedade de Poesia Requiem. Sob o olhar da Deusa da Noite Eterna, somos Seus cantores mais leais.",
  [1152359322109696] = "Caminhamos na fronteira entre a vida e a morte, trazendo paz aos que não dormem, cantando poemas para os mortos e guardando segredos em silêncio.",
  [1152359322109440] = "Venho da Requiem Poetry Society; este é um grupo formado por crentes devotos da Deusa da Noite Eterna.",
  [1152359322109184] = "Padre? Não, sou apenas alguém que canta para os mortos no cemitério.",
  [1152359322108928] = "Você veio. Todos aqueles que recebem essa carta têm almas favorecidas pela Deusa.",
  [1152359322108672] = "Que a Meia Noite proteja você. As almas perdidas acabarão por encontrar o seu lugar de descanso aqui.",
  [1152359322108416] = "Se você não se perder, quebrarei sua vassoura quebrada.",
  [1152359321554176] = "Deixe-a ir, Lanster.",
  [1152359322107648] = "Eu não tenho dinheiro.",
  [1152359322107392] = "Não fale bobagem! Cinco libras por mês, entregue!",
  [1152359322107136] = "Ah, você é muito intrometido, assim como as gaivotas nas docas.",
  [1152359322106880] = "Velho, esta rua nos pertence. Se você quiser varrer aqui, terá que pagar.",
  [1152359322106624] = "<P_Heart> (Coça a cabeça) </> Acontece que eu entendo o coração de uma criança.",
  [1152359322106368] = "Obrigado! Se não fosse por você, não sei o que teria acontecido!",
  [1152359322106112] = "Reuben está esperando por essas palavras há muito tempo.",
  [1152359322105856] = "Contanto que papai realmente faça isso, não ficarei mais zangado com papai.",
  [1152359322105600] = "É... é culpa do papai. Eu não deveria querer abrir tudo.",
  [1152359322105088] = "...Não vou mais assistir.",
  [1152359322104832] = "Pai, meu diário...",
  [1152359322104576] = "Rubens, você...",
  [1152359322104320] = "<P_Heart> (Animadamente) </> Eu não conseguia parar de me preocupar, então corri para verificar...",
  [1152359322104064] = "Ruben! Meu filho, você está bem?",
  [1152359322103808] = "Ele já fez isso antes... Na verdade, ele está melhor do que antes. Normalmente, ele nunca daria um passo para trás.",
  [1152359322103552] = "Pelo menos... ele se comprometeu agora há pouco. No passado, ele poderia ter arrombado a porta, certo?",
  [1152359322103296] = "Ele realmente mudará?",
  [1152359322103040] = "Você gostaria de tentar dar uma chance a ele?",
  [1152359322102784] = "...Mas meu pai simplesmente não entende.",
  [1152359322102528] = "A arte de arrombar fechaduras nunca teve como objetivo provar o quão bom alguém é; Muitas vezes digo isso a mim mesmo.",
  [1152359322102272] = "<P_Heart> (Hesitante) </> ...Por que você não é como os outros, dizendo que o problema é meu? Dizendo que estou sendo irracional?",
  [1152359322102016] = "<P_Heart> (Acena com a cabeça) </> Seu pai... está realmente errado.",
  [1152359322101760] = "Só quero que ele saiba... que nem todas as fechaduras devem ser abertas.",
  [1152359322101504] = "Você se trancou para que ele soubesse como é não conseguir abrir alguma coisa?",
  [1152359322101248] = "<P_Heart> (Até as crianças precisam de espaço pessoal.) </>",
  [1152359322100992] = "Meu diário, minhas gavetas, ele tem que abrir todas. Ele diz que é o seu ofício e tem muito orgulho disso.",
  [1152359322100736] = "Papai também é assim. Ele diz que o trabalho do serralheiro é abrir tudo e não há fechadura que ele não consiga abrir.",
  [1152359322100480] = "...O que?",
  [1152359322100224] = "<P_Heart> (Zombaria) </> Outra pessoa que pensa que pode abrir qualquer coisa?",
  [1152359322099968] = "Sim, estava trancado. Mas tenho algumas... técnicas que ainda estou aprendendo.",
  [1152359322099712] = "Como, como você entrou?! A porta não estava trancada...",
  [1152359322099456] = "Ruben? Você está bem?",
  [1152359322099200] = "<P_Heart> (Atordoado) </> Quer dizer, ele não quer... na nossa frente? Tudo bem. Vou deixar isso para você.",
  [1152359322098944] = "Por favor, saia primeiro e deixe-o se acalmar. Ficarei aqui e se acontecer alguma coisa te ligo imediatamente. Além disso... <P_Heart> (Sussurrando) </> algumas coisas podem não ser convenientes de serem ditas na frente dos pais.",
  [1152359322098688] = "Vá embora, nunca mais quero te ver!",
  [1152359322098432] = "Eu não vou embora! Meu próprio filho, eu...",
  [1152359322098176] = "<P_Heart> (Hesitando) </> Mas...",
  [1152359322097920] = "Senhora, a criança precisa se acalmar. Você e seu marido deveriam esperar mais longe; Vou ficar atento aqui e pensar em outras maneiras.",
  [1152359322097664] = "<P_Heart> (Embora eu tenha uma maneira de entrar diretamente na sala, é melhor não deixá-los ver. Preciso afastá-los.) </>",
  [1152359322097408] = "Eu... eu entendo o temperamento das crianças; talvez eu possa ajudar.",
  [1152359322097152] = "Esta criança... ele está se punindo só porque li seu diário?",
  [1152359322096896] = "Reuben se trancou lá dentro há quinze minutos! Ele tem medo do escuro; se isso continuar, ele não conseguirá respirar!",
  [1152359322096128] = "<P_Heart> (Chorando) </> Ruben, abra a porta! Papai sabe que ele estava errado!",
  [1152359322095872] = "<P_Heart> (Irritado) </> Droga... Eu mesmo instalei essa fechadura e agora ela não abre...",
  [1152359322095616] = "Não, não! Eu vou mudar! Vou virar uma nova página!",
  [1152359322095360] = "Ainda quer extorquir dinheiro?",
  [1152359322095104] = "Não ousarei, não ousarei!",
  [1152359322094848] = "Ainda quer tentar enganar as pessoas?",
  [1152359322094592] = "Uau-",
  [1152359322094336] = "<P_Heart> (Com um tom soluçante) </> Com certeza voltarei!",
  [1152359322093824] = "Eu vou lembrar de você, é só esperar!",
  [1152359322093568] = "Exatamente, desta vez eu nem toquei em você com um único dedo.",
  [1152359322093312] = "Ai, você caiu e está culpando o terreno irregular?",
  [1152359322093056] = "Você, você, você... jogando sujo! Isso não é justo!",
  [1152359322092800] = "Ai!",
  [1152359322092544] = "Você apenas espere!",
  [1152359322092288] = "Ele caiu sozinho; vimos isso claramente.",
  [1152359322092032] = "<P_Heart> (Sussurrando) </> Ele está tão longe, mas tem a coragem de dizer isso...",
  [809242973969664] = "Recentemente descobri uma nova receita de peixe seco, usando algumas ervas especiais e técnicas de defumação. Estou extremamente satisfeito com ele, mas não basta apenas eu dizer que é bom.",
  [809242974037248] = "Oh sim! Meu caderno foi levado pelo vento e as páginas estão flutuando por toda parte.",
  [1152359322091776] = "<P_Heart> (Levanta-se, percebendo algo) </> Você, você está pregando peças!",
  [1139165182859008] = "Poderíamos ter simplesmente roubado você, mas estávamos dispostos a pagar-lhe um centavo.",
  [1152359322091520] = "Ai! Como poderia estar tão longe? Eu, eu nem toquei nele...",
  [1152359322091264] = "<P_Heart> (Experimente a especialidade do Mago - a Técnica de Queda.) </>",
  [1152359322091008] = "<P_Heart> (Olhos iluminam) </> Ah, algo bom hoje!",
  [1152359322090752] = "<P_Heart> (Entendi! Já que ele gosta tanto de ficar deitado no chão... deixe-o mentir o quanto quiser.) </>",
  [1152359322090496] = "<P_Heart> (Se esse tipo de pessoa não aprender uma lição, parece que ele não aprenderá.) </>",
  [1152359322090240] = "Procurei o patrulheiro, mas ele rola duas vezes e se levanta como se nada tivesse acontecido.",
  [1152359322089984] = "<P_Heart> (Sussurrando) </> Esse canalha de novo... ele me roubou cinco soli no mês passado.",
  [1152359322089728] = "Eu nem toquei nele! Ele caiu sozinho!",
  [1152359322089472] = "Ai, você esbarrou em mim! Minha perna não se move! Pagar! Cinco sóis!",
  [1139165182587648] = "Opções",
  [1152359322089216] = "De agora em diante, esta arte marcial será chamada— <P_Yellow> I Want You Rat </>! Artes marciais!",
  [1152359322088960] = "Seu corpo deve ser como o de um rato: rápido, pequeno e ágil. Se você não pode vencê-los, corra; se você não puder ultrapassá-los, circule.",
  [1152359322088704] = "Este movimento é bom. Se você não pode vencê-los, desgaste-os; quando eles estiverem exaustos, você vence.",
  [1152359322088192] = "Ao se esquivar, fique próximo ao chão, dê passos curtos e não pule muito alto; pular expõe seu centro de gravidade.",
  [1152359322087424] = "Bom! Círculo atrás! Tapa na cauda!",
  [1152359322086144] = "<P_Heart> (Falando consigo mesmo) </> O corpo deve ser ágil, o centro de gravidade baixo e você deve circular atrás quando o oponente erra. Este rato... na verdade tem algumas habilidades.",
  [1152359322085120] = "<P_Heart> (Sorri) </> Você me elogia.",
  [1152359322084864] = "<P_Heart> (Exclama maravilhado) </> Simplesmente um mestre em pistolas!",
  [1152359322084608] = "<P_Heart> (Guarda a arma e sorri) </> Você simplesmente não sabe como usá-la.",
  [1152359322084352] = "<P_Heart> (Boca aberta) </> Eu não conseguiria vender essa arma nem por cinco soli!",
  [1152359322084096] = "<P_Heart> (Atordoado) </> ...Acertou?",
  [1152359322083840] = "Nas minhas mãos, não será mais um atiçador de fogo.",
  [1152359322083584] = "<P_Heart> (Risos) </> O cano está enferrujado; você vai devolvê-lo para usar como atiçador de fogo?",
  [1152359322083328] = "Vou levar este.",
  [1152359322083072] = "Ajude-me a queimar esta carta; ela não poderá recebê-lo de qualquer maneira.",
  [1152359322082816] = "Um presente deixado para uma filha é muito importante.",
  [1152359322082560] = "<P_Heart> (Risos) </> Então foi apenas uma questão pequena; Achei que era algo muito importante...",
  [1152359322082304] = "Isso é tudo.",
  [1152359322082048] = "<P_Heart> (Silêncio por um longo tempo) </> Só isso?",
  [1152359322081792] = "\"Quando você era pequeno, você disse que queria um relógio que tocasse, mas eu não suportava comprá-lo. Agora me arrependo.\"",
  [1152359322081536] = "“Papai não te deu nada de bom nesta vida, este relógio é a única coisa que comprei novo.”",
  [1152359322081280] = "\"Querida filha, tem um relógio de bolso na gaveta do papai, sobrou para você.\"",
  [1152359322081024] = "Não me lembro... estou procurando há três meses. Deveria estar na mesa naquele momento...",
  [1152359322080768] = "Onde está a carta? Posso ajudar você a procurar.",
  [1152359322080512] = "Minha filha. Ela se casou e se mudou para o sul. Eu disse que escreveria para contar algo a ela. A carta foi escrita, mas ela faleceu antes que eu pudesse enviá-la.",
  [1152359322080256] = "<P_Heart> (A obsessão de um espírito persistente...) </> Uma carta para quem?",
  [1152359322080000] = "Uma carta. A carta que escrevi para ela. Ela saiu antes que pudesse recebê-lo, e preciso encontrá-lo para queimá-lo para ela.",
  [1152359322079488] = "<P_Heart> (Não olha para cima) </> Não me afaste. Ainda não encontrei. Assim que eu encontrar, irei embora por conta própria...",
  [1152359322079232] = "Você... bem, tudo bem, não há nada valioso dentro de qualquer maneira. <P_Heart> (Puxa uma chave antiga) </> Aqui. Tome cuidado.",
  [1152359322078976] = "<P_Heart> (Isso poderia ser um incidente Beyonder?) </> Você pode abrir a porta e me deixar entrar e dar uma olhada? Talvez eu tenha um jeito.",
  [1152359322078720] = "Eles têm. Eles disseram que poderiam ser ratos. Mas os ratos não vasculham as gavetas.",
  [1152359322078464] = "A polícia esteve aqui?",
  [1152359322078208] = "É este quarto. O velho William morava aqui sozinho e está morto há três meses. Todas as noites você pode ouvir o som de coisas sendo vasculhadas, farfalhando, como se alguém estivesse procurando alguma coisa. É assustador e agora a casa não pode nem ser alugada!",
  [1152359322077952] = "Ir. O ritual está prestes a começar. Lembre-se: ancore-se, não seja engolido pelo abismo.",
  [1152359322077696] = "Eu entendo. Mas o apocalipse está próximo; Devo ser forte o suficiente para caminhar em direção ao meu destino.",
  [1152359322077440] = "Mas carregar o poder de uma divindade requer encarar Seu olhar diretamente. Isto é quase como olhar diretamente para um deus – seu espírito sofrerá um enorme impacto. Se você relaxar um pouco, poderá se perder nos sussurros.",
  [1152359322077184] = "Já recebi a revelação da Deusa; Ela concederá Sua bênção sobre você e permitirá que você use o poder que Ela detém na história.",
  [1152359322076928] = "Sra.",
  [1152359322076672] = "Vá à Catedral de Santa Selena em Tingen; Seu Papa, Arianna, está esperando por você.",
  [1152359322076416] = "A Deusa da Meia Noite. Sua autoridade está ligada ao Rio das Trevas Eternas, e sua bênção pode permitir que esta arma carregue uma verdadeira forma mítica.",
  [1152359322076160] = "A bênção de uma divindade... qual divindade?",
  [1152359322075904] = "<P_Heart> (Voz vinda de cima) </> Está tomando forma. Mas ainda falta o passo final – a bênção de uma divindade.",
  [1152359322075648] = "Bem aqui, funda o casulo com a poeira cinzenta da neblina. Vou abrir a cortina da história para você.",
  [1152359322075136] = "Todos que desejam caminhar em direção ao apocalipse deveriam ter as qualificações para enfrentá-lo.",
  [1152359322074880] = "“Forma de Criatura Mítica” carrega as sombras residuais de certas existências antigas. Ao tecê-lo com a poeira da névoa cinzenta, você pode emprestar brevemente o poder de um Deus.",
  [1152359322074624] = "Eu sei. Você cresceu mais rápido do que eu esperava.",
  [1152359322074368] = "<P_Heart> (Pious) </> Sr. \"O Louco\", eu vim buscar o Casulo Mítico.",
  [1152359322074112] = "Ore ao Sr. “O Louco”. Ele guiará seu caminho adiante.",
  [1152359322073600] = "<P_Heart> (Rindo) </> É por isso que só apareceu depois que você estava forte o suficiente. Isso mostra que o Sr. Louco acredita que você está pronto.",
  [1152359322073344] = "Isso não soa como algo que uma pessoa comum deveria tocar.",
  [1152359322073088] = "Mas esta tentativa é muito perigosa, então você prosseguirá sob nossa vigilância.",
  [1152359322072832] = "O apocalipse está próximo e você ainda está a alguma distância das Sequências altas. O Sr. \"O Louco\" pegou emprestada da história a forma mítica de uma divindade e a projetou no casulo, forjando assim um poder para você que transcende o seu.",
  [1152359322072576] = "Beyonder caminhos também são conhecidos como caminhos divinos; depois de passar para o estágio Semideus acima de Sequência 4, você pode exibir uma forma mítica até certo ponto.",
  [1152359322072320] = "Mítico?",
  [1152359322072064] = "<P_Heart> (Espantado) </> Como esperado de uma criação mítica.",
  [1152359322071808] = "Sim, este casulo... é muito mágico. Isso me guiou até aqui, me deixando vir aqui em busca de respostas.",
  [1152359322071552] = "<P_Heart> (Sorrindo) </> Recebemos a revelação do Sr. \"O Louco\" e sabíamos que você havia obtido o Casulo Mítico.",
  [1152359322071296] = "Boa tarde! Senhorita \"Justiça\", Senhorita \"Mágico\", Senhor \"A Estrela\", por que estão todos aqui?",
  [1152359322071040] = "É esta noite.",
  [1152359322070784] = "<P_Heart> (Sorrindo) </> Está sempre a caminho?",
  [1152359322070528] = "Está a caminho.",
  [1152359322070272] = "Não há necessidade, eu conheço o caminho.",
  [1152359322070016] = "Onde você mora? Eu te acompanho de volta.",
  [1152359322069760] = "<P_Heart> (Então é assim que é ter a confiança de um paciente.) </>",
  [1152359322069504] = "<P_Heart> (Sorriu levemente) </> Obrigado, doutor.",
  [1152359322069248] = "Eu sou psicólogo. Espero que você possa ter uma boa noite de sono.",
  [1152359322068992] = "O que você faz? Por que você ainda está fora até tão tarde?",
  [1152359322068736] = "<P_Heart> (Abrindo os olhos, olhos com bordas vermelhas) </> Obrigado.",
  [1152359322068480] = "Você pode abrir os olhos agora.",
  [1152359322068224] = "<P_Heart> (Silencioso) </> ...",
  [1152359322067968] = "Martin, o que aconteceu naquele dia não foi culpa sua. Você não pôde salvá-lo, mas você se lembra dele. Isso é o suficiente.",
  [1152359322067712] = "Martinho.",
  [1152359322067456] = "Qual o seu nome?",
  [1152359322067200] = "<P_Heart> (Respiração estabilizando gradualmente) </>",
  [1152359322066944] = "Você não está na fábrica agora. Você está na rua. As luzes da rua estão fortes, o vento está fresco. Você está vivo, você está bem.",
  [1152359322066688] = "<P_Heart> (fechando os olhos) </>",
  [1152359322066432] = "<P_Heart> (Suavização de voz) </> Feche os olhos.",
  [1152359322066176] = "Eu sei. Mas não posso esquecer.",
  [1152359322065920] = "Você não poderia salvá-lo.",
  [1152359322065664] = "<P_Heart> (Silêncio por um longo tempo) </> Ele disse \"Dói.\" Ele disse: “Eu não quero morrer”. Ele disse: \"Salve-me\".",
  [1152359322065408] = "O que ele disse?",
  [1152359322065152] = "A caldeira da fábrica explodiu. Meu colega de trabalho estava bem ao meu lado... <P_Heart> (Voz trêmula) </> O ferro derretido caiu e metade de seu corpo desapareceu. Mas ele não estava totalmente morto. Ele ainda estava segurando minha mão, dizendo algumas palavras para mim.",
  [1152359322064896] = "Que dia, o que aconteceu?",
  [519041160706816] = "Onde é isso...",
  [1152359322064640] = "Três meses. Cada vez que fecho os olhos, são os acontecimentos daquele dia.",
  [1152359322064384] = "Há quanto tempo isso está acontecendo?",
  [1152359322064128] = "<P_Heart> (Não olhou para cima) </> Sim.",
  [1152359322063872] = "As coisas que aconteceram recentemente foram muito difíceis para você, não foi?",
  [1152359322063616] = "Então vou começar a apresentação!",
  [1152359322063360] = "<P_Heart> (Atordoado por um momento, olhos ficando vermelhos) </> Emily...",
  [1152359322063104] = "<P_Heart> (Olhando e rindo de repente) </> Então os palhaços são tão fofos. Achei que seriam muito feios.",
  [519041160993536] = "Mãe...",
  [519041160984832] = "Hum...",
  [1152359322062848] = "Claro! <P_Heart> (Fazendo uma reverência) </> O melhor palhaço de Tingen está prestes a trazer a você a maior performance!",
  [519041161093632] = "Noite! De novo!",
  [1152359322062592] = "<P_Heart> (Fraco) </> Você é um palhaço?",
  [1152359322062336] = "Ouvi dizer que alguém aqui quer ver um palhaço?",
  [519041161201664] = "...Suspirar.",
  [1152359322062080] = "Isso também é verdade.",
  [519041161272576] = "EU...",
  [1152359322061824] = "Não. Tenho medo que assim que eu abrir a boca vocês dois fujam.",
  [1152359322061568] = "De qualquer forma, obrigado! No próximo sábado é o nosso primeiro encontro, quer vir como testemunha?",
  [1152359322060032] = "Embora seja muito imponente, é realmente terrível de ouvir.",
  [519041161456384] = "Certamente revelará um sorriso puro aos mortos:",
  [519041161429760] = "E então?",
  [519041161470464] = "Finalmente, o chefe cortou sua cabeça, subiu ao ponto mais alto e se tornou o grande caçador de dragões!",
  [519041161494784] = "Você veio aqui quando era criança?",
  [1152359322058496] = "Vá até a delegacia para recuperar o dinheiro que foi fraudado.",
  [1152359322058240] = "Ele parece pronto para pular, como devo ajustar seu humor?",
  [1152359322057984] = "Heh... você venceu. Mas você nunca esquecerá... o sabor da noite passada.",
  [1152359322057728] = "Eu vejo, escondidas sob os movimentos ágeis e poderosos estão garras afiadas; este é o Grande Balanço do Gato!",
  [1152359322057472] = "Deve haver algum mistério nisso...",
  [1152359322057216] = "Wuu wuu, eu vou retribuir, mas deixe-me voltar e lavar minhas calças primeiro...",
  [1152359322056960] = "Meu dinheiro – existe algum professor assim no mundo!",
  [1152359322056448] = "Hmm, parece que a fórmula do 'Trickmaster' não será útil por um tempo, vamos dar uma olhada nisso juntos.",
  [1152359322056192] = "Mas a verdade é que essa arrogância me fez ficar preso na parede e me fez esquecer que um “Aprendiz” precisa aprender humildemente com seu professor.",
  [1152359322055936] = "Achei que, por mais secreto que fosse um lugar, contanto que eu pudesse \"Abrir a Porta\", eu poderia entrar e sair quando quisesse.",
  [1152359322055680] = "Não está feliz mesmo depois de sair? Você precisa que eu coloque você de volta?",
  [1152359322055168] = "O que! Não, não-",
  [1152359322054912] = "Não tem outro jeito, Carmen, eu vou encontrar o Vigias Noturnos para você.",
  [1152359322054656] = "Realmente? Vou sair imediatamente... espere, quem acreditaria nisso!",
  [1152359322054400] = "Carmen, os materiais de avanço para \"Trickmaster\" estão nos trilhos do trem!",
  [1152359322054144] = "Por que você está agindo como meu professor! Não, ainda não consigo sair!",
  [1152359322053888] = "Carmen, na verdade estou um pouco decepcionada com você. Quando eu tirei você da parede, foi porque eu esperava que você pudesse dar tudo de si e crescer rapidamente...",
  [1152359322053632] = "<P_Heart> (Como posso tirar Carmen da parede?) </>",
  [1152359322053376] = "Já tentei, mas ainda não consigo sair, suspiro. Sempre ficando preso na parede, até duvido se fui talhado para ser um “Aprendiz”...",
  [1152359322053120] = "Este deveria ser o corpo de Carmen... Carmen, você pode sair sozinha?",
  [1152359322052864] = "Agora minhas calças também estão molhadas, alguém está jogando água fria em mim! Por favor me ajude rápido, só tenho uma calça!",
  [1152359322052608] = "Meu corpo está próximo... hmm? Desde agora, minhas roupas estão frias, como se estivessem encharcadas em água fria?",
  [1152359322052352] = "A propósito, o que eu troquei foi uma fórmula para um 'Trickmaster'. Se você estiver disposto a me ajudar, eu lhe direi a fórmula.",
  [1152359322052096] = "Por favor, você pode encontrar meu corpo e encontrar uma maneira de resgatá-lo?",
  [1152359322051840] = "Então... o que você precisa que eu faça?",
  [1152359322051584] = "Preso? Isso é perfeito, tenho bastante tempo, posso assistir devagar.",
  [1152359322051328] = "É uma longa história. Acabei de fechar um negócio de 300 libras e só queria sair rapidamente... e então fiquei preso!",
  [1152359322051072] = "Por que você é apenas uma cabeça agora?",
  [1152359322050304] = "<P_Heart> (Espero que outra bunda com um buraco não apareça na parede próxima...) </>",
  [1152359322050048] = "Minhas calças realmente estão rasgadas! Tenho que voltar rápido, o mais rápido que puder! Adeus!",
  [1152359322049792] = "Mas ainda tenho que agradecer por me contar como é “Open Door” com um babuíno; o professor não ensinaria essas coisas... espere.",
  [1152359322049536] = "Quando usei \"Open Door\" agora há pouco, ouvi um som parecido com o de um cachorro latindo; acabou sendo esse babuíno, droga!",
  [1152359322049024] = "Talvez eu devesse colocar em prática o que aprendi; afinal, sou um \"Aprendiz\"...",
  [1152359322048768] = "Hiss, eu estudei, mas nunca tentei.",
  [1152359322048512] = "Carmen, você já tentou atravessar uma parede carregando uma criatura viva?",
  [1152359322048256] = "Meu Deus! Suas calças têm um buraco enorme, o babuíno vai roer sua bunda!",
  [1152359322048000] = "<P_Heart> (O babuíno ainda está brincando... como posso tirar Carmen da árvore?) </>",
  [1152359322047744] = "Por favor me ajude a procurá-lo, está bem na árvore ao meu lado!",
  [1152359322047488] = "... Pontudo, como um dedo? Espere, está começando a me dar um tapa!",
  [1152359322047232] = "Que coisa? Você pode sentir isso? <P_Heart> (Só ter metade do corpo é muito assustador, é melhor ajudar até o fim...) </>",
  [1152359322046976] = "Acabei de usar a \"Porta Aberta\" do nosso Aprendiz no chão, enquanto estava em uma árvore, e fiquei preso. Agora tem uma coisa desconhecida cutucando minha bunda...",
  [1152359322046720] = "Ah... olá, eu realmente queria que minha bunda tivesse chegado comigo...",
  [1152359322046464] = "A propósito, Leonard me pediu para dar aquele buquê de margaridas Sevia para Melissa. Você poderia levá-los para ela para nós?",
  [1152359322046208] = "Nos primeiros dois anos após a morte de meu pai, o simples fato de passar pelo cruzamento da Blackthorn fez meu peito sentir um aperto. Melissa é mais forte que eu...",
  [1152359322045952] = "<P_Heart> (Olhando para a foto do grupo na parede) </> Não admira que Leonard e Frye tenham encontrado desculpas para escapar.",
  [1152359322045696] = "Ela... ela disse que Blackthorn sempre a lembra do irmão, então ela não apareceu.",
  [1152359322045440] = "Mas onde está Melissa? Ainda quero ver se ela ficou mais alta depois de ir para a universidade; Espero que ela não seja muito mais alta que eu.",
  [1152359322045184] = "Aqui! Acabei de embrulhá-los.",
  [1152359322044928] = "Estou aqui para comprar algumas coisas para Melissa. Leonard encontrou as plantas do relógio que precisava para sua tese de graduação.",
  [1152359322044672] = "Lembro que você está de licença hoje, por que tem tempo de vir para a empresa? Não seja como Frye, que nunca sai do trabalho, nunca faz uma pausa e quase trata a empresa como sua casa!",
  [1152359322044416] = "Rozanne, bom dia!",
  [1152359322044160] = "Eu me pergunto se, depois que tal história for escrita, aquelas fábricas que se preocupam com sua reputação ainda vão querer se associar a você...",
  [1152359322043904] = "Você, você...",
  [1152359322043648] = "Ah, certo, por acaso conheço um escritor famoso. Ela definitivamente estaria interessada em um tópico como este.",
  [1152359322043392] = "Os contratos para estas duas crianças são completamente ilegais e inválidos. Posso levá-los embora a qualquer momento. Ou você quer que suas ações apareçam nos jornais?",
  [1152359322043136] = "Você não apenas explora ilegalmente o trabalho infantil, mas também é suspeito de abuso infantil. A doença de Jem e os ferimentos em Dodge são a melhor prova.",
  [1152359322042880] = "Vá em frente, Dodge. Desejo a todos o melhor!",
  [1152359322042624] = "{{PlayerName}}... vou lembrar disso. Obrigado, {{PlayerName}}!",
  [1152359322042368] = "Claro. Meu nome é {{PlayerName}}.",
  [1152359322042112] = "<P_Heart> (Respiração profunda) </> Se não fosse por você, poderíamos ter ficado presos naquela chaminé estreita e suja para sempre. Quero saber seu nome... posso?",
  [1152359322041856] = "Você pode aprender outra coisa, se tornar um aprendiz, ou... o que quer que seja. Com sua inteligência e diligência, você não passará fome.",
  [1152359322041600] = "Realmente? Sinto que estou sonhando. Se eu acordar... onde mais Jem e eu podemos ir? Nós... não podemos voltar.",
  [1152359322041344] = "Não, criança. Na catedral você não precisa fazer esse tipo de trabalho perigoso. Você pode ficar aqui em segurança até Jem melhorar.",
  [1152359322041088] = "Senhor... há alguma chaminé na catedral que precise de limpeza?",
  [1152359322040832] = "Ele irá. O médico irá curá-lo. Acredite que ele definitivamente vai melhorar.",
  [1152359322040576] = "Jem pode realmente melhorar?",
  [1152359322040320] = "Por favor, fique tranquilo, iremos buscar Jem daqui a pouco e acomodar essas duas pobres crianças.",
  [1152359322040064] = "Deixe-me pensar... vamos primeiro à Catedral de Santa Selena; pelo menos podemos encontrar um médico para Jem.",
  [1152359322039808] = "Para onde podemos ir agora?",
  [1152359322039552] = "Você... você está certo. Talvez eu não devesse ter contado com Rex desde o início. Uma vez que não fôssemos mais úteis, ele teria nos abandonado sem pensar duas vezes...",
  [1152359322039296] = "Dodge, está tudo bem agora. Você não será mais ameaçado por Rex.",
  [1152359322039040] = "Pegue-os, apenas pegue esse maldito contrato e saia da minha vista!",
  [1152359322038784] = "Vou levar essas duas crianças comigo.",
  [1152359322038528] = "Não há raciocínio com alguém como você!",
  [1152359322038272] = "<P_Heart> (Calma, calma... Rex está acostumado a explorar brechas legais, tenho que aproveitar isso.) </>",
  [1152359322038016] = "Você... você nunca pretendeu que Jem vivesse!",
  [1152359322037760] = "Pelo menos eu dei dinheiro a eles. E você? O que você pode fazer por eles? Criá-los para o resto de suas vidas?",
  [1152359322037504] = "E daí se ele viver? Comprar uma criança saudável é muito mais barato que tratamento médico. Sem falar que eles já estão ficando grandes demais e logo serão inúteis...",
  [1152359322037248] = "Por que você não pagou os salários conforme combinado? Você sabe muito bem que o dinheiro foi para o tratamento que salvou a vida de Jem.",
  [1152359322036992] = "O quê, não gosta do que vê?",
  [1152359322036736] = "Eu... eu vou ouvir você. Estou disposto a confiar em você.",
  [1152359322036480] = "Deixe-me tentar falar com ele novamente. Se ele se recusar a ceder, quais são seus planos?",
  [1152359322036224] = "Wuu wuu... {Sr.{Sra.|}}, o que devo fazer?",
  [1152359322035968] = "Por que você está chorando? Você mesmo causou isso!",
  [1152359322035712] = "Metade... dezoito centavos? Isso não será suficiente para nada...",
  [1152359322035456] = "Perdeu? Em seguida, deduza outra metade.",
  [1152359322035200] = "<P_Heart> (Envergonhado) </> Pá? Eu, eu perdi...",
  [1152359322034944] = "Você fez no máximo metade do trabalho e quer todo o dinheiro? Sonhe! A propósito, onde está sua pá?",
  [1152359322034688] = "Senhor, isso, não foi isso que combinamos...",
  [1152359322034432] = "Finalizado? Considere-se com sorte... Aqui estão seus três xelins.",
  [1152359322034176] = "Sr. Rex, eu... terminei tudo.",
  [1152359322033920] = "Vamos, vamos sair desse inferno e encontrar o Rex!",
  [1152359322033664] = "Não peça desculpas. A chaminé já está desobstruída e as ferramentas podem ser substituídas. Sua segurança é o que mais importa.",
  [1152359322033408] = "Eu estava com tanta pressa que deixei cair a pá lá dentro e não tive tempo de tirar o resto da fuligem... me desculpe...",
  [1152359322033152] = "Tosse, tosse... estou bem! Mas agora mesmo, quando abri a fuligem bloqueada, a fumaça saiu e tive que voltar correndo...",
  [1152359322032896] = "Você está machucado de novo?",
  [1152359322032640] = "Eu vou te puxar para cima!",
  [1152359322032384] = "Tosse, tosse... {Sr.{Sra.|}}, estou de volta, cheguei à saída...",
  [1152359322032128] = "Dodge, como você está? Você está bem?",
  [1152359322031872] = "<P_Heart> (Não há tempo para discutir, tenho que tirar Dodge primeiro!) </>",
  [1152359322031616] = "Sobre o que você está gritando? Ainda não há movimento? Se ele realmente morrer lá, quem terá problemas sou eu, hmph...",
  [1152359322031360] = "Isso é assassinato!",
  [1152359322031104] = "Há quanto tempo você está demorando? Estou com pressa para chegar ao trabalho! Vou apenas queimar um pouco de fumaça para acabar com aquele pirralho.",
  [1152359322030848] = "Você está cego? Você não vê que alguém está limpando a chaminé?",
  [1152359322030592] = "<P_Heart> (Posso usar areia e terra para enterrar a pilha de carvão! Isso é mais seguro!) </>",
  [1152359322030336] = "<P_Heart> (Não, despejar água pode não apagar o fogo e é fácil criar muito vapor, o que escaldaria Dodge.) </>",
  [1152359322030080] = "<P_Heart> (Devo apagar o fogo rapidamente, o que devo usar?) </>",
  [1152359322029824] = "...Tudo bem, estou disposto a confiar em você. Vamos começar, deixe-me pensar...",
  [1152359322029568] = "Bem... eu tenho meus próprios métodos, pelo menos o suficiente para garantir que você não se perca. Você está disposto a confiar em mim?",
  [1152359322029312] = "<P_Heart> (Olhos arregalados) </> Você quer ajudar? Realmente? Mas você está lá fora, como pôde...",
  [1152359322029056] = "Eu entendo. Deixe-me ajudá-lo de fora; Posso guiá-lo e você pode me ordenar que ajude.",
  [1152359322028800] = "<P_Heart> (Entendo, Dodge não tem um \"olho\" que possa guiá-lo. Talvez... simples adivinhação possa preencher essa lacuna.) </>",
  [1152359322028544] = "Derrubo a fuligem que é dura como pedra. Sem ele, temo não conseguir encontrar a saída...",
  [1152359322028288] = "Jem... os ouvidos e o cérebro dele são melhores que os meus. Ele me diz onde a fuligem se acumulou e que caminhos laterais não devo seguir.",
  [1152359322028032] = "Dodge, entendo que você deve receber esse dinheiro. Mas ainda é muito perigoso deixar você entrar assim. Como você costuma fazer isso?",
  [1152359322027776] = "<P_Heart> (Posso perguntar como posso ajudá-lo. Comigo lá fora, pelo menos ele pode se sentir mais à vontade.) </>",
  [1152359322027520] = "<P_Heart> (Ele não acredita que possa escapar. Para ele, a maior esperança é limpar as chaminés e conseguir esse dinheiro que salva vidas. Mas descer sozinho é muito perigoso, nesse caso... ) </>",
  [1152359322027264] = "Mesmo se sairmos daqui, para onde podemos ir? Não sabemos fazer nada, somos magros e pequenos e nenhuma fábrica quer crianças assim.",
  [1152359322027008] = "Obrigado... mas acho que ainda preciso terminar o trabalho de hoje. Só depois de receber o dinheiro poderei consultar um médico. Este é o caminho mais rápido.",
  [1152359322026752] = "E o Jem? Se eu fugir, Rex definitivamente vai descontar sua raiva nele. Ele não pode correr...",
  [1152359322026496] = "Não, {Sr.{Sra.|}}, fomos comprados por ele no asilo... Não quero voltar para um lugar como esse. Eles só se preocupam em vender crianças; eles não se importam com o tipo de pessoa para quem os estão vendendo!",
  [1152359322026240] = "O que Rex está fazendo é ilegal. Deixe-o, você pode ir para o asilo ou para a igreja, pelo menos você não vai mais apanhar.",
  [1152359322025984] = "E mesmo que desta vez eu esteja salvo, e da próxima vez? A doença do meu irmão não é algo de um dia, nós... nem sempre podemos contar com a gentileza de estranhos.",
  [1152359322025728] = "S-sério? Eu... não, não posso, não posso pegar coisas de graça. E...",
  [1152359322025472] = "Eu pago pelo médico. Quanto você precisa?",
  [1152359322025216] = "Mas se eu não conseguir ganhar dinheiro, o Jem morrerá. {Sr.{Sra.|}}, ele vai morrer, o que devo fazer...",
  [1152359322024960] = "Para ganhar mais dinheiro para o tratamento do Jem, tenho que trabalhar sozinho. Mas eu não consigo lidar com isso sozinho... assim como antes, quase caí para a morte na chaminé...",
  [1152359322024704] = "Mal consigo me espremer agora. Assim como Jem, às vezes espero poder crescer rápido e melhorar, mas também tenho medo de crescer...",
  [1152359322024448] = "E você? Você também vai crescer.",
  [1152359322024192] = "Mas crescer significa que não cabemos mais nessas pequenas chaminés. Não sabemos fazer mais nada além de limpar chaminés. O Sr. Rex não nos sustentará de graça, e crescer significa... ser inútil.",
  [1152359322023936] = "Crescer não é uma coisa boa? Você pode trabalhar mais e ganhar mais dinheiro.",
  [1152359322023680] = "Ele disse que está crescendo e está feliz e triste.",
  [1152359322023424] = "Para que mais serve?",
  [1152359322023168] = "Mas o Jem disse que não poderá mais trabalhar comigo, e não é só por causa da doença...",
  [1152359322022912] = "Jem inalou muito pó de carvão, está muito doente, o médico disse que ele deve ficar alguns dias no hospital.",
  [1152359322022656] = "Meu irmão Jem e eu trabalhamos para o Sr. Rex, limpando chaminés.",
  [1152359322022400] = "O que aconteceu? Ele costuma te tratar assim?",
  [1143563228319488] = "Obrigado.",
  [1143563228288768] = "Enterrado com honras por exceder a contagem de palavras",
  [1143563229128448] = "Olá, convidado especial.",
  [1152359322022144] = "Obrigado, pessoa gentil...",
  [1152359322021888] = "Ouça, Dodge, se você não terminou a limpeza até escurecer... espere!",
  [1152359322021632] = "Hmph... você venceu...",
  [1152359322021376] = "Adivinhe de que lado a lei ficará? Um transeunte sóbrio que testemunhou tudo ou um bêbado perigoso?",
  [1152359322021120] = "Abuso infantil e... exploração do trabalho infantil, certo? Se eu ouvi corretamente.",
  [1152359322020864] = "O que isso importa para você? Esse cara é... é comprado por mim, posso fazer o que quiser!",
  [1152359322020608] = "O que quer que tenha acontecido, não há razão para usar violência contra uma criança.",
  [1152359322020352] = "Antes disso, você provavelmente já estará machucado e espancado. Quer tentar?",
  [1152359322020096] = "O-o que você está fazendo? Cuidado, vou ligar para meus irmãos que praticam boxe underground...",
  [1152359322019840] = "<P_Heart> (Passos à frente) </> Desapareça com sua bengala, ou vou ajudá-lo a ficar sóbrio.",
  [1152359322019584] = "Olhe para você. Um bêbado que precisa bater em uma criança para se sentir poderoso.",
  [1152359322019328] = "Hmph... cuidado ou eu trato de você também!",
  [1152359322019072] = "Parar! O que você está fazendo?",
  [1152359322018816] = "Não, senhor! Não!",
  [1152359322018560] = "Pirralho ingrato... não... aja de forma lamentável aqui! Cuidado com meu bastão—",
  [1152359322018304] = "Trabalhe, ganhe dinheiro. Não trabalhe, não tenha dinheiro... minhas regras são tão simples, tão simples que... até uma cabecinha como a sua cheia de pó de carvão pode entender!",
  [1152359322018048] = "\"Não consigo\"? Ha, garoto, eu paguei... paguei para você vir aqui, não para ouvir isso.",
  [1152359322017792] = "Sr. P-por favor! Eu realmente não consigo fazer isso sozinho...",
  [1152359322017536] = "<P_Heart> (Ele parece ser um Beyonder também... e seu estado não é muito bom, vamos perguntar.)",
  [1152359322017024] = "O pêndulo gira no sentido horário, é o lado direito! Está nesta mesa.",
  [1152359322016768] = "O pêndulo gira no sentido anti-horário, não para a esquerda, parece que está na mesa à direita.",
  [1152359322016256] = "O pêndulo gira no sentido anti-horário, não à direita, parece que está na mesa à esquerda.",
  [1152359322016000] = "O pêndulo gira no sentido horário, está na mesa à esquerda!",
  [1152359322015488] = "O pêndulo gira no sentido horário, é a mesa da direita!",
  [1152359322015232] = "O pêndulo gira no sentido anti-horário, não para a esquerda, parece que está na mesa à direita.",
  [1152359322014976] = "\"Ovo da Sorte\" está em...",
  [1152359322014720] = "O pôr do sol de hoje é perfeito para pintar. Eu tenho que voltar, {Sr.{Sra.|}}, adeus.",
  [1152359322014464] = "Sim. Assim como você pode reconhecer a mesma pessoa que viu hoje e ontem, mesmo que a luz e as expressões possam ser diferentes. Eu só... reconheço ovos.",
  [1152359322014208] = "Eu... usei alguns métodos especiais. Você está puramente observando?",
  [1152359322013952] = "Por que não? Seus padrões de fissuras têm ângulos diferentes, a disposição dos pontos pretos, a curvatura da extremidade romba também tem diferenças sutis... não estão todos claramente aí? Você não os viu também?",
  [1152359322013696] = "M-mas... então como você poderia realmente diferenciá-los?",
  [1152359322013440] = "Adivinhação ? Ah, isso é apenas um velho hábito que me ajuda a manter o foco.",
  [1152359322013184] = "Acabei de ver... você também usa adivinhação?",
  [1152359322012928] = "Quando você observa algo milhares de vezes, isso naturalmente deixa uma voz em seu coração. Isso não é loucura, {Sr.{Sra.|}}, isso é apenas... familiaridade.",
  [1152359322012672] = "Estou bem, só um pouco tonto. Preocupado? Ah... muitas pessoas já disseram isso. Minha professora, minha senhoria, até a fazendeira que me vende ovos, é assim que me dou bem com eles.",
  [1152359322012416] = "Sr. Da Vinci, por favor fique... você está bem? Sem ofensa, só que durante a competição, o jeito que você falou com os ovos... me deixou um pouco preocupado.",
  [1152359322012160] = "Vencedores, por favor, vão aos bastidores para receber seu prêmio.",
  [1152359322011904] = "Este Sr. Da Vinci e esta {Sr.{Sra.|}}!",
  [1152359322011648] = "O número do 'Lucky Egg' é 88. O vencedor é...",
  [1152359322011392] = "Posso ver que todos estão ansiosos por isso, então deixe-me revelar a resposta final!",
  [1152359322010880] = "<P_Heart> (Nervoso à toa... é como se ele não tivesse dito nada.) </>",
  [1152359322010624] = "Agora vamos revelar a resposta. O número do 'Ovo da Sorte' é... seu primeiro dígito é 8!",
  [1152359322010368] = "Quem será o vencedor deste desafio ‘Um em Cem Ovos’? Vejo que a senhora aqui está muito confiante, e o senhor ali já está pulando de emoção!",
  [1152359322010112] = "Senhoras e senhores, chegou o momento emocionante!",
  [1152359322009856] = "<P_Heart> (Movimentos estranhos... ele também é um Beyonder?) </>",
  [1152359322009344] = "O tempo está quase acabando, concorrentes que ainda não tomaram uma decisão, por favor, se apressem.",
  [1152359322009088] = "Não existem dois ovos idênticos no mundo!",
  [1152359322008832] = "...Então a competição começa oficialmente! Vamos gritar a famosa citação do Imperador Roselle—",
  [1152359322008576] = "Vaia-",
  [1152359322008320] = "Todo mundo deve ter visto o “Lucky Egg” de hoje; vem de uma galinha com uma identidade especial. Claro, nossa equipe também trabalhou muito para selecionar outros ovos que fossem quase idênticos ao \"Lucky Egg\"!",
  [1152359322008064] = "Uau—",
  [1152359322007808] = "Bem-vindos, competidores, ao nosso desafio 'Um em Cem Ovos'! Sou seu querido anfitrião, Finley, senti muitas saudades de todos vocês!",
  [1152359322007552] = "Finalmente minha vez...",
  [1152359322007040] = "Ele é sempre assim, desenhando ovos lá sozinho, e até fala coisas estranhas para os ovos... Esqueça os outros, aquele ouro de dez mil Sol deve ser meu hoje!",
  [1152359322006784] = "Então sua pele pálida não é por causa do nervosismo, mas por comer ovos? ...Falando nisso, Da Vinci não parece nem um pouco nervoso.",
  [1152359322006528] = "Isso não é nada. Nos últimos seis meses, comi dois por dia, cozidos, fritos... agora, quanto mais ver um ovo, só de ouvir a palavra 'ovo' meu estômago embrulha.",
  [1152359322006272] = "Apenas memorizar a aparência não é suficiente. Passei a última metade do mês estudando os padrões de reflexão das cascas de ovos sob diferentes luzes – a luz oblíqua da manhã e a luz do teto da tarde fazem o mesmo ovo parecer completamente diferente.",
  [1152359322006016] = "Perdi para aquele ovo manchado de marrom claro da última vez, dessa vez até memorizei a distribuição dos orifícios para respirar na casca!",
  [1152359322005248] = "Primeiro, adivinhe o resultado de onde Donnie foi?",
  [1152359322004992] = "Isso depende se o Sr. Shermin está disposto a continuar otimizando a fórmula...",
  [1152359322004736] = "<P_Heart> (Lamentável) </> Será que nunca mais poderemos beber 'Caramel Bomb'?",
  [1152359322004480] = "Entendido...",
  [1152359322004224] = "Ainda na \"Bomba de Caramelo\"? Vocês dois, não orem casualmente para divindades desconhecidas no futuro; é muito perigoso!",
  [1152359322003968] = "Não vá, 'Bomba de Caramelo'...",
  [1152359322003712] = "O que você entende? Ei!",
  [1152359322003456] = "Eu entendo! Eu entendo!",
  [1152359322003200] = "\"Caramel Bomb\" pode limpar o banheiro, isso atende às suas expectativas?",
  [1152359322002688] = "...O banheiro ficou tão limpo!",
  [1152359322002432] = "Não!",
  [1152359322002176] = "Não, não, não, esse tipo de coisa não deveria mais ser vendido, deveria ser jogado no vaso sanitário!",
  [1152359322001920] = "Tudo bem, continue pesquisando, você com certeza conseguirá preparar uma bebida que rivalize com o nível do seu professor!",
  [1152359322001664] = "Sua bebida é muito popular, isso já é bastante impressionante.",
  [1152359322001408] = "Professor, quando você vai voltar!",
  [1152359322001152] = "Isso é tão ruim? Me desculpe, me desculpe, eu realmente não consegui aprender no que o professor era realmente bom!",
  [1152359322000896] = "<P_Heart> (Parece que ficou ainda pior...) </>",
  [1152359322000640] = "Tosse, tosse, tosse—",
  [1152359321999872] = "Vamos beber juntos!",
  [1152359321999616] = "Vou beber primeiro!",
  [1152359321999360] = "Este é o fundador da 'Caramel Bomb', Sr. Shermin. Ele trouxe a última versão melhorada da bebida, vamos todos experimentar!",
  [1152359321999104] = "Vamos lá, vamos encontrar esses dois clientes juntos! Devo testemunhar a cena da degustação com meus próprios olhos!",
  [1152359321998848] = "Tenho a premonição de que, com a sua ajuda, esta garrafa será definitivamente a 'Bomba de Caramelo' perfeita!",
  [1152359321998592] = "Não é nada. <P_Heart> (Ele cometeu um tabu na cozinha... um súbito lampejo de inspiração?) </>",
  [1152359321998080] = "Espere-",
  [1152359321997824] = "Hum? Ainda sobrou um pouco de suco de limão e vinagre branco, não posso desperdiçar, é melhor adicionar!",
  [1152359321997568] = "Terei que sacrificar algumas das bolhas agradáveis...",
  [1152359321997312] = "O limão é uma substância aromática, não causa diarreia.",
  [1152359321997056] = "O cliente espera que a bebida não cause diarreia, para que possamos reduzir a proporção deste ingrediente...",
  [1152359321996800] = "É realmente melhor adicionar menos açúcar.",
  [1152359321996544] = "Isso não está certo; de acordo com a receita do Sr. Shermin, as nozes de cola proporcionam apenas um efeito refrescante.",
  [1152359321996288] = "Os clientes dizem que é muito enjoativo, talvez adicione menos...",
  [1152359321996032] = "Porque também sou um seguidor fiel de 'Caramel Bomb'.",
  [1152359321995776] = "Isso está realmente bem? {Sr.{Sra.|}}, por que você está me ajudando assim?",
  [1152359321995520] = "Não se preocupe, talvez eu saiba por quê. Você tem algum material extra? Vamos melhorar a fórmula juntos?",
  [1152359321995264] = "Realmente deu errado!",
  [1152359321995008] = "Ah, Deusa... quando a professora me entregou a loja, eu disse que não conseguiria...",
  [1152359321994752] = "Olá... há algo de errado com 'Caramel Bomb'?",
  [1152359321994496] = "Olá Lojista, você desenvolveu o 'Caramel Bomb'?",
  [1152359321994240] = "Não, não, eu não me consideraria ótimo...",
  [1152359321993984] = "Como eu saberia fazer isso! As bebidas são todas fornecidas pela loja de ervas folclóricas de Lawson, no Distrito Leste. Olha, o lojista veio entregar a mercadoria; este é o Sr. Shermin, o grande farmacêutico!",
  [1152359321993728] = "Olá, acabei de provar 'Caramel Bomb', tem um gosto muito bom. Posso perguntar se você mesmo fez isso?",
  [1152359321993472] = "Não se preocupe, suspeito que a receita desta bebida contém ingredientes que causam diarreia. Você espera na porta; Talvez eu possa ajudar a melhorar esta bebida!",
  [1152359321993216] = "Não me diga que você quer... resolver o problema da bebida? Não! Embora nos dê diarréia, mas—",
  [1152359321992960] = "Como você sabia! É esse mesmo!",
  [1152359321992704] = "O veneno que você mencionou é 'Bomba de Caramelo'?",
  [1152359321992448] = "Não, deixe-me pensar novamente...",
  [1152359321992192] = "<P_Heart> (O 'veneno' que eles mencionaram pode ser esse?) </>",
  [1152359321991936] = "Eu te disse! Que tal? Você é um porco, você é um porco, você é um porquinho Loenese—",
  [1152359321991680] = "Diga isso de novo se tiver coragem?!",
  [1152359321991424] = "Você é o porco!",
  [1152359321991168] = "Estou discutindo com você, seu porco Intis!",
  [1152359321990912] = "Ei, eu já te dei uma cara gritando 'faça um movimento' mais cedo, e agora você vai discutir comigo?",
  [1152359321990656] = "Doce? Isso é enjoativo! Beber um gole pode fazer alguém marchar no mesmo ritmo até Backlund!",
  [1152359321990400] = "O mais assustador é que dá vômito e diarreia... mesmo assim a gente ainda bebeu de novo, e de novo, e de novo...",
  [1152359321990144] = "Kalan e eu recentemente nos tornamos viciados em um veneno sagrado... esse líquido tem gosto doce e a textura é como três mil fogos de artifício explodindo na boca, fazendo com que alguém seja incapaz de parar de beber, e beber, e beber...",
  [1152359321989888] = "Estamos orando ao Senhor do Banheiro; Ele é muito poderoso! Amigos que costumam ter diarreia sabem que Ele pode restaurar a saúde do trato digestivo!",
  [1152359321989632] = "Eu sou Miles, ele é Kalan, somos estudantes próximos...",
  [1152359321989376] = "Explique seus nomes e para quem você está orando?",
  [1152359321989120] = "Ninguém se mexa! Investigação policial!",
  [1152359321988864] = "Eu rezo para você—",
  [1152359321988608] = "O guardião de todos os aparelhos digestivos de Tingen—",
  [1152359321988352] = "A misteriosa majestade entronizada no assento do vaso sanitário.",
  [1152359321988096] = "O Mestre dos Banheiros e Esgotos.",
  [1130298758691840] = "Realmente?",
  [1152359321987840] = "Parece que o barulho vem do banheiro masculino... por que não ouvi agora? Não importa, vamos verificar!",
  [1152359321986560] = "Parece que o barulho vem do banheiro masculino... bem, é masculino, tenho que verificar!",
  [1152359321986304] = "Fazer, fazer um movimento? Que tipo de movimento? Roubo ou roubo?",
  [1152359321985792] = "Pronto, vamos agir?",
  [1152359321985536] = "Ufa, muito melhor.",
  [1152359321985280] = "Lembro que tem um banheiro público por perto, preciso encontrá-lo rápido!",
  [1152359321985024] = "O que está acontecendo? Sinto correntes de ar agitando meu estômago... minha barriga... dói tanto...",
  [1152359321984768] = "...Algo está errado.",
  [1152359321984512] = "Aqui você vai. Depois de beber esta 'Bomba de Caramelo', que todas as suas preocupações explodam e que sua vida seja tão doce quanto possível!",
  [1152359321984256] = "Isso é impressionante? Dê-me uma garrafa!",
  [1152359321984000] = "Ei, {Sr.{Sra.|}}! Quer experimentar uma bebida que morde a língua? Apenas 1 centavo, mais forte que o chá gelado doce e mais refrescante que a cerveja de gengibre!",
  [1152359321983488] = "<P_Heart> (Chegou a este ponto... Que o Sr. Louco nos abençoe...) </>",
  [1152359321983232] = "<P_Heart> (espiritualidade oscilou... ali?) </>",
  [1152359321982976] = "Mas, felizmente, esta estrada é brilhante.",
  [1152359321982720] = "Eu nunca soube que ele tinha que caminhar tanto para chegar ao trabalho.",
  [1152359321982464] = "Há alguns anos, não tive oportunidade nem coragem de ver o caminho que ele percorreu.",
  [1152359321982208] = "<P_Heart> (olhando para cima) </> Vamos sentar um pouco; é raro que Tingen tenha um tempo tão bom.",
  [1152359321981696] = "Obrigado a ambos.",
  [1152359321981440] = "Lembro-me deste buquê... Crisântemos Sevia, simbolizando felicidade.",
  [1152359321981184] = "<P_Heart> (Olha fixamente para os crisântemos) </> ...",
  [1152359321980928] = "Foi preparado especialmente para você pelo Sr. Leonard.",
  [1152359321980672] = "Obrigado! E esse buquê?",
  [1152359321980416] = "Tudo bem! Deixe comigo!",
  [1152359321980160] = "<P_Heart> (Inclina-se ligeiramente) </> Então, gostaria de pedir que você me ajude a pegar a planta.",
  [1152359321979904] = "<P_Heart> (Sorrisos) </> Está tudo bem, você não precisa me confortar. Eu sei que ele realmente não nos deixou. É um pouco, um pouco triste.",
  [1152359321979392] = "Mas voltando aqui, sempre penso na cena do primeiro dia de trabalho de Klein.",
  [1152359321979136] = "Os colegas do meu irmão são muito atenciosos; O Sr. Leonard e o Sr. Frye ajudaram-me a encontrá-los. Mas...",
  [1152359321978880] = "Dessa vez, voltei a Tingen para encontrar a planta de um relógio Intis para minha tese de graduação.",
  [1152359321978624] = "O que há de errado, Melissa?",
  [1152359321978368] = "Então, vamos voltar para Blackthorn primeiro.",
  [1152359321978112] = "<P_Heart> (As palavras de Melissa... são muito no estilo do Sr. Louco.) </>",
  [1152359321977856] = "<P_Heart> (Risos) </> Haha, Benson é muito adequado para o departamento financeiro. Mas o lema da família Moretti é: cada moeda deve ser gasta onde vale a pena.",
  [1152359321863936] = "Senhoras e senhores, anuncio que nasceu um novo campeão de boxe!",
  [1152359321977344] = "<P_Heart> (baixando a voz) </> E olha, o custo de vida em Tingen é bem mais barato que em Backlund; é mais econômico comprar aqui.",
  [1152359321553920] = "Deixe-me ir, eu imploro...",
  [1152359321976576] = "É um prazer conhecê-lo. Qual o seu nome?",
  [1152359321976320] = "Eu sei! Você deve ser aquele que o Sr. Leonard mencionou em sua carta: o “novo colega muito talentoso”.",
  [1152359321976064] = "Ah, isso, sou funcionário da Blackthorn, estou aqui para recebê-lo em nome do Sr. Leonard. Eu... eu vi sua foto.",
  [1152359321975808] = "<P_Heart> (Surpreso) </> Você me conhece?",
  [1152359321975296] = "Continue assim, Senhor Mensageiro...",
  [1152359321975040] = "...eu protesto! Não estou mais escrevendo! Não! Escrita! Não mais!",
  [1152359321974272] = "“Louvado seja… o tolo…”",
  [1152359321974016] = "“Você pode consultar… o professor de história da universidade…”",
  [1152359321973760] = "“A parte dos clássicos sobre os Anjos do Sr. Louco também precisa ser revisada…”",
  [1152359321973504] = "O que há de errado, Senhor Mensageiro?",
  [1152359321973248] = "<P_Heart> (Abre a carta para verificar) </> Isto...",
  [1152359321972992] = "Dado o seu Sequência , é melhor não ter pensamentos tão perigosos, caso contrário—hmm, de quem é esta carta?",
  [1152359321972736] = "Muito obrigado. Tanto a Igreja quanto eu nos lembraremos de sua ajuda. Você pode me chamar pelo meu nome, 'Flaming' Danitz - ah, merda, merda, ainda estou na lista de procurados. Você não vai me denunciar, vai?",
  [1152359321972480] = "<P_Heart> (Tem uma má premonição) </> Eu?",
  [1152359321972224] = "A propósito, você disse que acredita no Louco, e já que veio também...",
  [1152359321971968] = "Não, o Capitão vai ficar bravo se descobrir... Só pedi que encontrassem algumas informações para aliviar minha carga de trabalho.",
  [1152359321971712] = "...Então, você usou o Evangelho do Louco para trocar por outros para completar sua tese?",
  [1152359321971456] = "Assim que terminar de editar o códice, vou colocar fogo em toda essa pilha de lixo! Queime tudo!",
  [1152359321971200] = "Lingüística, história, geografia, teologia, semiótica – se eu não terminar minha tese e receber os créditos, não posso sair da escola, ahhhhh, besteira!",
  [1152359321970944] = "Assista à aula! Os clássicos são realmente difíceis de compilar! Depois que o capitão leu meu primeiro rascunho, ele me enviou aqui para continuar meus estudos!",
  [1152359321970432] = "<P_Heart> (A voz é como o zumbido de um mosquito) </> Porque eu tenho que assistir à aula...",
  [1152359321970176] = "Por que escrever aqui em vez de ficar em um lugar como uma igreja?",
  [1152359321969920] = "Claro, este é um missão atribuído a mim pelo Bispo Derrick, para escrever um novo capítulo para o \"Livro do Louco\".",
  [1152359321969664] = "Você é realmente um mensageiro divino?!",
  [1152359321969408] = "Onde está um mensageiro divino como você, e você está até escrevendo... o \"Livro do Louco\" aqui?",
  [1152359321969152] = "Besteira, que caixa de correio, sou um mensageiro divino, um mensageiro divino!",
  [1152359321968896] = "<P_Heart> (Esta voz...) </> Você é aquela caixa de correio?",
  [1152359321968640] = "Merda, de onde você saiu!",
  [1152359321967872] = "Escrever isso depois daquilo, escrever aquilo depois disso... merda, quando isso vai acabar...",
  [1152359321967616] = "Resumindo, aceite o Evangelho e complete meu missão .",
  [1152359321967360] = "Não questione a decisão do mensageiro divino!",
  [1152359321967104] = "Uh... esse pedido é tão estranho...",
  [1152359321966848] = "Agora preciso... da compilação das escrituras e oráculos das igrejas ortodoxas da Quinta Época.",
  [1152359321966592] = "Concederei bênçãos, afastarei os espíritos malignos e realizarei milagres para você. Em troca, você deve pagar uma certa recompensa.",
  [1152359321966336] = "É assim mesmo? Então isso torna as coisas mais fáceis.",
  [1152359321966080] = "Eu sei, também acredito no Sr. Louco, acredito nele.",
  [1152359321965824] = "Primeiro, reserve um momento do seu tempo para me ouvir falar sobre nosso farol e salvador...",
  [1152359321965568] = "<P_Heart> (Senhor Mensageiro... é uma caixa de correio?) </>",
  [1152359321965312] = "Que rude, sou um mensageiro divino da Igreja do Louco; você deveria se dirigir a mim como Senhor Mensageiro.",
  [1152359321965056] = "A caixa de correio realmente falou?!",
  [1152359321964800] = "Você é quem está aqui para ouvir o evangelho?",
  [1152359321964544] = "Não desapareceu desta vez, deixe-me dar uma olhada mais de perto...",
  [1152359321964288] = "Eu não... Pra...",
  [1152359321964032] = "Mas ainda tenho um documento... relativo às escrituras e documentos oficiais de várias igrejas ortodoxas...",
  [1152359321963776] = "Embora a fé do Louco seja considerada uma fé em uma verdadeira divindade e seja bastante popular entre os marinheiros, como estudante você não deve confiar nos deuses para resolver seus problemas acadêmicos. Venha comigo ao Gabinete Disciplinar para escrever uma autorreflexão!",
  [1152359321963520] = "Mas... sob o abrigo do Evangelho, eu realmente passei no exame para funcionário público com notas altas...",
  [1152359321963264] = "De acordo com o Artigo 97 das regras escolares, nenhuma organização ou indivíduo está autorizado a promover a religião na escola, muito menos a participar em atividades religiosas!",
  [1152359321963008] = "Louvado seja o Louco! <P_Heart> (Por que de novo...) </>",
  [1152359321962496] = "De acordo com as instruções do Evangelho, extraí estes materiais históricos sobre o Mar Sónia.",
  [1152359321962240] = "Tudo, tudo, deve agradecer ao generoso Sr. Louco.",
  [1152359321961984] = "Um milagre realmente aconteceu! Os dados experimentais anteriores nunca foram qualificados, mas desta vez tiveram sucesso de uma só vez!",
  [1152359321961728] = "Louvado seja o Louco! <P_Heart> (Espere, por que eu também estou...) </>",
  [1152359321961216] = "De acordo com as instruções, encontrei todos os materiais históricos sobre a Quarta Época.",
  [1152359321960960] = "Depois de receber a orientação do Evangelho, os pesadelos nunca mais apareceram. Louvado seja o Louco!",
  [1152359321960704] = "É isso mesmo, eu já fui um cordeiro perdido, atormentado por pesadelos terríveis de reprovação nos exames por inúmeras noites.",
  [1152359321960448] = "Com licença, você está aqui para ouvir o evangelho do Louco?",
  [1152359321960192] = "Em seguida, use seu próprio método para continuar a ‘limpar’. Não deixe esta cidade ficar muito “quieta”.",
  [1152359321959936] = "Bem-vindo ao Clube \"Bom Cidadão\". Parabéns por se tornar oficialmente o “limpador” mais eficiente nas sombras de Tingen.",
  [1152359321959680] = "De agora em diante, não temos nenhum relacionamento.",
  [1152359321959424] = "Não, minha querida, eu realmente te amo!",
  [1152359321959168] = "Na verdade você é uma bruxa, mentiu para mim, não posso aceitar isso!",
  [1152359321957120] = "Parece que... não tenho mais tanto medo de mostrar aos outros os poemas que escrevi. Da próxima vez, quero dar o poema que acabei de escrever ao Sr. Leonard também!",
  [1152359321956864] = "Como pode ser igual... mas, sabendo que até ela recebe cartas de rejeição, por algum motivo, sinto que ela é ainda mais incrível.",
  [1152359321956608] = "Ah? Então ela também foi rejeitada? Então talvez não seja tão embaraçoso que eu tenha reprovado na aula de gramática da última vez!",
  [1152359321956352] = "Kelvin, a Sra. Xiga gostou muito do seu presente, mas ela disse que não pode ser considerada uma \"grande escritora\" no momento - seu último manuscrito acabou de ser rejeitado pelo editor do Tingen Daily, e ela está bastante preocupada com isso.",
  [1152359321955840] = "Unidade é força!",
  [1152359321955584] = "Assim como o Imperador Roselle disse—",
  [1152359321955328] = "Uma equipe... então foi a força de todos! Vou contar ao meu irmão, vamos guardar bem essa foto. Obrigado!",
  [1152359321955072] = "Marsha, o capitão Frye está muito grato pelos seus presentes, mas não foi o único que a salvou da carruagem; foi um esforço de equipe.",
  [1152359321954816] = "Voltaremos amanhã até que todos os presentes sinceros sejam entregues. Espero que ao recebê-los possam sentir um pouco de felicidade. Gentil {Sr.{Sra.|}}, que a Deusa o abençoe.",
  [1152359321954560] = "Uau, ele parece muito gentil! Eu me pergunto se a Sra. Xiga será tão gentil...",
  [1152359321954304] = "Que ótimo, Lia! Que bom que o Sr. Leonard tenha gostado do seu presente.",
  [1152359321954048] = "O mesmo lugar... então a frase 'a solidão não é assustadora'... foi a sua própria experiência. Obrigado!",
  [1152359321953792] = "Leah, as coisas foram entregues. O Sr. Leonard me pediu para lhe agradecer; ele aprecia muito esse sentimento. Ele também me pediu para te contar - ele cresceu no mesmo lugar, o orfanato Vigia Noturno.",
  [1152359321953280] = "Então pegue... embora encarar a câmera sempre me deixe um pouco desconfortável. Mas se é você quem está pegando, parece que consigo relaxar um pouco – em momentos como esse, deve haver alguém de confiança presente.",
  [1152359321953024] = "Ele também tem um pequeno desejo, esperando poder tirar uma foto sua usando isso em seu trabalho criativo.",
  [1152359321952768] = "No entanto, não se esqueça de agradecer a Kelvin por mim. Os itens que ele escolheu são muito práticos; para quem gosta de escrever, não há presente mais precioso do que papel e canetas para registrar pensamentos a qualquer momento.",
  [1152359321952512] = "\"Grande Escritor\"? O conto que enviei ao \"Tingen Daily\" na semana passada foi rejeitado novamente, o comentário do editor foi \"carece de conflito dramático e perspectivas comerciais necessários\". Simplificando, não é emocionante o suficiente... É realmente uma dor de cabeça...",
  [1152359321952256] = "Ele ouviu dizer que você é um “grande escritor”, então preparou papel e canetas especialmente, esperando que você possa usá-los para escrever trabalhos ainda melhores.",
  [1152359321952000] = "Kelvin? Aquele jovem inteligente, mas um pouco imprudente. Parece que o amuleto de segurança foi útil. É bom que ele esteja bem. Isso é?",
  [1152359321951744] = "Xiga, você está livre agora? Um jovem chamado Kelvin me pediu para trazer algo para você; ele quer agradecer por sua orientação anterior.",
  [1152359321951232] = "Tudo bem, então vou incomodá-lo para registrar este momento.",
  [1152359321950976] = "Entendo... Eles também esperavam tirar uma foto sua com essa escultura em madeira; a criança queria especialmente ver sua reação quando você o recebesse.",
  [1152359321950720] = "Sozinho... isso não está certo. Durante essa operação, Xiga foi responsável por orientar e estabilizar a multidão, Leonard garantiu que o ambiente fosse seguro e todos nós usamos um pouco do apoio necessário com muita moderação – é claro, a criança não teria notado.",
  [1152359321950464] = "Eles são muito gentis. Aquela criança te admira muito e disse que você controlou sozinho a carruagem para salvá-lo, então ele pessoalmente esculpiu isso em madeira como um presente para você.",
  [1152359321950208] = "Martha... e aquele menino, eles estão bem?",
  [1152359321949952] = "Capitão, desculpe incomodá-lo. Martha e seu irmão querem agradecer pela ajuda anterior. Este é o sentimento deles.",
  [1152359321949440] = "Uma foto... para ser sincero, costumo recusar esses pedidos. No entanto, se for você quem está ajudando a tirar a foto, concordo.",
  [1152359321949184] = "Aliás, ela quer guardar como lembrança uma foto sua recebendo o presente.",
  [1152359321948928] = "Por favor, agradeça a ela por mim; esse sentimento é muito precioso. Porém, você pode dizer a ela: eu cresci no orfanato Vigia Noturno assim como ela. Um poeta... um verdadeiro poeta provavelmente não teria tanta dor de cabeça ao escrever poesia.",
  [1152359321948672] = "Ela ouviu que você era um ‘nobre poeta’ e copiou especificamente a coleção de poesia, pensando que seria digna de seu status.",
  [1152359321948416] = "Lia? Ah, aquela garotinha que sempre tem pesadelos no orfanato, parece que a pequena mágica do sonho funcionou. Isto é... um poema que ela copiou? Para mim?",
  [1152359321948160] = "Sr. Leonard, eu perturbei seu descanso? Uma garota chamada Leah me pediu para trazer algo para agradecer pela sua ajuda anterior.",
  [1147961275157248] = "Nada.",
  [1152359321947904] = "Claro, se ela concordar.",
  [1152359321947648] = "Muito obrigado! Além disso... você poderia tirar uma foto dela quando ela vir o presente? Seus dedos batendo no queixo quando ela está pensando, a pequena luz que brilha em seus olhos quando ela lê uma frase interessante... esse tipo de sentimento transparente é especialmente legal.",
  [1152359321947392] = "Xiga pode estar escrevendo na sala. Vou fazer café, posso perguntar a ela enquanto faço isso.",
  [1152359321946880] = "Se possível... você poderia tirar uma foto do Capitão Frye quando ele receber o presente? Não há necessidade de posar, apenas o seu jeito habitual. Quando ele fica parado sem falar, ele tem uma sensação que deixa as pessoas particularmente à vontade.",
  [1152359321946624] = "O capitão Frye geralmente está no escritório, posso ajudá-lo a passar isso adiante.",
  [1152359321946368] = "Claro, se ele concordar.",
  [1152359321946112] = "Obrigado... você poderia tirar uma foto do Sr. Leonard quando ele receber o presente? O olhar focado em seus olhos verdes quando ele recita poesia... é difícil de esquecer.",
  [1152359321945856] = "Leonard acabou de voltar de uma missão, por acaso vou encontrá-lo, posso ajudá-lo a passar isso adiante.",
  [1152359321945600] = "Eu entendo, você quer que eu ajude a repassar esses presentes, certo? Na verdade, eles têm estado muito ocupados com tarefas recentemente... mas provavelmente sei quem está livre agora.",
  [1130369089383424] = "O que você está olhando?",
  [1152359321945344] = "Sabemos que todos em Blackthorn geralmente estão muito ocupados, e visitar diretamente pode ser muito perturbador... e o que preparamos não são coisas valiosas, então temos medo que pareça rude...",
  [1152359321945088] = "Na verdade, não os encomendamos oficialmente e não podemos pagar a taxa de comissão... mas todos ajudaram muito quando precisávamos, e só queremos expressar um pouco do nosso coração.",
  [1152359321944832] = "Madame Xiga... o método que ela me ensinou me permitiu evitar problemas com sucesso. Ouvi dizer que ela não só faz segurança aqui, mas também é uma ótima escritora, então preparei papel e canetas... Espero que ela possa usá-los.",
  [1152359321944576] = "O meu irmão foi salvo pelo Capitão Frye de uma carruagem fora de controlo. Para expressar sua gratidão, ele fez uma escultura em madeira com a madeira que guardou, dizendo que o capitão é como um herói de uma história.",
  [1152495149647616] = "Sua escolha causou mudanças sutis no distrito fabril de Tingen.",
  [1152495149658880] = "Um mês depois, um \"Restaurante Octopus Chef\" foi inaugurado em Docks Bay, sem negócios nem bons nem ruins. Diz-se que o proprietário é o ex-chefe do Restaurante Coastline – o Rei dos Chefs, Cook.",
  [1152359321943808] = "Quanto ao conteúdo deste ritual, não vou apresentar muito. Você poderá acompanhar todo o processo muito em breve.",
  [1152359321943552] = "Estou honrado. Parece que a Deusa também apoia a nossa escolha e nos enviou um ajudante.",
  [1152359321943296] = "Além disso, este é o meio catalítico que usaremos a seguir. Fique à vontade para verificar e coloque-o de volta no ritual após verificar. Está bem ali.",
  [1152359321943040] = "Se você insistir, poderá ficar e testemunhar esse experimento com seus próprios olhos. Acredito que você mudará de ideia.",
  [1152359321942784] = "Sim, sim, entendo suas preocupações, mas acreditamos que somente experimentando você mesmo você poderá obter o conhecimento que lhe pertence.",
  [1152359321942528] = "Este é um ritual absolutamente seguro. Mesmo que falhe, ninguém ficará ferido, mas nosso professor e os policiais não pensam assim.",
  [1152359321942272] = "Na verdade, estamos pesquisando um certo... ritual alquímico. Para ser mais preciso, é uma replicação do ritual de mapeamento de números espirituais registrado no 'Códice Hermes'.",
  [1152359321942016] = "Isso não é direcionado a você pessoalmente, é só que ter outras pessoas por perto afetará a pureza do campo ritual... Ah, quero dizer, é um ritual baseado em pesquisa.",
  [1152359321941760] = "Pare, {Sr.{Sra.|}}... Por favor, perdoe minha grosseria, mas você não pode se aproximar aqui por enquanto.",
  [1152359321941504] = "Se alguém virar para a última página, ficará surpreso ao encontrar uma 'Bruxa e a Fera' rebelde, uma paródia que você escreveu por capricho.",
  [1152359321941248] = "‘A Bela e a Fera’, assinado por Roselle Gustav, você não fica nem um pouco surpreso.",
  [1152359321940992] = "Se você tiver alguma dúvida ou confusão, Arrodes está aqui para responder a todas as suas perguntas.",
  [1152359321940736] = "Não se preocupe, só você pode me ver. Aos olhos dos transeuntes, você é apenas um tolo falando sozinho perto da fonte.",
  [1152359321940480] = "Na verdade, estou me comunicando com um espelho...",
  [1152359321940224] = "Parabéns, você aprendeu este jogo de perguntas e respostas.",
  [1152359321939968] = "Isso dói!",
  [1152359321939712] = "Para realmente ignorar a pergunta de Arrodes, punição!",
  [1152359321939456] = "É muito estranho! O espelho está voando! E faz perguntas!",
  [1152359321939200] = "Boa resposta, lindos olhos.",
  [1152359321938944] = "Sim! Quero me livrar da corrupção e encontrar a resposta para tudo!",
  [1152359321938688] = "Você quer se livrar da corrupção imunda do seu corpo?",
  [1152359321938432] = "De acordo com o <P_Yellow> princípio da reciprocidade </> , é minha vez de fazer uma pergunta. Se você recusar ou não puder responder, receberá a punição <P_Yellow> de Arrodes </> .",
  [1152359321938176] = "Vim seguindo o cheiro da névoa cinzenta, seguindo as instruções do grande mestre para ajudá-lo.",
  [1152359321937920] = "Eu sou o servo mais leal do Sr. Tolo, o Espelho Mágico Arrodes. O que você vê é apenas um avatar; meu verdadeiro corpo ainda está ao lado do meu mestre.",
  [1152359321937664] = "O que é isso!?",
  [1152359321937408] = "O grande Sr. Arrodes.",
  [1152359321937152] = "Cara rude, você deveria se dirigir a mim como—",
  [1152359321936896] = "Falou mesmo!",
  [1152359321936640] = "Encontrei você.",
  [1152359321936384] = "Ele nem tem boca, como pode falar?",
  [1152359321936128] = "Deveria ser esta fonte.",
  [1152359321935872] = "Uma fonte que pode falar e atingir as pessoas? Vamos dar uma olhada.",
  [1152359321935616] = "Recusando-se a responder à pergunta, punição!",
  [1152359321935360] = "Fonte F! A fonte está falando! Um fantasma—",
  [1152359321935104] = "Você deseja que seu parceiro não seja humano?",
  [1152359321934848] = "Eu já respondi sua pergunta. Agora é minha vez de perguntar.",
  [1152359321934592] = "Quem está falando!",
  [1152359321934080] = "Por que Charlotte rejeitou meu convite novamente? Ela me odeia?",
  [1152359321933824] = "Acho que estava respondendo à minha pergunta. Fiquei muito confuso naquela época...",
  [1152359321933568] = "Sim?",
  [1152359321933312] = "Ele disse... sim.",
  [1152359321933056] = "Como poderia uma fonte falar? O que isso disse?",
  [1152359321932800] = "Ontem, quando eu estava orando devotamente diante da fonte, a fonte realmente falou!",
  [1152359321932544] = "Ah— <P_Heart> (Grito de um homem) </>",
  [1152359321932288] = "Le-Lena, o que você está fazendo?",
  [1152359321932032] = "Joana! Fil! Vá pegar essa coisa!",
  [1152359321931776] = "Quantas vezes é isso?! Da última vez foram rosas, da vez anterior foram velas, o que é desta vez? Você acha que é o protagonista masculino de um romance escrito pelo Imperador Roselle?!",
  [1152359321931520] = "Hmm... hmm... seu maldito sapo que não entende a fala humana!",
  [1152359321931264] = "(Fiz contato visual com Lena. Ela... ela se apaixonou por... mim?)",
  [1152359321931008] = "Oh, ora, embora você seja apenas um na multidão, estou profundamente atraído por você.",
  [1152359321930752] = "Lena? O que você está olhando?",
  [1152359321930496] = "Lena! Meu coração é verdadeiro, por favor...",
  [1152359321930240] = "<P_Heart> (Mais amor? Poderia significar isso? Não sei onde comprar.) </>",
  [1152359321929984] = "Nossa, não posso dizer. Você tem que descobrir sozinho.",
  [1152359321929728] = "Mais amor? Então... então o que devo fazer?",
  [1152359321929472] = "Hmm... nossa, não sou esse tipo de mulher casual... acho que preciso de mais amor.",
  [1152359321929216] = "Lena, olha, até o destino está nos abençoando! Os aplausos desses estranhos são a melhor testemunha do meu amor por você.",
  [1152359321928960] = "<P_Heart> (Parece bastante interessante. Deixe-me pensar no que posso fazer!) </>",
  [1152359321928704] = "<P_Heart> (Este cavalheiro está... expressando seu amor pela senhora na varanda?) </>",
  [1152359321928448] = "Por favor, permita-me entrar em sua vida e deixar nossa história ser escrita a partir desta noite. Lena, eu te amo mais do que tudo de lindo nesse mundo!",
  [1152359321928192] = "Lena! Meu luar! Desde o primeiro momento que te vi, fiquei cativado pelas estrelas em seus olhos. Todas as noites, eu me reviro e sua figura permanece em minha mente, incapaz de ser descartada.",
  [1152359321927936] = "Então não vamos mais incomodá-lo. Vamos beber juntos quando tiver tempo!",
  [1152359321927680] = "Ah, eu sei, eu sei. Os figurões sempre têm coisas sobre as quais não podem falar. A culpa foi minha por não ter pensado nisso.",
  [1152359321927424] = "Desculpe... eu...",
  [1152359321927168] = "Grande tolerância ao álcool! Venha, vamos tomar uma boa bebida!",
  [1152359321926912] = "Escondi este barril de cerveja escura durante três meses, apenas esperando que um verdadeiro herói o explorasse!",
  [1152359321926656] = "Para ser honesto... até o Velho Scarface murmura que os ratos nos esgotos de Tingen têm que ficar em posição de sentido e saudar quando vêem você!",
  [1152359321926400] = "Venha, venha aqui. Estes são 'Rat' Jimmy, 'Bottle' Sam, 'Viper' Sean e 'Scarface' Willy.",
  [1152359321926144] = "Hmph, vamos nos ver quebrar sua boca agora!",
  [1152359321925888] = "Você sabe por que os corvos do Distrito Leste não ligaram recentemente? Porque suas gargantas estão presas com ossos de idiotas como você.",
  [1152359321925632] = "Tch, perca-se enquanto pode. Não queremos ver você.",
  [1152359321925376] = "Eu apenas pensei que vocês eram meus conhecidos. Parece que eu estava enganado.",
  [1152359321925120] = "Desapareça imediatamente, ou você prefere se ajoelhar e lamber esta poça para limpar, ou esperar que meus irmãos ajam?",
  [1152359321924864] = "Por que você está aqui? A última pessoa que veio me provocar só sobrou esse dente... quer deixar uma lembrancinha também?",
  [1152359321924608] = "O Imperador Roselle disse uma vez que tanto a bondade quanto o mal receberão a devida resposta! Agora, deixe-os ir para a prisão e refletir sobre suas ações!",
  [1152359321924352] = "Você não tem culpa, mas você acreditaria? Ele fingiu estar doente por tanto tempo que só depois de fazer um exame médico na prisão é que descobriu que na verdade estava sofrendo de uma doença grave!",
  [1152359321924096] = "E a doença do Ed, parecia que ele estava prestes a morrer...",
  [1152359321923840] = "<P_Heart> (Não, a Deusa não faria isso... o perfume proibido deve ter o poder de fazer as pessoas relaxarem a vigilância, não admira que eu fosse como uma cidadã preocupada e fui enganada sem qualquer suspeita...) </>",
  [1152359321923584] = "Você tem razão, a turma comprou perfume proibido que pode confundir a cabeça das pessoas no mercado clandestino, até a Deusa seria enganada!",
  [1152359321923328] = "Obrigado, oficial. Geralmente estou muito alerta, mas quando encaro Ed, era como se meu coração estivesse coberto de manteiga; Eu só precisava ajudá-lo... Agora só sinto arrependimento, arrependimento profundo.",
  [1152359321923072] = "{Sr.{Sra.|}}, é você. A devolução dos produtos que você comprou foi bem-sucedida e o pagamento foi recuperado.",
  [1152359321922560] = "Precisamos de roupas novas... talvez algo com uma cor diferente, de preferência que brilhe ao sol!",
  [1152359321922304] = "Uh... essas roupas velhas realmente não são decentes o suficiente, seja para passear no Central Plaza ou para ir à igreja rezar...",
  [1152359321921792] = "Devemos atacar! Merecemos melhor! Merecemos mais!",
  [1152359321921536] = "Queremos atacar! Proprietários de fábricas inescrupulosos não são dignos de nós, trabalhadores esforçados!",
  [1152359321920768] = "Sempre dizem que gastamos todo o nosso dinheiro em álcool, mas não sabem que é a água benta que sustenta o nosso trabalho! Não temos como tirar dinheiro dos bolsos desses donos de fábricas, então só podemos usar o álcool para confortar nossas almas!",
  [1152359321920512] = "Trabalhamos até morrer, mas só recebemos um salário lamentavelmente pequeno. Esses pobres soli não dão nem para pagarmos aluguel e comprarmos um pouco de comida!",
  [1152359321920000] = "Precisamos... uh... de um novo bar, senão não poderemos trabalhar! Por causa da sede... ou outra coisa...",
  [1152359321919744] = "Uh... especialmente cerveja! A cerveja do Evil Dragon Bar chegou ao ponto de não ser comestível!",
  [1152359321919232] = "<P_Heart> Os trabalhadores parecem confusos... </>",
  [1152359321918976] = "Não podemos viver! A menos que... a menos que os vegetais da Rua Cruz de Ferro possam ser mais baratos...",
  [1152359321918720] = "Uh... o pão da loja de painéis... é muito caro, a gente não tem nem dinheiro... agulhas de costura, e o que mais...",
  [1152359321918464] = "<P_Heart> Os trabalhadores parecem animados! </>",
  [1152359321918208] = "Eles poderiam claramente melhorar o nosso ambiente de trabalho gastando muito pouco dinheiro. Mas, na realidade, eles preferem gastar esse dinheiro em joias brilhantes!",
  [1152359321917952] = "A poeira da fábrica está prejudicando nossos pulmões e tirando nossas vidas, mas e os donos das fábricas? Eles só se preocupam se nossa licença médica afetará o período de construção!",
  [1152359321917696] = "<P_Heart> Sobre o que você vai falar? </>",
  [1152359321917440] = "Acalme-se, acalme-se! Meus queridos colegas de trabalho, por favor, me escutem!",
  [1152359321917184] = "Reunir-se em uma livraria é muito elegante... vamos preparar os presentes.",
  [1152359321916928] = "Esta é a maior livraria de Tingen e muitos estudantes vêm aqui para comprar livros.",
  [1152359321916672] = "Se for conveniente, você poderia convidar aquele cavalheiro de avental cinza prateado para vir até aqui? Ele sempre consegue manter a temperatura do chá preto tão perfeita quanto a de um riacho no início da primavera.",
  [1152359321916416] = "Isso seria maravilhoso. O barista tem muitos doces; fique à vontade para escolher o que quiser.",
  [1152359321916160] = "O chá preto com pudim de limão é perfeito para uma tarde como esta. Você gostaria de compartilhar esse tempo de lazer comigo?",
  [1152359321915648] = "Obrigado, você também se lembra deles.",
  [1152359321915392] = "Nunca perderei nenhum de seus aniversários.",
  [1152359321915136] = "Você está aqui.",
  [1152359321914624] = "Também há cópias de vários documentos e clássicos de alto nível, e lê-los requer um certo nível de autoridade. Além disso, alguns artefatos selados são mantidos na parte inferior do Portão Chanis.",
  [1152359321914368] = "É dividido em diversas áreas, preservando fórmulas de poções de certas sequências e diversos materiais mágicos, e detendo temporariamente hereges, mutantes, cultistas e membros de organizações secretas.",
  [1152359321914112] = "É guardado por membros oficiais rotativos Vigia Noturno, e há pelo menos dois guardas internos da igreja dentro, bem como inúmeras armadilhas. Não aborde isso casualmente, ou você será contaminado pelo azar.",
  [1152359321913856] = "Derivado do nome do Arcebispo Chanis, o fundador do sistema Vigia Noturno moderno, existe um no porão da catedral central da igreja da Deusa da Noite Eterna em todas as grandes cidades.",
  [1152359321913344] = "Eu rezo por sua ajuda",
  [1152359321913088] = "Você é o Rei do Amarelo e do Preto que tem boa sorte",
  [1152359321912832] = "Você é o governante misterioso acima da névoa cinzenta",
  [1152359321912320] = "Eu rezo por sua proteção",
  [1152359321912064] = "Eu rezo pelo seu olhar",
  [1152288991313664] = "Quem é você?",
  [1152359321911808] = "O grande Deus das Tempestades",
  [1152359321911552] = "O Imperador que domina o mar",
  [1152359321911296] = "O rei que governa o céu",
  [1152359321911040] = "Eu oro por sua proteção para um crente leal",
  [1152359321910528] = "Você é a Mãe da Ocultação, a Imperatriz da Calamidade e do Terror, o Senhor do Sono e do Silêncio",
  [1152359321910016] = "Em qualquer caso, passeios de teste gratuitos, você está convidado a experimentá-los!",
  [1152359321909760] = "As bicicletas são todas boas... mas se você pegá-las emprestadas, o melhor é devolvê-las aos seus lugares originais por cor. Da última vez que alguém estacionou bicicletas amarelas em frente à Catedral de Santa Selena, a expressão nos rostos das duas igrejas...",
  [1152359321909504] = "Brown é o modelo de paz e conforto. A absorção de choque é suave e quase não emite nenhum som durante a condução. O conceito de paz defendido pela igreja Evernight Goddess é especialmente adequado para áreas noturnas e residenciais.",
  [1152359321909248] = "Azul, a escolha de velocidade e potência! Leves e que economizam trabalho, os rolamentos são suaves, promovidos pela igreja do Senhor das Tempestades, especialmente populares na área portuária e nas estradas costeiras, suaves em todo o caminho, mais rápidos.",
  [1152359321908992] = "Amarela, robusta e fácil de dirigir, a transmissão equipamento é particularmente suave e pode suportar os solavancos das estradas de pedra no distrito fabril. Supervisionados pelos artesãos da igreja Deus do Vapor e das Máquinas, a qualidade é garantida!",
  [1152359321908736] = "Veja bem, o método de funcionamento é o mesmo: insira uma moeda para desbloquear, devolva para qualquer lugar, mas cada bicicleta tem seus méritos.",
  [1152359321908480] = "Muito bem, senhor. O tempo de espera estará incluído na tarifa, fique atento.",
  [1152359321908224] = "Então vamos fazer uma pausa aqui por um momento.",
  [1152359321907968] = "Espere um minuto... olhe para esta esquina sob o sol poente, a luz e a forma dos edifícios parecem muito com a pintura a óleo 'Cena da Rua Tingen'. Vamos ficar aqui um pouco?",
  [1152359321907712] = "Uma hora deve estar certa, vamos no tempo. Vamos partir?",
  [1152359321907456] = "Senhor, esta rota turística leva cerca de uma hora. Com o tempo, são 2 soli por hora, com 6 centavos para cada quarto de hora depois disso. Se for pela distância, são 4 centavos por quilômetro na cidade. Qual você acha que é melhor?",
  [1152359321907200] = "Sim, existe um lugar assim. No entanto, as “revelações” que eles dão são por vezes mais intrigantes do que a tarifa. Falando em tarifa, motorista, como calculamos essa viagem?",
  [1152359321906944] = "Howls Street... tem algum clube Adivinhação famoso lá?",
  [1152359321906688] = "De acordo com o percurso que acabamos de mencionar, vamos da Rua Zoutland até a Catedral de Santa Selena e depois voltamos pela Rua Howls; deveríamos ser capazes de ver quase todas as paisagens que valem a pena ver.",
  [1152359321906432] = "Pronto, são eles! Quem conhece os peixes melhor do que esses pequeninos? Se até eles puderem ser atraídos, significa que minha fórmula é realmente um sucesso!",
  [1152359321905664] = "... Peço desculpas pela minha grosseria anterior. Você está certo... eu te admiro.",
  [1152359321905408] = "Isso é incrível!",
  [1152359321905152] = "Um lampejo de sabedoria; você tocou a alma do poema.",
  [1152359321904896] = "Deixando seus pensamentos vagarem em direção à sua distante cidade natal... Meu Deus! Esta é exatamente a linha que o Imperador queria expressar, mas não conseguiu escrever!",
  [1152359321904640] = "...Uma cidade natal distante. Talvez coincida com a profunda nostalgia do Imperador nos seus últimos anos por um certo passado glorioso ao qual nunca poderia regressar.",
  [1152359321904384] = "E lentamente abaixou a cabeça, deixando seus pensamentos vagarem em direção à sua distante cidade natal.",
  [1152359321904128] = "<P_Heart> (Isso é... Pensamento de Noite Tranquila? Aham, por que o Imperador continua mexendo com uma pessoa...) </>",
  [1152359321903872] = "As regras são simples: adicione a linha final a este poema inacabado do Imperador Roselle – se puder.",
  [1152359321903616] = "Nossa, as coisas estão ficando sérias!",
  [1152359321903360] = "Vencedor! Isso é muito rude!",
  [1152359321903104] = "Novo amigo, já que seus insights são extraordinários, você se atreve a experimentar o “tesouro” do nosso clube? Estudamos este poema incompleto durante meses sem resposta.",
  [1152359321902848] = "Ah não, deixei minha imaginação correr longe demais...",
  [1152359321902592] = "Hmph! Que bobagem. Este é um clube de poesia, não uma sociedade para o estudo de existências ocultas!",
  [1152359321902336] = "Acho que é ele vendo os segredos do céu estrelado. 'Por medo de incomodar' mostra que ele viu algo que não deveria ter visto...",
  [1152359321902080] = "Hmph! É apenas mais uma interpretação inteligente. Uma verdadeira alma gêmea precisa ser capaz de ressoar com os pensamentos inacabados do Imperador!",
  [1152359321901824] = "Uma reviravolta brilhante.",
  [1152359321901568] = "Meu Deus, {ele{ela|}} faz com que pareça ainda mais razoável!",
  [1152359321901312] = "...Bem dito! De “Conquista” a “Awe”, esta interpretação torna o reino do poema subitamente claro!",
  [1152359321901056] = "O espanto não é covardia; decorre de uma sabedoria profunda – ligando-se ao conteúdo anterior, quanto mais ele conhece, mais entende que alguma tranquilidade não deve ser perturbada.",
  [1152359321900800] = "Acredito que isso expressa uma espécie de “admiração”.",
  [1152359321900544] = "<P_Heart> (Não ouse falar em voz alta, por medo de perturbar os seres celestiais? Oh, Imperador, Imperador...) </>",
  [1152359321900288] = "<P_Heart> (...Mas não me atrevo a falar alto, por medo de perturbar o sono dos deuses no céu.) </>",
  [1152359321900032] = "Novo parceiro, o que você acha?",
  [1152359321899776] = "Hmm, a perspectiva da senhorita Estella parece valer mais a pena explorar...",
  [1152359321899520] = "Talvez contenha também um traço de curiosidade pelo Reino de Deus e um desejo de tranquilidade?",
  [1152359321899264] = "Um ponto de vista muito poderoso. No entanto, sinto que falta um toque de... charme?",
  [1152359321899008] = "Uau! Sênior Victor está certo, isso é tão legal!",
  [1152359321898752] = "Isso não poderia ser mais óbvio! Isso é uma conquista! O Imperador está no auge que os mortais podem alcançar e emite uma declaração aos deuses.",
  [1152359321898496] = "Vamos deixar aqui. Talvez outra pessoa escreva uma história ainda mais brilhante!",
  [1152359321898240] = "Que livro de histórias mágico.",
  [1152359321897984] = "Que bom, vou me lembrar dessa história para sempre...",
  [1152359321897728] = "Hmm... vamos chamá-lo de <P_Yellow> 《A Bruxa e a Fera》 </>!",
  [1152359321897472] = "Eu vou te ajudar a registrar essa história, como você gostaria de chamá-la?",
  [1152359321897216] = "<P_Heart> (As palavras emergem lentamente) </> Embora seja uma loucura, tenho que admitir... é uma história maravilhosa.",
  [1152359321896960] = "Como foi? Eu dirigi isso muito bem, não foi?",
  [1152359321896448] = "Testemunhado pelos Intestinos de Porco Estufados com Mel, a bela e a fera finalmente se uniram.",
  [1152359321895936] = "<P_Heart> (Tirando um anel grosseiro) </> Senhorita Belle, você poderia...",
  [1152359321891840] = "Este é um prato dedicado aos doces companheiros. Por favor, aproveite!",
  [1152359321891584] = "A textura dos intestinos fatiados lembra um favo de mel cheio de doçura, mantendo uma textura em borracha e ao mesmo tempo oferecendo uma gordura rica e suculenta.",
  [1152359321891328] = "<P_Yellow> Intestinos de porco cozidos com mel! </>",
  [1152359321890560] = "Testemunhado pela Star-Gazing Pie, a bela e a fera finalmente se uniram.",
  [1152359321890304] = "Eu vou... eu vou!",
  [1152359321890048] = "Senhorita Belle, você poderia...",
  [1152359321889792] = "<P_Heart> (Lágrimas brilhando nos olhos) </> Da mesma forma aos meus olhos, embora você tenha presas e garras, você é mais parecido com um cavalheiro do que qualquer outro homem.",
  [1152359321889536] = "<P_Heart> (Abaixando o prato) </> Aos meus olhos, mesmo sendo homem, você é mais charmoso do que qualquer mulher.",
  [1152359321889280] = "Se você realmente não se importa, termine este prato para provar seu coração para mim.",
  [1152359321889024] = "Quer eu seja homem ou mulher, meus sentimentos por você nunca mudarão.",
  [1152359321887744] = "Senhorita Belle, o que você quer dizer...?",
  [1152359321887488] = "Para falar a verdade, sou como este prato. Embora tenha ingredientes ricos e pareça único na superfície, o sabor é... difícil de descrever...",
  [1152359321887232] = "Porque tenho algo a confessar a você.",
  [1152359321886976] = "Já que a reputação é tão ruim, por que viemos aqui?",
  [1152359321886720] = "Não admira que este lugar seja chamado de '<P_Yellow> o restaurante mais intragável de Tingen </> '!",
  [1152359321886464] = "Nunca comi nada tão terrível. Parece que meias sujas e ovos podres fermentaram juntos durante três dias e três noites – amargos, azedos e com uma doçura perturbadora.",
  [1152359321886208] = "<P_Heart> (Prova com cautela) </> Ugh—!",
  [1152359321885952] = "Este é um prato dedicado aos corajosos. Por favor, aproveite!",
  [1152359321885696] = "O bravo arenque olha para o céu estrelado com uma postura elegante, como se lembrasse o vento e as ondas do Mar Furioso.",
  [1152359321885440] = "<P_Yellow> Torta para contemplar as estrelas! </>",
  [1152359321885184] = "Respeitados senhoras e senhores, permitam-me a honra de apresentar-lhes a culinária original famosa em Tingen—",
  [1152359321884160] = "<P_Heart> (Tirando uma coleira linda) </> Haji-Ape, se você estiver disposto, deixe-me colocar esta coleira em você. Eu mesmo fiz isso.",
  [1152359321880576] = "Transcendendo o gênero, transcendendo as espécies, o amor deles agora é destemido!",
  [1152359321880320] = "Testemunhado pelo vaso sanitário e pela pia, a bela e a fera finalmente se uniram.",
  [1152359321880064] = "Claro, estou disposto!",
  [1152359321879808] = "<P_Heart> (Tirando um anel tosco) </> Senhorita Belle, se você estiver disposta, deixe-me colocar este anel em você. Eu mesmo fiz isso.",
  [1152359321879552] = "<P_Heart> (Lágrimas brilhando nos olhos) </> Obrigado, macaco Haki... Embora você tenha presas e garras, você é mais parecido com um cavalheiro do que qualquer outro homem.",
  [1152359321879296] = "Aos meus olhos, mesmo sendo homem, você é mais charmoso do que qualquer mulher.",
  [1152359321879040] = "...Desde o primeiro momento que te vi, não consegui tirar os olhos de você.",
  [1152359321878784] = "E você? Você vai se apaixonar por mim também?",
  [1152359321878528] = "Não é à toa que você é tão linda, fazendo com que todos os homens se apaixonem perdidamente por você.",
  [1152359321878272] = "Na verdade, eu sou um <P_Yellow> homem </> ... um homem que se transformou em uma <P_Yellow> Bruxa </> .",
  [1152359321878016] = "...Já que você descobriu, serei honesto com você.",
  [1152359321877760] = "Senhorita Belle... será que você tem o hábito de espiar?",
  [1152359321877504] = "Mas este é claramente o <P_Yellow> banheiro masculino </> ! Por que você está aqui?",
  [1152359321877248] = "<P_Heart> (Abre a porta impotente) </> ... Tudo bem, sou eu.",
  [1152359321876992] = "Senhorita Belle, abra a porta, eu vi claramente você entrando agora há pouco.",
  [1152359321876480] = "Senhorita Bela! Você está aí?",
  [1152359321875968] = "O prato exclusivo deste notório restaurante é...",
  [1152359321875456] = "Junto à pia, seu símbolo de amor é colocado...",
  [1152359321874944] = "Ato três: Eles finalmente <P_Yellow> conseguiram dar as mãos </> em um lugar maravilhoso. Este lugar é...",
  [1152359321874432] = "Haji-Ape, obrigado. Com você aqui, eu realmente me sinto seguro.",
  [1152359321874176] = "<P_Heart> (Enfiando as notas na boca de Henry) </> Como você ousa manchar a reputação da Srta. Belle com dinheiro imundo! Jamais permitirei que tal comportamento aconteça na minha frente.",
  [1152359321873664] = "Mas você não é nada forte. Um fraco como você nem está qualificado para amarrar os sapatos da Srta. Belle.",
  [1152359321873152] = "Uma mulher bonita e um homem forte – que combinação perfeita!",
  [1152359321872896] = "Senhorita Belle, contanto que você se torne minha mulher, poderá usar os vestidos mais caros, beber o melhor vinho tinto e viver confortavelmente como uma senhora rica em casa.",
  [1152359321872640] = "<P_Heart> (Tirando uma pilha de notas) </> Só no jogo desta noite, inúmeras pessoas fizeram apostas pesadas em mim. Posso ganhar mais dinheiro em uma luta do que gastaria durante toda a vida.",
  [1152359321869056] = "O ato de Haji-Ape dar um passo à frente trouxe lágrimas aos olhos de Belle. Naquele momento, um carinho inexplicável de repente cresceu em seu coração…",
  [1152359321868800] = "Haji-Ape, obrigado... Com você aqui, me sinto tão seguro!",
  [1152359321868544] = "Fotógrafo, tire algumas fotos desse idiota também. Quero que todos saibam o que acontece com aqueles que ofendem a Srta. Belle.",
  [1152359321868288] = "O que? Seu gorila feio, se tiver coragem, suba no palco! Vamos ver se não arranco todos os pelos do seu corpo bestial!",
  [1152359321868032] = "Mas um fraco como você nem sequer está qualificado para amarrar os sapatos da Srta. Belle.",
  [1152359321867776] = "Bem dito.",
  [1152359321867520] = "Somente o homem mais forte está qualificado para possuir Miss Belle.",
  [1152359321867264] = "Fotógrafo, tire algumas fotos desses idiotas também. Quero que todos saibam o que acontece com aqueles que me fazem inimigo.",
  [1152359321867008] = "Hmph, um bando de idiotas que não conhecem o seu lugar.",
  [1152359321866752] = "E daí se você é o campeão de boxe? Se você se atreve a desrespeitar Miss Belle, nós lhe mostraremos o que é!",
  [1152359321866496] = "Isso mesmo, senhorita Belle é a deusa que pertence a todos nós, como podemos permitir que você coloque o dedo nela.",
  [1152359321866240] = "Eu recuso. Não tenho interesse em alguém tão hipócrita quanto você.",
  [1152359321865984] = "Senhorita Belle, você será minha mulher agora?",
  [1152359321865728] = "Daquele momento em diante, jurei que, mais cedo ou mais tarde, faria algo de mim mesmo e a possuiria.",
  [1152359321865472] = "Há dois anos, convidei a senhorita Belle para passar uma noite maravilhosa juntos, mas levei um tapa forte por isso.",
  [1152359321865216] = "Senhorita Bela!",
  [1152359321864960] = "Devo meu sucesso a uma pessoa, e esta é—",
  [1152359321864704] = "Sr. Henry, você tem algum discurso de aceitação?",
  [1152359321864448] = "Henrique! Henrique! Campeão de Boxe Henry!",
  [1152359321864192] = "Gritemos o nome dele: Campeão de Boxe Henry!",
  [1152359321715456] = "Estranho, por que eu estava trabalhando agora quando é hora de descansar?",
  [813709740384512] = "O que está acontecendo?",
  [1152359321463552] = "É como dizem as lendas, o vento faz um som como um suspiro quando passa perto da estátua...",
  [1152359321322240] = "Cozinhar! \"Rei dos Chefs\"! Na verdade, eu conheci você pessoalmente!",
  [1152359321306880] = "Você ainda não sabe? Gourmet Massimo escreveu um artigo que fez do chef daqui, Cook, um sucesso. Estamos todos aqui para provar a comida.",
  [813709740337920] = "O que aconteceu?",
  [1152359321977600] = "<P_Heart> (hesitante) </> Você ainda está bem financeiramente? Ouvi dizer que Benson trabalha no departamento financeiro em Backlund; seu trabalho está indo bem?",
  [1152359321846528] = "Você não pode deixar isso de lado!",
  [1152359321831168] = "Ok, eu vou te ajudar. Alguma pista? <P_Heart> (Deixá-lo com metade do corpo exposto assim certamente assustará alguém.) </>",
  [1152359321860608] = "...Não me force a amaldiçoar.",
  [1152359321860352] = "Então, antes que o cabelo caia, tome a iniciativa! Raspe tudo com antecedência e você nunca mais terá que se preocupar com queda de cabelo!",
  [1152359321860096] = "Mm-hmm, tesoura... e depois?",
  [1152359321859840] = "Eu uso essa tesoura há dez anos; eles funcionam perfeitamente. Vou entregá-los a você agora.",
  [1152359321859584] = "Suspiro... Nesse caso, tenho uma última solução.",
  [1152359321858048] = "As palavras de Haji-Ape trouxeram lágrimas aos olhos de Belle e, sem saber, um afeto inexplicável começou a crescer entre eles...",
  [1152359321857792] = "Haji-Ape, cara...",
  [1152359321857536] = "Contanto que você pergunte, mesmo que eu tenha que tirar todo o meu pelo e virar uma codorna pronta para a panela, eu faria isso de boa vontade.",
  [1152359321857280] = "Senhorita Belle, foi você quem me trouxe liberdade. O que é um pouco de cabelo comparado a isso?",
  [1152359321857024] = "Haji-Ape, pelo meu bem, você realmente estaria disposto a desistir do seu cabelo?",
  [1152359321856768] = "Hmm... observei com atenção. Este seu animal de estimação tem pêlo grosso, brilhante e preto. Sua qualidade é de uma em um milhão – o material perfeito para transplantes capilares.",
  [1152359321856512] = "Não vou esconder isso de você, todos os pelos do meu corpo crescem rápido e são longos e duros. Se eu não o cortasse várias vezes ao dia, os outros pensariam que eu era um ouriço.",
  [1152359321856000] = "Estou disposto!",
  [1152359321855744] = "Tal pessoa talvez não fosse encontrada em toda Tingen e, mesmo que existisse, quem estaria disposto a abrir mão do cabelo?",
  [1152359321855488] = "É muito difícil... a menos que você encontre uma garota com cabelos extremamente exuberantes e qualidade de cabelo perfeita, então eu poderia realizar uma cirurgia de transplante capilar para você.",
  [1152359321855232] = "Minha cara senhora, se um médico pudesse inventar uma cirurgia que tratasse a queda de cabelo sem nenhum custo, ele se tornaria imediatamente o homem mais rico de Loen.",
  [1152359321854976] = "Será que não tem como ter o melhor dos dois mundos?!",
  [1152359321854464] = "Sim, causará queda severa de cabelo...",
  [1152359321854208] = "Esse frasco também não tem efeitos colaterais, não é mesmo?",
  [1152359321853952] = "Mas a boa notícia é: o frasco da direita vai curar a sua pele.",
  [1152359321853696] = "Que assustador! Minha pele é tão preciosa quanto meu cabelo, não deve ser perdida de forma alguma!",
  [1152359321853440] = "Mas seus efeitos colaterais são inevitáveis. Sua pele começará a rachar e a mudar de cor, assim como o gesso de parede velho e negligenciado.",
  [1152359321853184] = "Que ótimo, é isso que eu quero!",
  [1152359321852928] = "O frasco de remédio à esquerda pode restaurar a vitalidade vibrante do couro cabeludo e seu cabelo crescerá descontroladamente como videiras na primavera.",
  [1152359321852672] = "Suspiro, já que é esse o caso, aqui estão dois frascos de remédios especiais, que desenvolvi exclusivamente. Talvez eles possam ajudá-lo.",
  [1152359321852416] = "Doutor, por favor, pense em um jeito!",
  [1152359321852160] = "Não! — Se eu perder meu lindo cabelo e ficar careca, que sentido restará em minha vida!",
  [1152359321851904] = "...Mas a sua <P_Yellow> queda de cabelo </> é muito grave, eu realmente não posso fazer nada a respeito.",
  [1152359321851648] = "Doutor, contanto que você possa curar minha doença, estou disposto a pagar qualquer quantia em dinheiro.",
  [1152359321851392] = "Suspiro, verifiquei com cuidado agora há pouco, sua situação não é otimista...",
  [1152359321850880] = "No canto do ringue de boxe tem um item importante...",
  [1152359321850368] = "Há um suporte importante na mesa de operação...",
  [1152359321849856] = "O segundo ato, uma <P_Yellow> grande crise </> está prestes a chegar, e o amor deles nasce na crise. A localização desta crise é...",
  [1152359321849600] = "<P_Heart> (...a cor da aura de Ed realmente mostra que ele está sofrendo de uma doença grave... será que nem ele sabe que está gravemente doente?) </>",
  [1152359321849344] = "Tudo bem!",
  [1152359321849088] = "Vou levá-los de volta para a delegacia. Entraremos em contato com o dono da loja sobre os produtos que você comprou após ser enganado para negociar devoluções e reembolsos. Iremos notificá-lo para vir buscar seu dinheiro de volta.",
  [1152359321848832] = "Não seja ingênuo, não gaste dinheiro, cuidado com fraudes!",
  [1152359321848576] = "Desconfie de estranhos puxando conversa, mantenha a cabeça limpa!",
  [1152359321848320] = "Incrível! Na semana passada, o Sr. Jessie, do Distrito Leste, acreditou ingenuamente na filosofia de investimento da gangue. Ele pagou sete vezes em três dias e foi fraudado em um total de 500 libras!",
  [1152359321848064] = "O jornal diz: Incrível! Na semana retrasada, a Sra. White, do distrito de Gold Oak, “abriu” sua carteira para a gangue. Sete dias de namoro e ela foi fraudada em um total de 100 libras.",
  [1152359321847808] = "Fraude... turma?!",
  [1152359321847552] = "{Sr.{Sra.|}}, essas duas pessoas são membros de uma gangue fraudulenta que tem perambulado por Tingen recentemente. Você não foi enganado, não é?",
  [1152359321847296] = "De onde veio a polícia? E...Ed!",
  [1152359321847040] = "Não desperdice seu esforço, você está preso por fraude!",
  [1152359321846784] = "Não se mova! Comportar-se!",
  [1152359321846272] = "Deixando de lado o gênero...",
  [1152359321553664] = "Eu vou cuidar de tudo, você só precisa dizer 'eu vou'.",
  [1152359321845504] = "Desculpe, pensei que isso fosse um lixo que alguém não queria.",
  [1152359321845248] = "Chegou um tio de aparência rude, o tio também está usando as roupas da cor combinada! O tio se aproximou! O tio negociou com a avó!",
  [1152359321844992] = "Chegou uma vovó linda... a vovó está com a roupa da cor combinada! Ela se aproximou! Ela pegou as flores!",
  [1152359321844736] = "Veio uma tia linda, não, não é isso.",
  [1152359321844480] = "Chegou uma menina linda, não, não é isso.",
  [1152359321844224] = "Bom! Bem cantado! Esta é a flor que você queria! Que você encontre doçura e romance!",
  [1152359321843968] = "Você, você me admira...",
  [1152359321843712] = "Nossa, você realmente não quer cantar? Todo mundo cantou, sabe?",
  [1152359321843456] = "Você cantou tão bem, essa é a flor que você queria! Que você encontre doçura e romance!",
  [1152359321843200] = "Você, você me admira... Eu, eu te admiro, essa floricultura é doce como mel!",
  [1152359321842944] = "<P_Heart> (Por que sinto uma sensação inexplicável de vergonha...) </>",
  [1152359321842688] = "Você me admira, eu te admiro, essa floricultura é doce como mel! Vamos lá, experimente!",
  [1152359321842432] = "Comprar música—começar—",
  [1152359321842176] = "Você tem uma música de loja?",
  [1152359321841920] = "Super surpresa! Hoje é dia de promoção da nossa floricultura. Contanto que você cante a música da loja bem alto, você poderá obter um desconto!",
  [1152359321841664] = "Olá, quero um buquê de lírios.",
  [1152359321841408] = "Por que você não disse isso agora mesmo!",
  [1152359321841152] = "Na verdade, só descobri depois dos vinte e cinco anos que nossa família tem várias propriedades em Backlund, e minha família nunca bebe café barato, e há um Relógio da Ordem a apenas dois passos de casa.",
  [1152359321840896] = "Ah, então é filha em tempo integral... Hmm?!",
  [1152359321840640] = "Filha em tempo integral.",
  [1152359321840384] = "Que tipo de trabalho é tão bom?",
  [1152359321840128] = "Então encontrei um emprego com bom salário e pouco trabalho.",
  [1152359321839872] = "O chefe sempre diz que está um pouco decepcionado comigo. Ele me contratou como balconista porque viu o potencial que mostrei durante a entrevista. Ele espera que, depois que eu ingressar, eu possa trabalhar duro e rapidamente me tornar um vendedor de ponta... Não, é cansativo, cansativo demais.",
  [1152359321839616] = "Não me pergunte, hoje é meu último dia de trabalho. Não há futuro em trabalhar em uma joalheria.",
  [1152359321839104] = "Olá, quero o anel mais novo e mais caro.",
  [1152359321838592] = "Você é realmente... muito gentil! Se possível, você poderia pagar as compras para mim primeiro? Saí com pressa e preciso voltar para pegar minha carteira... Te espero aqui!",
  [1152359321838336] = "...Pode funcionar.",
  [1152359321838080] = "Seu rosto está cheio de integridade. Será que você poderia me ajudar a comprar um anel e um buquê e recusar meu amigo por correspondência para mim?",
  [1152359321837824] = "OK. <P_Heart> (Tão perfumado, um paciente pode realmente usar tanto perfume...) </>",
  [1152359321837568] = "Você é realmente muito gentil! Se possível, você poderia pagar as compras para mim primeiro? Saí com pressa e preciso voltar para pegar minha carteira... Te espero aqui!",
  [1152359321837312] = "Posso ajudá-lo a comprar o anel e o buquê e recusar seu amigo por correspondência para você.",
  [1152359321837056] = "<P_Heart> (Ele está pálido e sua aura está turva; ele realmente está morrendo, ele não parece estar mentindo...) </>",
  [1152359321836800] = "Se estou destinado a morrer, não ver seu lindo rosto será meu maior arrependimento!",
  [1152359321836544] = "Quero tanto comprar o anel mais caro e as flores mais brilhantes para a data... mas isso seria irresponsável demais. Devo fazê-la me esquecer!",
  [1152359321836288] = "Ela disse que iria à livraria no Distrito Leste, vestindo roupas marrons escuras, e pegaria a ficha de lírio que lhe entreguei.",
  [1152359321836032] = "Desculpe, sinto muito em ouvir isso.",
  [1152359321835776] = "Mas tenho uma doença terminal e minha vida está chegando ao fim...",
  [1152359321835520] = "Eu te perturbei? Meu nome é Ed. Meu amigo por correspondência, meu tesouro, meu amor, meu pequeno lírio, quer me conhecer...",
  [1152359321835264] = "Para quem você está se desculpando?",
  [1152359321835008] = "Sinto muito, meu amigo por correspondência, meu tesouro, meu amor, meu pequeno lírio...",
  [1152359321834752] = "Isso é só o começo, é só esperar e ver, a trama a seguir será ainda mais explosiva!",
  [1152359321834240] = "Apenas me diga, é bom ou não?",
  [1152359321833984] = "Adaptação não é edição aleatória e dramatização não é bobagem! Como ousa blasfemar contra as obras do Imperador Roselle!",
  [1152359321833728] = "Tudo bem, eu admito, só queria mostrar minhas habilidades, não esperava... tosse tosse, tenho um assunto urgente! Adeus!",
  [1152359321833472] = "Bem... uh... não é mais... mais estiloso não seguir o caminho comum?",
  [1152359321833216] = "Espere, acabei de olhar, há claramente caminhos em ambos os lados para contornar. Por que você teve que atravessar a parede?",
  [1152359321832960] = "Muito obrigado! Aqui, esta é a chave conforme prometido, o baú do tesouro é seu.",
  [1152359321832704] = "Tente lançar 'Open Door' ao contrário; já que você pode entrar, você pode voltar.",
  [1152359321832448] = "Não entre em pânico, concentre-se e pense na sensação de atravessar uma parede!",
  [1152359321832192] = "Um, dois, três – empurre!",
  [1152359321831936] = "Tenha paciência, vou expulsá-lo diretamente!",
  [1152359321831680] = "<P_Heart> (Qual método devo usar para tirar Carmen da parede?) </>",
  [1152359321831424] = "Sua pose é única... tudo bem, como posso encontrá-la?",
  [1152359321830912] = "Minha parte inferior do corpo ainda está presa na parede, preciso encontrá-la primeiro. Você pode me ajudar a procurar? Deveria estar por aqui.",
  [1152359321553408] = "Você tem família, não quero ser esse tipo de mulher.",
  [1152359321828864] = "Garotão, qual é o seu nome?",
  [1152359321828608] = "Uau-! Parabéns, linda senhora. Acredito que isso definitivamente lhe trará retornos inesperados.",
  [1152359321828352] = "Um bando de coitados, não se aproximem se não tiverem dinheiro.",
  [1152359321828096] = "O que! Essa mulher é louca!",
  [1152359321827840] = "Eu lancei 5.000 libras de ouro.",
  [1152359321827584] = "Eu lancei 650 libras de ouro!",
  [1152359321827328] = "Eu lancei 600 libras de ouro!",
  [1152359321827072] = "O lance inicial é de apenas 500 libras!",
  [1152359321826816] = "Seja para ser um bandido quando você está fora ou um guarda-costas para proteger sua casa, todas são escolhas muito confiáveis!",
  [1152359321826560] = "Embora seu poder de combate e força física sejam muito elevados, sua personalidade é muito gentil e obediente.",
  [1152359321826304] = "Não tenha medo, ele era originalmente uma pessoa normal, mas foi acidentalmente afetado pelo poder de um Artefato Selado e se transformou em um gorila aterrorizante.",
  [1152359321826048] = "Um homem-macaco amaldiçoado!",
  [1152359321825792] = "Senhoras e senhores, por favor abram bem os olhos—",
  [1152359321825536] = "Todo mundo sabe que nosso negócio é muito especial, mas garanto que ninguém nunca viu esse próximo item.",
  [1152359321822208] = "Desde então, estou hospedado neste apartamento e quase nunca saio.",
  [1152359321821696] = "Claro que não... na verdade, eu também sou humano.",
  [1152359321821440] = "Não esperava que um gorila falante morasse aqui. Você escapou de um circo?",
  [1152359321821184] = "Embora eu tenha uma pistola para autodefesa, ela não contém balas. Eu me escondi aqui em pânico e depois desmaiei...",
  [1152359321820928] = "No meu caminho para casa ontem à noite, um estranho continuou me seguindo...",
  [1152359321818624] = "E a história deles apenas começou...",
  [1152359321818368] = "A partir de então, Haji-Ape se tornou o guarda-costas número um de Belle, sempre seguindo-a de perto.",
  [1152359321818112] = "Haji-Ape... embora não saiba o que significa, gosto desse nome.",
  [1152359321817856] = "A partir de hoje, você será chamado de <P_Yellow> Haji-Ape </> !",
  [1152359321817600] = "Então deixe-me dar-lhe um nome—",
  [1152359321817344] = "Eu esqueci.",
  [1152359321817088] = "Não se preocupe. A propósito, qual é o seu nome?",
  [1152359321816832] = "...Isso funcionará?",
  [1152359321816576] = "Se a polícia bater na porta, direi apenas que você é meu animal de estimação, que tal?",
  [1152359321816320] = "Com uma grande beleza como eu, quem teria tempo de olhar para você?",
  [1152359321816064] = "Receio que isso não funcione. A última vez que saí, assustei o Sr. William escada abaixo até que ele desmaiou e quase fui pego pela polícia.",
  [1152359321815808] = "Que pena, você deveria me seguir de agora em diante, eu vou te levar para sair.",
  [1152359321815552] = "Desde então, estou hospedado neste apartamento e quase nunca saio.",
  [1152359321815296] = "Há três anos, fui acidentalmente afetado pelo poder de um Artefato Selado, e é por isso que fiquei assim...",
  [1152359321815040] = "Claro que não! Na verdade, também sou humano... pelo menos costumava ser.",
  [1152359321814784] = "Não esperava que meu vizinho fosse um gorila falante. Você escapou de um circo?",
  [1152359321814528] = "Eu estava de mau humor ontem à noite e acidentalmente bebi demais, então fiquei tonto e fui para a porta errada.",
  [1152359321814272] = "Certo, lembro agora!",
  [1152359321814016] = "Para ser sincero, também estou um pouco confuso sobre a situação.",
  [1152359321813760] = "Mas esta é realmente a minha casa. Como você entrou?",
  [1152359321813504] = "Uh... desculpe, sou tímido desde criança.",
  [1152359321813248] = "Uma mulher fraca e um gorila gigante na mesma sala – não importa como você olhe, sou eu quem está em perigo, certo?",
  [1152359321812992] = "...Por favor, eu deveria estar gritando.",
  [1152359321812736] = "Quem é você!? Por que você está deitado na minha cama!",
  [1152359321812480] = "Ah-!!",
  [1152359321811712] = "Os itens desta casa de leilões são...",
  [1152359321811200] = "Muito bom, preparativos concluídos. Podemos começar a apresentação.",
  [1152359321810944] = "Há um suporte importante ao lado do travesseiro...",
  [1152359321810432] = "Muito bom. A seguir, vamos configurar os adereços.",
  [1152359321810176] = "O primeiro ato é o encontro entre a Bela e a Fera; eles <P_Yellow> se conheceram pela primeira vez </> em...",
  [1152359321809920] = "O palco é seu. Eu gostaria de ver que tipo de história você consegue inventar!",
  [1152359321809664] = "Agora você é o diretor. Você pode organizar a <P_Yellow> cena </> e <P_Yellow> adereços </> como desejar, e os atores seguirão suas instruções.",
  [1152359321809408] = "E a Besta?",
  [1152359321809152] = "Beleza?",
  [1152359321808896] = "O que é isso no palco...",
  [1152359321808640] = "<P_Heart> (Letras grandes de raiva) </> Você não aceita, certo? Tudo bem, tudo bem, tudo bem! Aqui está a caneta, você escreve!",
  [1152359321808384] = "É realmente tão incrível? Pelos padrões de hoje, a história é um pouco clichê.",
  [1152359321808128] = "Principalmente ‘A Bela e a Fera’, que pode ser considerado o romance de amor mais profundo e comovente do mundo; os homens ficam em silêncio depois de ler! As mulheres derramaram lágrimas depois de ler!",
  [1152359321807872] = "Por que tão surpreso? Sou apenas um livro comum que brilha e escreve... O que realmente vale a pena admirar é o mundo escrito pelo Imperador Roselle - aquele mundo rico, colorido e vasto que deixa as pessoas obcecadas!",
  [1152359321807616] = "De repente há texto! Este livro pode escrever sozinho?!",
  [1152359321807360] = "<P_Heart> (Um texto brilhante aparece) </> Isso mesmo, \"A Bela e a Fera\" é a história de amor de maior sucesso escrita pelo Imperador Roselle!",
  [1152359321807104] = "<P_Yellow> \"A Bela e a Fera\" </> ? Olhando a assinatura, esta também é uma obra do Imperador Roselle...",
  [1152359321806848] = "Mas você só está mais na moda do que eu hoje, então só pode sentar aqui hoje!",
  [1077660176359424] = "Sucesso",
  [1152359321806592] = "Tudo bem, admito que você tem as qualificações para sentar aqui.",
  [1152359321806336] = "Você ainda não atende ao código de vestimenta aqui. Volte na próxima vez.",
  [1152359321806080] = "Mas não tenho tempo para ensinar o básico.",
  [1152359321805824] = "Coitadinha, quero muito te ensinar o que é moda...",
  [1152359321805568] = "Nós definitivamente voltaremos!",
  [1152359321805312] = "Não, impossível! Como poderia haver alguém em Tingen mais elegante do que nós!",
  [1152359321805056] = "Obrigado novamente por sua generosidade! Venha comigo no trem para nossa casa!",
  [1152359321804800] = "Obrigado! Gentil {Sr.{Sra.|}}.",
  [1152359321804544] = "Pegue esse dinheiro.",
  [1152359321804288] = "Tem alguém aí? Vamos verificar.",
  [1152359321804032] = "Lua! Pare de se esconder de mim!",
  [1152359321803776] = "Este é o lugar; Luna deveria estar esperando por mim.",
  [1152359321803520] = "<P_Heart> É realmente verdade? </> Que Deus abençoe você e sua família. Quanto a esta casa, estou disposto a pagar por ela.",
  [1152359321803264] = "<P_Heart> 10.000 libras de ouro?? Tão barato, talvez seja uma farsa, vamos fazer um adivinhação para ver. </>",
  [1152359321803008] = "Agora, por apenas 10.000 soli, você pode se tornar o novo dono desta mansão.",
  [1152359321802752] = "Esta mansão já foi a glória da minha família. Embora tenha sido lavado pelo tempo, ainda tem um apelo encantador. Se não fosse o meu filho ter uma enorme dívida de jogo e estar gravemente doente, eu não teria vendido a mansão por um preço baixo.",
  [1152359321802496] = "Respeitado {Sr.{Sra.|}}, com licença por um momento. Será que você tem um carinho especial por história e arte? Tenho uma mansão excepcionalmente única em mãos e estou procurando alguém destinado a herdar sua história.",
  [1152359321802240] = "<P_Heart> (Ele solta um gemido confortável, se inclina contra você e abaixa a cabeça para cheirar a comida.) </>",
  [1152359321801728] = "Venha aqui e coma alguma coisa.",
  [1152359321801472] = "Como esperado... ainda não posso simplesmente deixar você para trás.",
  [1152359321801216] = "<P_Heart> (Ele solta um gemido desapontado enquanto observa você se afastar.) </>",
  [1152359321800704] = "Desculpe, pequenino, tenho coisas para fazer e não posso ajudá-lo.",
  [1152359321800448] = "Esse carinha parece que está morrendo de fome...",
  [1152359321800192] = "<P_Heart> (Um grito fraco e suplicante; ele inclina a cabecinha para olhar para você.) </>",
  [1152359321799680] = "Esse garotinho... está encharcado.",
  [1152359321799424] = "\"Miau...\" <P_Heart> (Um miado fraco e suplicante, sua cabecinha molhada esfregada na ponta dos dedos). </>",
  [1152359321799168] = "Vamos fazer um adivinhação para ver se o banheiro é a entrada.",
  [1152359321798912] = "Quando eu estava investigando a Praça Central de Tingen com o Capitão Frye, entrei em um espaço de conhecimento relacionado a Roselle. Poderia haver um espaço de conhecimento aqui também?",
  [1152359321798656] = "A Campanha Patriótica de Saúde... essa é a campanha mencionada no diário do Imperador Roselle!",
  [1152359321798400] = "<P_Heart> (Olhe para o abismo e você poderá ir para o paraíso.) </>",
  [1152359321798144] = "<P_Heart> (Suas mãos, sua saúde, seu país... Campanha Patriótica de Saúde... todos são responsáveis.) </>",
  [1152359321797888] = "<P_Heart> (Um zumbido em meus ouvidos... acabei de... adquirir conhecimento em um banheiro?) </>",
  [1152359321797632] = "<P_Heart> Ele pode estar aqui também; vamos dar uma olhada. </>",
  [1152359321797376] = "<P_Heart> Teatro da Inspiração do Sr. Speer? </>",
  [1152359321797120] = "Distintos convidados, por favor tomem seus lugares o mais rápido possível. \"O Retorno do Conde\" está prestes a começar!",
  [1152359321796608] = "O Sr. Speer também pode ter sido transportado para cá. Vamos em frente e procurá-lo.",
  [1152359321796352] = "O Capitão Frye disse uma vez que alguns Artefatos Selados podem criar espaços anormais; talvez esse manuscrito tenha tal habilidade.",
  [1152359321796096] = "O Teatro da Inspiração do Sr. Speer?",
  [1152359321795840] = "Por favor, tomem seus lugares o mais rápido possível, <P_Yellow> 'O Retorno do Conde' </> está prestes a começar!",
  [1152359321795584] = "Senhoras e senhores, bem-vindos ao <P_Yellow> Teatro da Inspiração do Sr. Speer </> !",
  [1152359321795328] = "Minha cabeça dói... onde é esse lugar?",
  [1152359321795072] = "Espero que ele consiga se formar sem problemas, sem ter que refazer seus dados experimentais.",
  [1152359321794816] = "Vamos! Ouvi dizer que hoje há um prato novo no refeitório.",
  [1152359321794560] = "Amigo, você descobriu isso tão rapidamente.",
  [1152359321794304] = "Já que chegou a esse ponto, vamos ao refeitório comer! Rex, você vem também.",
  [1152359321794048] = "Que a Deusa me proteja; contanto que eu trabalhe continuamente em minha pesquisa, com certeza me formarei!",
  [1152359321793792] = "Estranho, por que eu estava tão ansioso agora?",
  [1152359321793280] = "<P_Heart> (Ele está muito ansioso, é hora de ajudá-lo a se livrar de algum fardo psicológico!) </>",
  [1152359321793024] = "Vivendo assim, você também está sendo arruinado lentamente.",
  [1152359321792768] = "Ele tem muito poder na faculdade. Tenho medo que ele simplesmente me expulse e minha vida fique arruinada!",
  [1152359321792512] = "Por que você simplesmente não registra uma reclamação? A faculdade cuidará disso.",
  [1152359321792256] = "Descansar? Esse é o privilégio do professor.",
  [1152359321792000] = "Você deveria descansar. Se continuar assim, você ficará doente.",
  [1152359321791744] = "O professor rasgou os dados experimentais que passei a noite toda organizando e me pediu para entregar um novo para ele hoje...",
  [1152359321791488] = "Portanto, captar as emoções mais primitivas, simples e intensas no fundo do coração das pessoas é a chave para o sucesso de um trabalho.",
  [1152359321791232] = "Justamente por isso, ‘vingança’ é a trama mais contagiante, e ‘O Conde de Monte Cristo’ pode se tornar um clássico de classe mundial.",
  [1152359321790976] = "Não importa a época ou o mundo, “o bem é recompensado com o bem e o mal é recompensado com o mal” é um conceito de justiça com o qual todos sempre concordarão.",
  [1152359321790720] = "As dificuldades são apenas o prelúdio para um retorno. Vamos! Chegou a hora do cheat do protagonista aparecer!",
  [1152359321790464] = "Fugas de prisões, encontros, dedos de ouro, lacunas de informação... muitos tropos posteriores foram levados adiante daqui.",
  [1152359321790208] = "'O Conde de Monte Cristo' é de fato o ancestral dos romances satisfatórios, é tão gratificante copiá-lo.",
  [1152359321789952] = "Quanto às falas principais, por que não prestar homenagem a uma cena lendária...",
  [1152359321789696] = "Esse é exatamente o sentimento de humilhação que desejo, especialmente nesta sociedade onde os nobres correm soltos; o povo de Intis certamente irá concordar com isso.",
  [1152359321789440] = "O tropo do “noivado rompido” é realmente uma grande invenção no mundo dos romances na web. É perfeito para modificar o início de 'O Conde de Monte Cristo'.",
  [1152359321789184] = "Também deixei um grande problema para você, ele será desbloqueado automaticamente quando você estiver cercado, aguarde ansiosamente.",
  [1152359321788928] = "Agora você pode sentir o aprimoramento de seus atributos de combate.",
  [1152359321788672] = "Não, é isso?",
  [1152359321788416] = "Vou te dar uma ideia!",
  [1152359321788160] = "É assim mesmo? Então não saia daí.",
  [1152359321787904] = "Não parece ter nenhum sentimento real?",
  [1152359321787648] = "Apresse-se e encontre a fonte do jargão!",
  [1152359321787392] = "No espaço do conhecimento, o texto tem usos maravilhosos, pegue-o primeiro!",
  [1152359321787136] = "Em que o cadáver se transformou? Texto?",
  [1152359321786880] = "<P_Heart> (Esta mulher é realmente... não, por que estou começando a ansiar pelo que acontecerá a seguir?) </>",
  [1152359321786624] = "Bem-vindo ao meu mundo, Conquistador.",
  [1152359321786368] = "Não...",
  [1152359321786112] = "Não resista, ela está esperando por você.",
  [1152359321785856] = "Não tenha medo, venha até mim...",
  [1152359321785600] = "Não, a corrupção não desapareceu completamente – ainda há algo escondido nas profundezas da pintura!",
  [1152359321785344] = "Quem... quem está falando?",
  [1152359321785088] = "Venha aqui... chegue um pouco mais perto...",
  [1152359321784832] = "Como esperado, esta não é uma pintura a óleo comum, é—",
  [1152359321784576] = "Finalmente saiu... o que vem pela frente?",
  [1139165182846976] = "Tolo que não pertence a esta época",
  [1152359321784320] = "Isto é... um lenço perfumado?",
  [818041751511808] = "Olá?",
  [1152359321784064] = "Hum? Onde está aquela linda senhora?",
  [1152359321783808] = "Vulnerável, hum hum.",
  [1152359321783552] = "Esqueça, vamos voltar e reportar primeiro ao Capitão Frye.",
  [1152359321783296] = "Escapou? Hmph, ela realmente tinha outros motivos.",
  [1152359321783040] = "A corrupção foi eliminada e todos voltaram ao normal. Porém, e Madame Vera?",
  [1152359321782784] = "Sinto que tive um sonho muito longo...",
  [1139165182782464] = "Então o que devo fazer?",
  [1152359321782528] = "...O que aconteceu? Por que estou aqui?",
  [1152359321782272] = "Voltei...",
  [1152359321782016] = "Que tal responder a essas perguntas? Talvez possamos nos encontrar novamente...",
  [1152359321781760] = "Ah, é isso mesmo? Não percebi... mas como você é tão atencioso...",
  [1152359321781504] = "Senhora, você esqueceu seu lenço!",
  [1152359321781248] = "Oh? Você está procurando por mim?",
  [1152359321780992] = "Ela caminhou por aqui?",
  [1152359321780736] = "Sua Majestade, você precisa se refrescar? Aqui está uma garrafa de Refrescante Flower Dew.",
  [1152359321780480] = "Minha cabeça está tão tonta...",
  [1152359321779968] = "Entre, garanto que você também vai se apaixonar por esse tipo de ‘perigo’.",
  [1152359321779712] = "<P_Heart> (As coisas não são simples aqui, devo ter cuidado.) </>",
  [1152359321779456] = "<P_Heart> (Um traço de flutuação espiritual... Ela também é uma Beyonder? Espero que ela não seja uma inimiga...) </>",
  [1152359321779200] = "O amor é a coisa mais perigosa deste mundo. E o Spring Night Salon sempre vendeu esse tipo de ‘perigo’.",
  [1152359321778688] = "Ah... aquele pobre Barão, ele também foi morto de amor.",
  [1152359321778432] = "Olá, sou um oficial do Departamento de Polícia do Condado de Awwa. Preciso entender algumas informações sobre o caso do Barão Stephan.",
  [1152359321778176] = "Sou o dono do Salão Noturno de Primavera; você pode me chamar de Madame Vera.",
  [1152359321777920] = "Eu-me desculpe. Quem é você?",
  [1152359321777664] = "Você está aqui? Apenas me siga!",
  [1152359321777408] = "Sr. Speer?",
  [1152359321777152] = "É uma carta enviada pelo Capitão Frye... e um jornal?",
  [1152359321776896] = "{{PlayerName}}, você tem um pacote da Blackthorn Security Company.",
  [1152359321776640] = "...Obrigado por ouvir, o intervalo acabou, tenho que continuar jogando.",
  [1152359321776384] = "Agora 'Night Visit' se tornou a peça que toco melhor.",
  [1152359321776128] = "Estou muito confuso com essa história, mas ela nunca mais apareceu depois que terminou de contá-la... Estive em Backlund e disseram que tinham visto alguém parecido no banquete de Eder, mas o príncipe já havia morrido há muito tempo.",
  [1152359321775872] = "O final de uma bela história não deveria ser que todos conseguissem o que queriam e vivessem uma vida melhor?",
  [1152359321775616] = "E por esse amor irracional, os protagonistas masculino e feminino caminham voluntariamente em direção à morte, o que me faz entender ainda menos... Se vocês não podem passar o resto da vida juntos, então qual é o significado do amor?",
  [1152359321775360] = "Só posso pensar que essa pessoa está amaldiçoada ou controlada. Em suma, isso não é razoável.",
  [1152359321775104] = "Mas eu não entendo, {Sr.{Sra.|}}, você não acha que o amor é apenas uma artimanha do destino? Como pode existir uma coisa tão absurda como o amor à primeira vista, fazendo com que as pessoas estejam dispostas a dar tudo por um estranho?",
  [1152359321774848] = "Ela me contou uma história de amor para compensar a lacuna em minha experiência emocional — para explicar, não acho que isso seja uma falha.",
  [1152359321774592] = "Minha professora me disse que para jogar bem 'Visita Noturna', devo acreditar no amor e no sacrifício, acreditar na dor e nas mentiras.",
  [1152359321774336] = "<P_Heart> (A atmosfera ficou tão pesada...) </>",
  [1152359321774080] = "Às vezes, não há diferença entre eles, não é?",
  [1152359321773824] = "No amor, por trás da alegria e da paixão, muitas vezes há uma dor correspondente.",
  [1152359321773568] = "Você já ouviu o poema escrito por Roselle? 'O amor é um pássaro livre, ninguém pode domesticá-lo.'",
  [1152359321773312] = "Será que eu joguei muito mal...",
  [1152359321773056] = "<P_Heart> (Seus olhos transmitem frustração.) </>",
  [1152359321772800] = "Uh... música de piano?",
  [1152359321772544] = "O que você ouviu?",
  [1152359321772288] = "<P_Heart> (Melhor esperar ela terminar de brincar...) </>",
  [1152359321772032] = "Obrigado por ouvir!",
  [1152359321771776] = "\"Isso me deixaria ainda mais feliz.\"",
  [1152359321771520] = "\"Se você quer tudo que eu tenho...\"",
  [1152359321771264] = "\"Meu amor-\"",
  [1152359321771008] = "\"Você quer ouro, pedras preciosas ou terras?\"",
  [1152359321770752] = "\"Mesmo que o que transparece em seus olhos estreitos não seja alegria.\"",
  [1152359321770496] = "\"Vejo que você tem um coração de ouro.\"",
  [1152359321770240] = "\"O amante de bochechas redondas é toda a minha felicidade.\"",
  [1152359321769984] = "\"O amante de bochechas redondas é toda a minha felicidade.\"",
  [1152359321769728] = "Está tudo bem, não acho que isso seja importante. Por que você não me deixa ouvir sua música, que tal?",
  [1152359321769472] = "(Se isso continuar, essas crianças vão começar a discutir, tenho que distraí-las...)",
  [1152359321769216] = "Eu me lembro agora também, hum hum. E também lembro que o príncipe não se chama Ed-pizza, ele se chama Ed-yo-sak!",
  [1152359321768960] = "Eu adivinhei! Deusa, um nobre e carinhoso príncipe se apaixonou por uma garota de rosto redondo e escreveu uma linda canção de amor para ela... Essa é realmente uma linda história, com certeza eles ficarão muito felizes.",
  [1152359321768704] = "Tingen é impossível, caso contrário com certeza saberíamos – lembro-me agora, a irmã Sarah disse que isso tem algo a ver com Sua Alteza o Príncipe! O príncipe parece se chamar... Ede-pizza?",
  [1152359321768448] = "Como poderia ser Intis! A Irmã disse que a língua que os Intis falam é diferente da nossa! E essa peça é tão feliz! Parece que é do nosso Loen.",
  [1152359321767424] = "Irmã Sarah ensinou para nós, chama-se ‘Visita Noturna’, hehe.",
  [1152359321767168] = "Preciso pensar sobre isso antes de tomar uma decisão.",
  [1152359321766912] = "(Eu simplesmente sinto que o preço por trás de tal história definitivamente me levará a ser enganado...)",
  [1152359321766656] = "(Isso vai durar para sempre... e tenho a sensação de que vou ser enganado...) Preciso pensar sobre isso antes de tomar uma decisão.",
  [1152359321766400] = "Qual preço você está disposto a pagar?",
  [1152359321766144] = "Qual é o seu preço?",
  [1152359321765888] = "Qual é o seu preço psicológico?",
  [1152359321765632] = "Qual é o seu preço mínimo?",
  [1152359321765376] = "Qual é a sua expectativa?",
  [1152359321765120] = "De qualquer forma, {Sr.{Sra.|}}, quanto você está disposto a pagar por esta caixa de música?",
  [1152359321764864] = "Alguns dizem que aquela mulher morreu há muito tempo, e outros dizem que ela deixou Loen, o lugar do desgosto, por amor... Parece um fantasma.",
  [1152359321764608] = "Algumas pessoas também pensam que veio do Príncipe Edessak, que cometeu suicídio para escapar da punição. Para Loen, ele era um pecador, mas para o círculo social, um príncipe obcecado por uma bela e misteriosa plebeia contribuiu com muitas fofocas.",
  [1152359321764352] = "Ninguém sabe quem é o compositor, se é uma mulher ou um homem, um plebeu ou um nobre. Mas algumas pessoas até ouviram marinheiros tocarem no mar, apenas para o navio ser atacado naquele mesmo dia.",
  [1152359321764096] = "Alguns nobres mais tradicionais não gostam desta peça, achando que a sua disposição é um pouco frívola. Mas mais pessoas acham que parece misterioso e elegante, perfeito para ser usado como acompanhamento de conversas privadas em ambientes sociais.",
  [1152359321763840] = "Esta peça se chama 'Visita Noturna'. Um pretendente de uma nobre encomendou-o como presente, usando a melodia de 'Visita Noturna' para comemorar o momento em que foi cativado pelo amor.",
  [1152359321763584] = "Acho que esta caixa de música deve corresponder à sua descrição.",
  [1152359321763328] = "Primeiro deng, deng deng deng deng, depois deng deng deng deng deng.",
  [1152359321762816] = "Hmm... temos uma caixa de música cheia de histórias.",
  [1152359321762560] = "Esta loja não vende pianos... mas acho que o som que você ouviu deve ter vindo de uma de nossas caixas de música.",
  [1152359321762304] = "Música? Você ainda se lembra de como é?",
  [1152359321762048] = "A entrada fica no ponto mais alto.",
  [1152359321761792] = "Te espero na entrada do corredor do Bar Bravehearts. Eu lhe darei uma recompensa, bem como uma apresentação gratuita. Acredite, você definitivamente vai querer ouvir.",
  [1152359321761536] = "Essas notas contêm emoções intensas ou têm letras que valem a pena cantar. Espero que você os proteja quando encontrar perigo.",
  [1152359321761280] = "Esta melodia não é minha criação. Eu acidentalmente ouvi uma doce jovem chamada Trissy cantarolar em Backlund há muitos anos.",
  [1152359321736192] = "Ele se autodenominava... Sr.",
  [1152359321735936] = "Ele me disse que se eu usasse esses sapatos de dança ritualizados, todos se apaixonariam por mim.",
  [1152359321735680] = "Fui ouvido quando estava orando e aquele homem me ensinou um ritual.",
  [1152359321735424] = "Quem te transformou em um monstro?",
  [1152359321735168] = "Mas eu trouxe dor para muitas pessoas!",
  [1152359321734912] = "Obrigado por me libertar da minha dor.",
  [1152359321734656] = "Este par de sapatos deve ser a fonte da maldição.",
  [1152359321734400] = "Mais tarde, fui engolido pelo monstro...?",
  [1152359321734144] = "Eu estava fazendo hora extra à noite e vi aquele homem, e aí veio o monstro... mais tarde...",
  [1152359321733888] = "Um homem encapuzado trouxe de volta os sapatos de dança.",
  [1152359321733632] = "Os sapatos de dança! Tia cometeu suicídio pulando no incinerador com aqueles sapatos! À noite, os sapatos de dança voltaram a aparecer na fábrica têxtil!",
  [1152359321733376] = "Então... então...",
  [1152359321733120] = "Tia, a pobre menina, perdeu a cara no baile e foi expulsa por eles. Ela até perdeu o emprego e outras trabalhadoras também a condenaram ao ostracismo.",
  [1152359321732864] = "Hehe, esses jovens mestres, apenas dizendo algumas palavras bonitas, podem enganar as garotas da fábrica até elas ficarem tontas.",
  [1152359321732608] = "Ela é operária da fábrica e o jovem patrão da fábrica a convidou para ir ao baile.",
  [1152359321732352] = "Quem é ela? Por que você acha que ela está se vingando de você?",
  [1152359321731840] = "Deve ser ela. Ela está se vingando de nós?",
  [1152359321731584] = "Na noite em que despedimos a Tia, apareceu um monstro invisível.",
  [1152359321731328] = "O que aconteceu aqui? Como você morreu?",
  [1152359321731072] = "Minha Deusa... Jess, acorde! Venha salvar alguém!!!",
  [1152359321730816] = "Acabou, Jack... na verdade eu estava lutando, não atuando...",
  [1152359321730560] = "...Sou apenas um cidadão comum com senso de justiça. Será que tudo isso é apenas uma brincadeira?!",
  [1152359321730304] = "Você é o verdadeiro ator temporário? Então quem é esse...",
  [1152359321730048] = "Desculpe a todos, aconteceu algo em casa, então acabei de chegar. Vamos começar a filmar... espere, você já terminou?",
  [1152359321729792] = "Jack? Por que você não está dizendo nada? Jack?",
  [1152359321729536] = "Esfriou recentemente em Tingen e o solo ainda está muito frio à noite. Quase congelei e levantei cedo agora há pouco.",
  [1152359321729280] = "Além disso, Jack, você deveria se levantar também. Não deite no chão.",
  [1152359321729024] = "Essa cena já acabou, por que você ainda está imerso nela? Acorde, é hora de bater o ponto.",
  [1152359321728768] = "E você... não ia chamar a polícia? Por que você veio sozinho?",
  [1152359321728512] = "Espere... você já não foi morto por Jack, o Estripador?",
  [1152359321728256] = "Na verdade, embora houvesse muitas partes um pouco improvisadas, o desempenho geral foi brilhante.",
  [1152359321728000] = "Parece que os atores temporários são bastante profissionais. Capitão Brown, o que você acha?",
  [1152359321727744] = "Eu também não pretendia deixar você ir embora. Já que você viu essa cena esta noite, é melhor deixar sua vida aqui!",
  [1152359321727488] = "Maldito Jack, o Estripador, vou acabar com seus crimes esta noite!",
  [1152359321727232] = "Já que você viu essa cena esta noite, é melhor deixar sua vida aqui também!",
  [1152359321726976] = "É assim mesmo? Gostaria de ver o que o famoso detetive pode fazer comigo.",
  [1152359321726720] = "Tal como disse o Imperador Roselle: 'Todas as más ações serão descobertas um dia, mesmo que todo o solo da terra as cubra!'",
  [1152359321726464] = "Mas agora que conheci um demônio como você aqui, não tenho motivo para deixá-lo ir e tirar mais vidas inocentes!",
  [1152359321726208] = "Não tenho passado e não sei nada sobre suas antigas lendas.",
  [1152359321725952] = "A pessoa que sou agora é um demônio com cabeça humana.",
  [1152359321725696] = "Só posso caminhar através do sangue em direção ao inferno, ouvindo as palavras dos demônios, nunca acreditando na chamada “consciência”.",
  [1152359321725440] = "Minhas mãos estão manchadas de sangue há muito tempo e meus pés estão mergulhados em uma poça de sangue.",
  [1152359321725184] = "Você acha que pode abalar meu coração com isso?",
  [1152359321724928] = "Seu louco... Para a segurança de outras pessoas em Tingen, seja como Vigia Noturno ou como cidadão comum, vou impedi-lo!",
  [1152359321724672] = "Conhecido como o mais terrível Jack, o Estripador da história de Loen, pegarei esta lâmina manchada de sangue novamente e tirarei mais vidas!",
  [1152359321724416] = "Lembrar? Eu, que apareci em Tingen há vinte e um anos e cometi vários assassinatos em série—",
  [1152359321724160] = "Tanto tempo se passou e parece que você finalmente percebeu um rastro meu, mas aos meus olhos, tudo isso foi em vão.",
  [1152359321723904] = "Muito tempo sem nos ver, meu aclamado detetive.",
  [1152359321723392] = "Não tem problema, então vamos começar.",
  [1152359321723136] = "A esquerda. Sou canhoto, então estou mais acostumado a matar com a mão esquerda.",
  [1152359321722880] = "Aqui estou, Jack. Seria melhor para mim morrer à esquerda ou à direita mais tarde?",
  [1152359321722624] = "Vamos, Liana, eu deveria matar você.",
  [1152359321722368] = "Sim, estou esperando por você há muito tempo. Eu sou Jack, o Estripador. É hora de começar a trabalhar.",
  [1152359321722112] = "Você finalmente veio?",
  [1152359321721856] = "É perigoso aqui! Jack, o Estripador, está por perto, todos vocês devem sair rapidamente!",
  [1152359321721600] = "Droga, poderia ser mesmo ele... O tempo está se esgotando. Vou dar uma olhada lá. Obrigado pela informação!",
  [1152359321721344] = "Não há criança em Tingen que não tenha ficado assustada com essa história pela mãe quando era pequena!",
  [1152359321721088] = "Vinte e um anos atrás, o 'Açougueiro Sangrento - Jack, o Estripador', que matou cinco meninas seguidas, destruindo o coração de algumas e o estômago de outras!",
  [1152359321720832] = "{Sr.{Sra.|}}, você nunca ouviu falar disso? É isso—",
  [1152359321720576] = "Um serial killer?",
  [1152359321720320] = "Também vi um homem e uma mulher passando por aqui. O traje daquele homem realmente me lembra o caso do serial killer que chocou toda a cidade de Tingen!",
  [1152359321720064] = "Ah, sim, estava bem ali.",
  [1152359321719808] = "Olá, um grito veio desta direção?",
  [1152359321719552] = "Onde está seu distintivo policial? Só acredito no que vejo com meus próprios olhos. Sem um crachá para provar sua identidade, você é o suspeito, não é?",
  [1152359321719296] = "Na verdade, sou um detetive disfarçado do Departamento de Polícia do Condado de Awwa. Alguém relatou que um serial killer está na área e estou aqui para fazer uma prisão.",
  [1152359321719040] = "Obrigado por ajudar em meu trabalho.",
  [1152359321718784] = "Eu vejo. Você realmente é um policial. Falando em suspeito... acho que acabei de ouvir um grito vindo de lá.",
  [1152359321718528] = "É um mal-entendido. Na verdade, sou oficial do Departamento de Polícia do Condado de Ahoava. Alguém disse que um serial killer apareceu aqui e eu vim fazer uma prisão.",
  [1152359321718016] = "Pessoas suspeitas? Para ser sincero, poucas pessoas aparecem nesta estrada no meio da noite. Você parece um estranho; na verdade, você se parece mais com esse tipo de pessoa suspeita.",
  [1152359321717760] = "Olá, você viu alguma pessoa suspeita?",
  [1152359321717504] = "Ah, esqueça! {Sr.{Sra.|}}, por favor, tenha cuidado, tente atrasá-lo o máximo possível, irei imediatamente à delegacia de polícia mais próxima para obter ajuda!",
  [1152359321717248] = "Por que tão rápido? Muito imprudente. Provavelmente ainda não é hora de chamar a polícia...",
  [1152359321716992] = "Assassinato?! Você vai chamar a polícia, eu vou verificar a situação primeiro!",
  [1152359321716736] = "Não há tempo! Jack, o Estripador, está prestes a matar alguém, vá rápido!",
  [1152359321716480] = "Lá? O que está acontecendo?",
  [1152359321716224] = "Você finalmente chegou! Depressa, depressa, depressa, vá até lá, que bom que você conseguiu!",
  [1152359321715968] = "Vamos, vamos ao cais comer batatas fritas juntos.",
  [1152359321715712] = "Amigo, você finalmente descobriu.",
  [1152359321715200] = "Não importa, dirigir é uma coisa boa. Vamos arregaçar as mangas e trabalhar duro juntos!",
  [1152359321714688] = "Para minha família! Para amanhã!",
  [1152359321714432] = "Por que estou descansando aqui?! Eu deveria estar ocupado, pela minha família, amanhã!",
  [1152359321714176] = "<P_Heart> Por que minha cabeça dói um pouco de repente? </>",
  [1152359321713920] = "<P_Heart> Minha cabeça está um pouco tonta... </>",
  [1152359321713664] = "O item místico 'Dedos da Destreza' criado pelos artesãos Clube do Tarô pode roubar pensamentos do cérebro de outra pessoa. Podemos tentar roubar a ideia dele de trabalhar duro.",
  [1152359321713408] = "Exatamente, descansar é legal. Ele trabalhou por muito tempo.",
  [1152359321713152] = "O item místico 'Dedos da Destreza' criado pelos artesãos Clube do Tarô pode roubar pensamentos do cérebro de outra pessoa. Podemos tentar isso.",
  [1152359321712896] = "Eles estão na idade em que precisam trabalhar duro. É hora de roubar seus pensamentos preguiçosos.",
  [1152359321712640] = "Mas o portão da fábrica está cheio de gente nova da Rua Cruz de Ferro. Se não trabalharmos duro, poderemos perder este emprego a qualquer momento.",
  [1152359321712384] = "Mesmo que trabalhemos de manhã à noite, o nosso salário semanal é de apenas 20 soli.",
  [1152359321712128] = "Ei amigo, relaxe. Descansar é legal.",
  [1152359321711872] = "A infusão de conhecimento do Sábio Oculto... Não, isso vai destruir meu cérebro. Preciso da ajuda do Sr. Tolo!",
  [1152359321711616] = "\"Por favor, olhe para mim, olhe para este humilde buscador de conhecimento!\"",
  [1152359321711360] = "\"...Avatar do Conhecimento - o grande Sábio Oculto...\"",
  [1152359321711104] = "“Minha cabeça está prestes a explodir… Magia Ritual, conhecimento oculto…”",
  [1152359321710848] = "\"Sua voz está ecoando em meus ouvidos...\"",
  [1152359321710592] = "Poderia ser um <P_Yellow> item místico </> formado pela combinação de um Beyonder após a morte e os livros ao redor? Parece que precisa ser selado.",
  [1152359321710336] = "Uma capa feita de pele humana, um livro cheio de magia ritual...",
  [1152359321710080] = "Elogie a sopa de bucha!",
  [1152359321709824] = "Muito obrigado! Você é simplesmente {{Rei das Buchas | Rainha das Buchas}}. Vou preparar uma tigela de sopa de bucha para beber quando chegar em casa esta noite.",
  [1152359321709568] = "Ótimo! Todas as buchas de hoje estão esgotadas!",
  [1152359321709312] = "<P_Heart> Vou ter que fazer mais sopa de bucha agora. </>",
  [1152359321709056] = "Todos, não se apressem. Compre buchas e você terá uma receita de sopa de bucha, venha dar uma olhada!",
  [1152359321708800] = "Deixe-me provar!",
  [1152359321708544] = "(Hawking) Aproxime-se, não perca, degustação de sopa de bucha grátis! Reduz o calor interno e é saudável!",
  [1152359321708288] = "Compre buchas e ganhe uma receita, aqui está!",
  [1152359321708032] = "Podemos apenas conversar sobre as coisas adequadamente; Eu também estava errado. Compre algumas buchas, vamos para casa fazer uma sopa e podemos conversar enquanto comemos.",
  [1152359321707776] = "Essa sopa de bucha é tão deliciosa, por que eu estava tão agitado agora há pouco...",
  [1152359321707520] = "Quer experimentar nossa sopa de bucha? Pode reduzir o calor interno.",
  [1152359321707264] = "Pare de discutir. O tempo tem estado seco ultimamente, é fácil ficar inflamado; pode ser que o fogo do seu fígado esteja muito alto.",
  [1152359321707008] = "Como você pode falar comigo com essa atitude? Você não era assim antes.",
  [1152359321706752] = "O que você quer dizer!",
  [1152359321706496] = "Boa ideia-",
  [1152359321706240] = "Que tal convidarmos os clientes para provar mais tarde e depois vendermos as buchas enquanto fazemos isso? Os compradores podem obter a receita!",
  [1152359321705984] = "Quero comprar algumas dessas buchas!",
  [1152359321705728] = "Esta é uma sopa secreta de bucha. Além de delicioso, também pode reduzir o calor interno e regular o corpo!",
  [1152359321705472] = "Como você fez isso? As buchas podem realmente ter um gosto tão bom!",
  [1152359321705216] = "É uma delícia, muito saboroso!",
  [1152359321704960] = "Experimente!",
  [1152359321704704] = "<P_Heart> Na minha memória, é assim que deveria ser feito... preciso adicionar bastante MSG para ficar saboroso o suficiente... </>",
  [1152359321704192] = "Posso emprestar-me a sua panela e as suas buchas? Deixe-me tentar.",
  [1152359321703936] = "<P_Heart> Posso fazer uma sopa de bucha para diminuir o calor interno e convidar todo mundo para provar! </>",
  [1152359321703680] = "<P_Heart> Deixe-me pensar, buchas... </>",
  [1152359321703424] = "<P_Heart> Eu entendo agora. É porque as receitas aqui são limitadas e só vender buchas não tem truque. Eu tenho uma ideia. </>",
  [1152359321703168] = "Buchas? Não, não, as buchas não ficam gostosas quando cozidas.",
  [1152359321702912] = "Senhor, venha ver essas buchas frescas!",
  [1152359321702656] = "Todas essas buchas parecem fofas e frescas, por que ninguém as compra?",
  [1152359321702400] = "Este é meu primeiro dia de venda e não tive um único cliente. Como devo reportar ao meu pai?",
  [1152359321701888] = "(Murmurando) As buchas não estão vendendo, {{esse gentil Sr.|essa gentil Sra.}}, você pode me ajudar? Por favor.",
  [1152359321701632] = "(Hawking) Cultivados em casa, saudáveis ​​e higiênicos, vendendo barato!",
  [1152359321701376] = "(Hawking) Aproxime-se, não perca, venha ver essas buchas fresquinhas!",
  [1152359321701120] = "Não tenha medo, vou acompanhá-lo de volta.",
  [1152359321700864] = "Dormitório da fábrica têxtil, há monstros na névoa negra! Não consigo ver nada!",
  [1152359321700608] = "Acalme-se, senhorita. Onde fica sua casa?",
  [1152359321700352] = "{{PlayerName}}, o que você descobriu?",
  [1152359321700096] = "Essa, essa garota...",
  [1152359321699840] = "Venha, descanse, durma...",
  [1152359321699328] = "\"Deusa!\" Se ela ouvir, ela definitivamente concordará.",
  [1152359321699072] = "A lua cheia carmesim surge, refletindo sobre a terra.",
  [1152359321698816] = "A seguir, orarei por você. Que a Deusa lhe conceda paz.",
  [1152359321698560] = "Obrigado, já entendi o Sequência dos acontecimentos.",
  [1152359321698304] = "Tudo bem, então voltarei e otimizarei. Espero convidá-lo a experimentá-lo novamente na próxima vez.",
  [1152359321698048] = "Não é muito divertido. Um jogo bastante fracassado.",
  [1152359321697792] = "Como é a sensação?",
  [1152359321697536] = "Oh não, Sua Majestade! Por causa da mudança de seu rosto, seus sujeitos não o reconhecem. Lide com os soldados que se aproximam e escape primeiro!",
  [1152359321697024] = "Independentemente disso, você obteve o que queria—",
  [1152359321696512] = "Sou apenas um espelho, Majestade. As pessoas não podem pedir a um espelho para distinguir entre beleza e feiúra, a menos que você possa conversar com pequenos animais e ter lábios rosados, pele comparável à neve e 7 servos anões...",
  [1152359321696256] = "Isso não é nada bonito.",
  [1152359321696000] = "Não é?",
  [1152359321695744] = "Você acha que isso está certo?",
  [1152359321695488] = "Ah, claro, não há problema. Vou realizar um ajuste facial para você agora mesmo—",
  [1152359321695232] = "Eu quero ficar bonito. Não, espere, eu quero a versão em que eu fique bonito, sem efeitos colaterais, sem custos, com uma família harmoniosa e com muita saúde.",
  [1152359321694976] = "Há algo que este servo leal possa fazer por você, Majestade?",
  [1152359321693952] = "Majestade, você já é tão perfeito... Mas atenderei todos os seus pedidos. Vou invocar o Espelho do Mistério para você—",
  [1152359321693440] = "Atualmente, o Reino Goose está temporariamente <P_Yellow> desfrutando de um clima favorável </>. Você pode realizar <P_Yellow> uma </> tarefa hoje. O que você pretende fazer?",
  [1152359321692928] = "Esta noite, você bebe e dança com a bruxa, passando uma noite maravilhosa...",
  [1152359321692672] = "Venha, Majestade, vamos nos divertir esta noite.",
  [1152359321692416] = "Como uma bruxa em treinamento não é uma bruxa?",
  [818107787034880] = "Por que a estaca de madeira ficou tão curta? É quase como sentar no chão.",
  [1152359321692160] = "...? Não é você, irmão mais velho...?",
  [1152359321691392] = "Uma escolha esperada! Afinal, ninguém resiste ao encanto de uma bruxa... Vou convocar uma bruxa para você agora, Majestade.",
  [818107786768128] = "Quando ele voltar, vou dizer-lhe o que penso!",
  [1161155682786560] = "Quem está falando?",
  [1152359321690368] = "Suas conexões mudaram... (+1 Ressentimento de Opinião Pública, +1 Ressentimento Militar, ganhou 'Hipocrisia Ministerial')",
  [1152359321690112] = "Não estou agradando ninguém – o domínio do imperador está se manifestando em você!",
  [1152359321689856] = "Suas conexões mudaram... (+1 Influência Nobre, +1 Ressentimento da Opinião Pública, +1 Ressentimento Militar)",
  [1152359321689600] = "Suas conexões mudaram... (+1 Favor de Opinião Pública, +1 Ressentimento Militar)",
  [1152359321689344] = "Suas conexões mudaram... (+1 Favor Militar, +1 Ressentimento da Opinião Pública)",
  [1125971310798592] = "Então, sobre a saída...",
  [1152359321689088] = "Um excelente imperador muitas vezes equilibra o poder entre os seus ministros. No passado, você foi esfaqueado nas costas pelos seus ministros. Desta vez, o que você pretende fazer?",
  [1152359321688832] = "Suas estatísticas aumentaram! (+1 Vigor, +1 Ressentimento do Sujeito)",
  [1152359321688576] = "Suas estatísticas aumentaram! (+2 Ressentimento do Assunto)",
  [1152359321688320] = "Suas estatísticas aumentaram! (+1 Social, +1 Ressentimento do Assunto)",
  [1152359321688064] = "Suas estatísticas aumentaram! (+1 Charme, +1 Ressentimento do Sujeito)",
  [1152359321687808] = "Seu gerenciamento de estatísticas anterior foi muito lamentável; pode-se dizer que foi um fracasso total. Desta vez, o que você pretende fazer?",
  [1152359321687552] = "Atualmente, o Reino Goose está temporariamente <P_Yellow> desfrutando de um clima favorável </>. Você pode realizar <P_Yellow> três </> tarefas hoje. O que você pretende fazer?",
  [1152359321687296] = "Venha, transforme o Reino Ganso no reino mais próspero e torne-se um imperador cujo nome ficará para a história!",
  [1152359321687040] = "A Deusa gostou de você, permitindo que você obtenha o sistema, que sou eu, e pode lhe dar uma ajuda maior.",
  [1152359321686784] = "Você renasceu, renasceu três meses antes de ser deposto. Desta vez, você recuperará tudo o que lhe pertence.",
  [1152359321686528] = "Vamos ignorar esses detalhes e começar nosso jogo—",
  [1152359321686272] = "(Olhando em volta) ...É evidente que alguém que nunca viveu uma vida boa não consegue imaginar como é um palácio magnífico.",
  [1152359321686016] = "Este é o palácio! Você sabe? Do tipo realmente magnífico e enorme.",
  [1152359321685760] = "Onde é isso?",
  [1152359321685504] = "Uma pessoa de bom gosto! Primeiro, por favor, feche os olhos...",
  [1152359321685248] = "Parece bom. Como posso experimentar isso?",
  [1152359321684992] = "...Embora eu não possa fazer isso acontecer para você, tenho um jogo que permite que você se torne o Imperador e experimente a sensação de ser admirado por milhares de pessoas!",
  [1152359321684736] = "Eu quero governar o mundo.",
  [1152359321684480] = "Ei! Você tem algum desejo não realizado que é difícil de satisfazer? Algum arrependimento que pesa em seu coração? Vamos, tenho aqui todos os tipos de jogos que podem permitir que você experimente uma vida diferente!",
  [1152359321684224] = "<P_Yellow> Histórias 'refrescantes' são a busca comum de diferentes pessoas em mundos diferentes! </>",
  [1152359321683968] = "Sem problemas. Afinal, o Imperador Roselle disse uma vez—",
  [1152359321683712] = "Ah? Mas esse não parece ser o estilo do professor. Escrever assim funcionará?",
  [1152359321683456] = "Não se preocupe, o Sr. Speer disse que se inspirou no manuscrito do Imperador Roselle e está se preparando para criar uma história mais emocionante e estimulante.",
  [1152359321683200] = "Isso afetará o trabalho futuro do professor? Os atores da trupe estão esperando para ensaiar.",
  [1152359321682944] = "No entanto, sua mente ainda não se recuperou totalmente e ele terá que descansar um pouco recentemente.",
  [1152359321682688] = "O tratamento psicológico correu muito bem. Eu curei sua histeria.",
  [1152359321682432] = "(Vindo de fora da porta) Policial, como está a professora?",
  [1152359321682176] = "A corrupção foi esclarecida e o Sr. Speer deverá acordar em breve.",
  [1152359321681920] = "Parece bom. Parece que é hora de voltarmos.",
  [1152359321681664] = "Espero que sim... Queimarei meus manuscritos e retornarei às dobras descartadas como 'vulgares' para escrever uma obra verdadeiramente comovente. Quando chegar a hora, vou convidar vocês para assistirem juntos.",
  [1152359321681408] = "Não é tarde demais para entender agora.",
  [1152359321681152] = "Não há deuses ou imperadores nesta peça do Imperador Roselle, apenas um marinheiro com um casaco grosso. Suas linhas ásperas quebraram como pedras a cúpula de vidro em que acreditei durante toda a minha vida.",
  [1152359321680896] = "As esculturas em pedra da Terceira Época no museu são lindas, sim, mas não se pode mais ouvir o pulsar do sangue dentro delas.",
  [1152359321680640] = "Mas hoje você me fez perceber o problema: os tempos mudaram há muito tempo e o drama deveria mudar junto com eles.",
  [1152359321680384] = "Décadas atrás, aprendi todas as técnicas do teatro tradicional com meu professor. Agora, eu também ensino isso ao meu Aprendiz.",
  [1152359321680128] = "Obrigado por me ajudar a terminar esta peça. Graças a você, agora tenho muitos novos insights e inspirações...",
  [1152359321679872] = "Que ótima peça. Essas duas horas foram como se eu tivesse vivido uma vida inteira.",
  [1152359321679616] = "Isso foi brilhante. Meu coração está por um fio desde o primeiro ato, e só agora finalmente se acalmou.",
  [1152359321679360] = "Tudo o que resta conhecido no mundo é a lenda do retorno do Conde...",
  [1152359321679104] = "Comprou o 'Pharaon' daquela época, renovou-o e zarpou mais uma vez, mas ninguém sabe para onde foi.",
  [1152359321678848] = "[As luzes diminuem lentamente] Depois de treze anos, Dantes finalmente completou sua vingança. Ele se sentiu aliviado, mas exausto.",
  [1152359321678336] = "Tenha medo, arrependa-se e passe todos os dias em um destino pior que a morte!",
  [1152359321678080] = "O esquecido voltou, e seus mastros e ganchos são a sua forca!",
  [1152359321677824] = "Nenhuma quantia de dinheiro pode redimir a injustiça e o tormento que engoli na prisão escura, nem pode suportar a espada da vingança que lancei com meu próprio sangue e poli com meus ossos.",
  [1152359321677568] = "Essa sua ninharia não é suficiente nem para reformar meu banheiro.",
  [1152359321677312] = "Haha – olhe para o seu estado patético, é realmente cômico.",
  [1152359321677056] = "Ofereço tudo a você, só peço que tenha misericórdia. Prometo voltar para minha cidade natal imediatamente e nunca mais aparecer diante de você...",
  [1152359321676800] = "Estas são as economias da minha vida, um total de <P_Yellow> três milhões de libras de ouro </> ...",
  [1152359321676544] = "Conde, eu imploro... eu imploro... poupe-me...",
  [1152359321676288] = "Tão satisfatório! É porque há muitos funcionários como este que as nossas vidas são tão miseráveis!",
  [1152359321676032] = "Entregarei as provas ao departamento de polícia, jogarei você, um promotor corrupto e abandonado que incriminou inocentes, na prisão, e deixarei você passar o resto da sua vida lá!",
  [1152359321675776] = "Eu imploro... eu imploro...",
  [1152359321675520] = "É isso mesmo, você perseguiu uma nobre senhora naquela época pelo bem de sua carreira, estrangulou o bebê que sua ex-mulher acabara de dar à luz e enterrou-o debaixo da árvore em frente à porta. Já desenterrei aquela caixa!",
  [1152359321675264] = "Excelência, você descobriu...",
  [1152359321675008] = "Sr. Villefort, a casa onde estou morando agora é considerada sua antiga residência?",
  [1152359321674752] = "Exatamente! E ele ainda ousa falar de honra nobre? O rosto dele está mais sujo do que uma bota pisada num chiqueiro!",
  [1152359321674496] = "Seu hipócrita de duas caras, pretendo ver você ser abandonado por todos, fazer com que sua esposa e filhos tenham vergonha de você e transformá-lo em um vagabundo desgraçado.",
  [1152359321674240] = "Conde, você também pode me matar com um tiro. Perder a honra de um nobre é mais assustador para mim do que a morte.",
  [1152359321673984] = "Sr. Fernand, o senhor foi um desertor na guerra e confiou na traição de seus camaradas e superiores para obter mérito militar, mas encontrei um sobrevivente da guerra e ele exporá tudo isso no parlamento!",
  [1152359321673728] = "Bom trabalho! Levar alguém à morte por mero ciúme – que o sol transforme esta alma sombria e feia em cinzas!",
  [1152359321673472] = "Seu avarento ganancioso e ciumento, pretendo que você perca a riqueza que acumulou ao longo da vida e se torne um indigente sem um tostão.",
  [1152359321673216] = "Conte, você absolutamente não pode fazer isso! Isso fará com que o Intis Ocean Bank vá à falência imediatamente!",
  [1152359321672960] = "Sr. Danglars, decidi desistir do investimento no projecto ferroviário do Continente Sul e retirar todos os meus depósitos do Intis Ocean Bank.",
  [1152359321672704] = "O final é que o marinheiro passou por uma provação de vida ou morte e finalmente se transformou em um conde fantasmagórico, diante de todos vocês, exercendo um direito que lhe pertence, o direito mais legítimo e precioso—",
  [1152359321672448] = "Conde, qual é o final desta história?",
  [1152359321671936] = "Todos viveram boas vidas, aparentemente tendo esquecido completamente o marinheiro que jogaram no masmorra...",
  [1152359321671680] = "O contador do navio tornou-se <P_Yellow> gerente de banco </>, o promotor do porto foi promovido a <P_Yellow> Procurador Real </>, e o jovem nobre não apenas se casou com sua bela prima, mas também se tornou um <P_Yellow> membro do parlamento </> do reino.",
  [1152359321671424] = "Muitos anos depois, os <P_Yellow> três vilões </> que o incriminaram tornaram-se figuras proeminentes—",
  [1152359321671168] = "O pobre marinheiro foi repentinamente preso pela polícia durante sua cerimônia de noivado e jogado em uma prisão escura e sem sol...",
  [1152359321670912] = "Um <P_Yellow> jovem nobre </> que guardava rancor do marinheiro juntou forças com ele, agindo como fiador para entregar a carta ao promotor, e subornou pesadamente o <P_Yellow> promotor </> para contornar o tribunal e condenar o marinheiro inocente diretamente.",
  [1152359321670656] = "A história começa em um navio mercante no Mar Berserk. Há um jovem marinheiro que é favorecido pelo velho capitão e está prestes a ser promovido a capitão, mas o <P_Yellow> contador do navio </> está com ciúmes e fabrica uma carta de denúncia cruel.",
  [1152359321670400] = "Que coincidência. Todos nós vivemos em Port Lesel e conhecemos muitos marinheiros. Por favor, conte-nos a história.",
  [1152359321670144] = "A história de um marinheiro? Estou muito interessado. Muitos anos atrás, também servi como contador em um navio.",
  [1152359321669888] = "Boa tarde, senhores. Convidei você aqui hoje para compartilhar uma história— <P_Yellow> a história de um marinheiro azarado </>.",
  [1152359321669632] = "Boa tarde, conde.",
  [1152359321669376] = "Tudo perdido... Eu entendo, experimentei a paixão e o desejo ardentes nos corações do público. Este é o verdadeiro significado do drama!",
  [1152359321669120] = "Chegou o momento de _______; Vou recuperar tudo o que perdi!",
  [1152359321668864] = "Agora está tudo pronto; o conde voltou!",
  [1152359321668608] = "No entanto, ele nunca esqueceu seu ódio profundo por um único momento. Após anos de investigação cuidadosa, ele descobriu a verdade e encontrou os inimigos que o incriminaram.",
  [1152359321668352] = "Ao mesmo tempo, sua erudição e comportamento gracioso conquistaram os nobres de Intis, permitindo-lhe conhecer muitas figuras proeminentes da alta sociedade.",
  [1152359321668096] = "Depois que Dantes mudou de identidade, ele não só comprou grandes extensões de terras e feudos e foi intitulado Conde, mas também investiu em fundos e ações, tornando-se um grande banqueiro em Trier.",
  [1152359321667840] = "... Verdadeiramente maravilhoso, até eu estou começando a ansiar pela trama subsequente, o Imperador Roselle é realmente um gênio em contar histórias.",
  [1152359321667584] = "Olha a sua falta de ambição, mesmo com todo esse dinheiro, o mais importante é descobrir a verdade daquele ano!",
  [1152359321667328] = "Uau! Tanto dinheiro, se eu fosse Dantes, hehe... hehe...",
  [1152359321667072] = "Esconderei meus rastros e planejarei lentamente... Quando eu retornar, será o dia em que a verdade será revelada e o mal será destruído!",
  [1152359321666816] = "No entanto, aqueles que expressam seu ódio de forma imprudente muitas vezes acabam bebendo vinho amargo.",
  [1152359321666560] = "Vou transformar cada moeda de ouro em uma bala de vingança e fazer com que os vilões que me incriminaram paguem o preço!",
  [1152359321666304] = "Que a Tempestade me abençoe, já possuo riqueza e sabedoria infinitas.",
  [1152359321666048] = "Adeus, gaiola!",
  [1152359321665792] = "Agora é hora de mandá-lo de volta. Lembre-se, quando você tiver problemas, vá em frente!",
  [1152359321665536] = "Eu te disse, é uma vitória garantida.",
  [1152359321665280] = "Apenas me diga, minha funcionalidade é incrível, amigo?",
  [1152359321665024] = "...Eu sei como sair da prisão agora, na verdade é tão simples!",
  [1152359321664512] = "Tanto conhecimento perfurado em meu cérebro!",
  [1152359321662976] = "Vamos, preencha os atributos que desejar. A oportunidade de desafiar os céus e mudar seu destino está bem na sua frente.",
  [1152359321662720] = "No final das contas, esse elfo é na verdade o \"<P_Yellow> Sistema </>\" para o protagonista trapacear. Contanto que você tenha o \" <P_Yellow> Sistema </> \", você não precisa de nenhuma técnica complexa de escrita para escrever um fluxo constante de pontos interessantes.",
  [1152359321662464] = "Você não esperava, não é? Este elfo é interpretado por mim, Roselle, pessoalmente!",
  [1152359321662208] = "Que bom para você, garoto, você é sensato!",
  [1152359321661952] = "No entanto, se você quiser que eu aja, o pré-requisito é ver se a sua sinceridade é suficiente.",
  [1152359321661696] = "Não importa qual atributo ou quantos pontos você deseja, eu, o Super Attribute Point Elf, posso satisfazê-los todos de uma vez, transformando você absolutamente no mais puro monstro numérico!",
  [1152359321661440] = "Que rude, eu sou o nobre <P_Yellow> Super Attribute Point Elf </>.",
  [1152359321661184] = "Essa coisa pode falar?!",
  [1152359321660928] = "Ei, amigo, tenha calma!",
  [1152359321660672] = "O que devo preencher para a vaga no roteiro aqui? Como o enredo deve se desenvolver?",
  [1152359321660416] = "Estou morrendo de ansiedade, apresse-se e deixe a apresentação continuar!",
  [1152359321660160] = "Caramba! O desempenho parou novamente. Eles estão nos provocando de propósito?",
  [1152359321659904] = "Isso, isso é...!",
  [1152359321659648] = "Espere, acho que ouvi um barulho estranho?",
  [1152359321659392] = "Talvez eu devesse reconhecer a realidade, parar de lutar e esperar calmamente aqui pela chegada da Morte.",
  [1152359321659136] = "Suspiro... Já gritei inúmeras vezes e ninguém nunca me respondeu.",
  [1152359321658880] = "Eu sou inocente... deixe-me sair...",
  [1152359321658624] = "Eu sou inocente! Deixe-me sair!",
  [1152359321658112] = "Dia após dia, ano após ano...",
  [1152359321657856] = "Na cela escura e apertada, ele perdeu todo contato com o mundo exterior.",
  [1152359321657600] = "【As luzes se apagam lentamente】 O pobre Dantès foi escoltado até o Château d'If – uma prisão de segurança máxima para presos políticos localizada em uma ilha isolada.",
  [1152359321657344] = "Não há necessidade. As evidências são completas e os fatos são indiscutíveis. Em nome do Rei e da lei, eu o condeno à prisão perpétua!",
  [1152359321657088] = "Senhor promotor, deve haver algum mal-entendido. Por favor, você deve investigar a verdade do assunto novamente.",
  [1152359321656832] = "Eu juro, nunca fiz essas coisas.",
  [1152359321656576] = "Recebi uma carta de denúncia <P_Yellow> detalhada e confiável </>, acusando você de se juntar secretamente a um culto a um deus maligno no continente sul, de participar de um ritual de sacrifício maligno e de organizar ataques terroristas contra civis!",
  [1152359321656320] = "Me prendendo? Posso perguntar por quê? Nunca cometi nenhum ato contra a lei.",
  [1152359321656064] = "Edmond Dantès, sou o promotor local, Villefort. Agora estou prendendo você formalmente em nome da lei!",
  [1152359321655808] = "Eu me oponho!",
  [1152359321655552] = "Leia a carta",
  [1152359321655296] = "Se ninguém tiver mais objeções, peça aos noivos que assinem este contrato de casamento para concluir o noivado formal.",
  [1152359321655040] = "Sr. Fernand, espere por mim...",
  [1152359321654784] = "Você vai se arrepender, espere e verá!",
  [1152359321654528] = "Você, seu plebeu, como ousa falar assim comigo! Que audácia!",
  [1152359321654272] = "Água turbulenta do rio... um menino que não quer ser comum... Essa é a voz do público?",
  [1152359321654016] = "Está tão ardente! Deveríamos deixar que esses nobres que sempre olham com desprezo saibam que nós, pessoas comuns, também queremos proteger nossa honra!",
  [1152359321653760] = "Bem dito, até a água do rio Hoy muda de curso. Faremos sucesso um dia também!",
  [1152359321653504] = "Trinta anos a leste do rio, trinta anos a oeste do rio, não despreze um jovem pobre!",
  [1152359321653248] = "Senhor, pelo bem da Mercedes, vou lhe dar um conselho!",
  [1152359321652992] = "Dez libras? Vinte libras? Haha, você é muito ganancioso... Vou te dar cinquenta libras, sair imediatamente e nunca mais aparecer na minha frente!",
  [1152359321652736] = "Preciso usar o modo de pensar do Imperador Roselle para resolver o problema... Vamos usar Visão Espiritual para encontrar pistas.",
  [1152359321652480] = "O Imperador Roselle sempre consegue conquistar o coração do público. Se fosse ele, como continuaria essa história?",
  [1152359321652224] = "O que!? O público não gosta das minhas falas? Como isso é possível!",
  [1152359321651968] = "Sr. Speer, acabei de saber que...",
  [1152359321651712] = "Tudo bem... Por favor, vá e me ajude a descobrir, ouça o que o público diz, por favor.",
  [1152359321651456] = "Os únicos qualificados para avaliar uma peça são o público. Você deve ouvir os pensamentos reais do público no local.",
  [1152359321651200] = "\"O Retorno do Conde\", do Imperador Roselle, foi originalmente publicado em série em jornais e escrito para cidadãos comuns. Sua adaptação também deve...",
  [1152359321650944] = "Quando a minha última peça estreou no Royal Theatre, até Sua Majestade o Rei e os ministros elogiaram as minhas falas. Como alguém poderia não gostar deles?",
  [1152359321650688] = "Impossível, eu claramente o criei estritamente de acordo com as leis do drama, elegante, nobre e racional... Como poderia haver um problema?",
  [1152359321650432] = "Talvez porque...",
  [1152359321650176] = "Como pode ser isso? Preenchi claramente as falas, a atuação deve continuar!",
  [1152359321649920] = "Por que a performance parou de novo?!",
  [1152359321649664] = "Que pessoa normal falaria assim? É muito exagerado!",
  [1152359321649408] = "Sobre o que você está tagarelando? Por que não entendi uma palavra disso?",
  [1152359321649152] = "Com uma retórica tão exagerada, será que o público vai gostar mesmo?",
  [1152359321648896] = "(Espere... as linhas que o Sr. Speer escreveu...)",
  [1152359321648640] = "Oh! Senhor, imploro-lhe que deixe de lado esse sarcasmo tão cortante quanto o vento norte. Os verdadeiros sentimentos que brilham em nossos olhos não podem ser igualados nem mesmo pelas pérolas mais brilhantes deixadas pela Dinastia Trunsoest!",
  [1152359321648384] = "Vou te dar cinquenta libras de ouro, sair imediatamente e nunca mais aparecer na minha frente!",
  [1152359321648128] = "Deixe-me pensar... Certo, metáforas requintadas, retórica elegante, espírito nobre... Seguindo as grandes leis do drama, posso facilmente escrever versos perfeitos.",
  [1152359321647872] = "Esta é uma peça adaptada de \"O Retorno do Conde\", mas o manuscrito do Imperador Roselle está incompleto, levando à falta de uma <P_Yellow> linha-chave </> aqui. Enquanto puder ser preenchido, o desempenho certamente continuará.",
  [1152359321647616] = "Sr. Speer, por que a apresentação parou?",
  [1152359321647360] = "Dez libras? Vinte libras? Garoto, você é muito ganancioso... Vou te dar cinquenta libras de ouro, sair imediatamente e nunca mais aparecer na minha frente!",
  [1152359321646848] = "Quanto a você, nossa Família Montego lhe dará uma indenização. Diga-me, quanto dinheiro você quer deixar para minha prima linda?",
  [1152359321646592] = "É simplesmente um sapo querendo comer carne de cisne. Para falar a verdade, antes de vir já tinha persuadido os mais velhos da família e decidi cancelar formalmente o noivado.",
  [1152359321646336] = "Hahahaha—honra? A honra de um pobre é simplesmente a maior piada desde a Quinta Época!",
  [1152359321646080] = "Senhor, por favor retire essa declaração. Embora eu não seja um aristocrata, minha honra é igualmente inviolável.",
  [1152359321645824] = "Minha querida, esta é a nossa cerimônia de noivado, como você pode começar uma briga...",
  [1152359321645568] = "Guarde isso, eu não acredito nisso de jeito nenhum. Aquilo pelo qual você, pobre menino, se apaixonou devem ser as moedas de ouro da nossa família!",
  [1152359321645312] = "Primo, como você pode dizer isso? Ele é um marinheiro – alerta, forte e de bom coração. Você não deveria usar padrões aristocráticos para julgá-lo.",
  [1152359321645056] = "Mercedes, é desse Dantes que você sempre fala? Ele parece pobre, vulgar e... ele fede!",
  [1152359321644800] = "Ei, vocês ainda nem estão noivos e já estão dizendo coisas tão piegas que é nojento!",
  [1152359321644288] = "Hmph, isso não é necessariamente verdade. As pessoas muitas vezes passam por infortúnios quando as coisas vão muito bem. Se você não acredita em mim, assista—",
  [1152359321644032] = "Sim, garanto que com certeza viverão felizes para sempre e se tornarão uma história contada entre os vizinhos.",
  [1152359321643776] = "Olhe para eles, que fofos, que combinam! Como personagens que saíram de uma pintura de Oletti.",
  [1152359321643520] = "É precisamente a saudade de você que me permitiu superar as ondas furiosas do Mar Furioso e voltar para me reunir com você.",
  [1152359321643264] = "Minha querida Mercedes, eu também.",
  [1152359321643008] = "Minha querida, estou ansioso por este momento.",
  [1152359321642752] = "Mas neste momento, seu humor está muito mais turbulento do que as ondas do mar...",
  [1152359321642496] = "A história começa com uma animada cerimônia de noivado. O noivo, Dantès, acaba de voltar do Continente Sul. Ele é o primeiro imediato do navio mercante 'Pharaon', um marinheiro que passou por grandes tempestades.",
  [1152359321642240] = "Eu não sou louco! É tudo sangue! O sangue fluiu por todo o chão da névoa negra!",
  [1152359321641984] = "Todos dizem que sou louco!",
  [1152359321641728] = "Eu vi um trabalhador, ele foi engolido da cabeça aos pés! Pela névoa negra!",
  [1152359321641472] = "Você pode... você pode me levar para casa?",
  [1152359321641216] = "Tudo bem, vou subir ao palco agora.",
  [1152359321640960] = "<P_Heart> (Se eu puder ajudá-lo a terminar esta peça, talvez eu possa quebrar este espaço e restaurá-lo ao normal.) </>",
  [1152359321640704] = "<P_Heart> (Parece que o corpo espiritual do Sr. Speer está preso neste espaço, e é por isso que ele está agindo como um louco no mundo real.) </>",
  [1152359321640448] = "Por favor, você deve concordar em subir ao palco como ator principal, eu imploro! A apresentação está prestes a começar e não tenho outra escolha.",
  [1152359321640192] = "Mas ouso dizer que você tem talento para ser ator. Você não apenas atende a todos os meus requisitos, mas o sentido da história em seus olhos certamente comoverá o público. Este deve ser um arranjo da Deusa.",
  [1152359321639936] = "A apresentação está prestes a começar, por favor, apresse-se, vista a fantasia da apresentação e suba ao palco.",
  [1152359321639680] = "Ótimo, de repente percebi que você atende perfeitamente aos meus requisitos, e o sentido da história em seus olhos certamente comoverá o público. Este é simplesmente um presente da Deusa.",
  [1152359321639424] = "Hum? ...Mas, jovem, você está interessado em ser o <P_Yellow> ator principal </> ?",
  [1152359321639168] = "Não é tão simples. Para desempenhar o carisma do protagonista Dantes, essa pessoa não deve apenas ser bonita e ágil, mas, o mais importante, deve ser capaz de exibir as qualidades heróicas de perseverança e integridade.",
  [1152359321638912] = "Não, como dramaturgo com integridade profissional, nunca sairei da estreia da minha própria obra!",
  [1152359321638656] = "A apresentação está prestes a começar em alguns minutos. O que devo fazer sem um ator principal? O público furioso definitivamente não vai me deixar escapar.",
  [1152359321638400] = "É realmente absurdo; esta peça nem tem ator principal, e não consigo nem encontrar o diretor do teatro ou o diretor de palco!",
  [1152359321637888] = "O que devo fazer!? A apresentação está prestes a começar e esse tipo de coisa realmente aconteceu...",
  [1152359321637632] = "Tanto texto e conhecimento inundando meu cérebro...",
  [1152359321637376] = "“Agora, modificar uma versão de 'O Conde de Monte Cristo' para ser ainda mais emocionante e emocionante é moleza, o povo de Intis com certeza ficará viciado.”",
  [1152359321637120] = "... Há uma linha de anotações chinesas aqui, escrita por Roselle: \"Eu li tantos <P_Yellow> web novels </> , descobri os tropos há muito tempo ...\"",
  [1152359321636864] = "Mas isso é normal; afinal, é um artefato histórico de duzentos anos atrás.",
  [1152359321636608] = "Este manuscrito parece <P_Yellow> incompleto </>; a caligrafia em muitos lugares não é mais legível e alguns números de páginas estão faltando...",
  [1152359321636352] = "<P_Heart> (Mas essas cores estão mudando violentamente, indicando que sua mente está em um estado ativo e doentio. Preciso encontrar uma maneira de acalmá-lo.) </>",
  [1152359321636096] = "<P_Heart> (A cabeça e a superfície do cérebro parecem roxas claras, e o todo está envolto em cinza...) </>",
  [1152359321635840] = "(O que devo perguntar a seguir?)",
  [1152359321635584] = "Entendido, oficial.",
  [1152359321635328] = "Eu entendo. A seguir, conduzirei uma consulta psicológica muito particular para o Sr. Speer. Por favor, afaste-se por um momento e certifique-se de que ninguém entre nesta sala.",
  [1152359321635072] = "Sim, ele faz uma pequena pausa após cerca de duas a três horas de episódios e depois começa novamente... que é a duração de uma <P_Yellow> apresentação teatral </> .",
  [1152359321634816] = "Um padrão?",
  [1152359321634560] = "Hmm... se eu tivesse que dizer, sinto que os episódios histéricos da professora têm um padrão.",
  [1152359321634304] = "Então ele decidiu estudar o manuscrito cuidadosamente para aprender com sua experiência criativa... Eu não esperava que ele acabasse assim.",
  [1152359321634048] = "Ele sempre admirou o Imperador Roselle, especialmente recentemente, pois lhe falta inspiração e não consegue escrever uma obra satisfatória...",
  [1152359321633792] = "Três dias atrás, o professor obteve acidentalmente o manuscrito original do Imperador Roselle de <P_Yellow> \"O Retorno do Conde\" </>.",
  [1152359321633536] = "Na verdade, como dramaturgo, é normal experimentar flutuações emocionais durante a criação, mas nunca ouvi falar de uma histeria tão severa como a do professor.",
  [1152359321633280] = "Sim, de manhã à noite ele não come nem bebe, apenas murmura para si mesmo como um louco.",
  [1152359321633024] = "Como você pode ver, o estado mental do professor... não é muito normal.",
  [1152359321632768] = "Como... como posso fazer a história continuar...",
  [1152359321632512] = "Espere, não... não posso escrever assim, é muito brando, falta tensão dramática!",
  [1152359321632256] = "Hahaha, isso mesmo, exatamente! Uma reversão chocante está prestes a acontecer!",
  [1152359321632000] = "Eu vejo. Oficial, por favor, siga-me.",
  [1152359321631744] = "O Sr. Speer é uma celebridade no mundo literário e o Departamento de Polícia leva esse assunto muito a sério, por isso fui enviado especialmente para investigar.",
  [1152359321631488] = "Sou especialista em psicologia do Departamento de Polícia do Condado, inspetor estagiário.",
  [1152359321631232] = "A professora teve alguns problemas mentais recentemente. Entramos em contato com uma clínica psicológica, então por que a polícia veio?",
  [1152359321630976] = "Esta é a oficina do Sr. Speer? Recebi ordens para investigar a situação.",
  [1152359321630720] = "Tudo bem, que o Imperador o abençoe. Espero que ambos possamos sair do trabalho mais cedo.",
  [1152359321630464] = "Ainda quero passear por aqui. Nos veremos mais tarde. Tome cuidado!",
  [1152359321630208] = "<P_Heart> (Usar Beyonder poderes na frente de pessoas comuns causará problemas desnecessários... É melhor eu agir sozinho.) </>",
  [1152359321629952] = "O Imperador Roselle disse uma vez que o encontro é o destino! Pretendo investigar lá. Se precisar, podemos ir juntos.",
  [1152359321629696] = "Será que foi você quem desapareceu em Chess Manor...",
  [1152359321629440] = "O banheiro que você mencionou não seria o do Chess Manor...",
  [1152359321629184] = "Meu? Acho que fui jogado no vaso sanitário...",
  [1152359321628928] = "E você? Talvez você possa sair de onde entrou?",
  [1152359321628672] = "Não me pergunte. Eu estava disfarçado de reparador conduzindo uma investigação quando de repente desmaiei e apareci aqui. Eu não sei de nada.",
  [1152359321628160] = "<P_Heart> (Salvando famílias desfeitas... Será que o ressentimento no banheiro também pode estar relacionado à Campanha Patriótica de Saúde?) </>",
  [1152359321627904] = "A gestão do esgoto foi uma das medidas. Este feito foi posteriormente promovido em todo o mundo, salvando inúmeras famílias da desintegração!",
  [1152359321627648] = "Muito bem. Depois de se tornar Cônsul, o Imperador Roselle começou a promover uma campanha para enfatizar a higiene, prevenir, reduzir e até erradicar doenças e melhorar os padrões de saúde.",
  [1152359321627392] = "O, o Grande Imperador Roselle.",
  [1152359321627136] = "Como ousa chamá-lo pelo nome? Por favor, refira-se a ele respeitosamente como o Grande Imperador Roselle.",
  [1152359321626880] = "Então foi mesmo a Campanha Patriótica da Saúde promovida pela Roselle! Quais foram as especificidades da campanha?",
  [1152359321626624] = "Quando há financiamento suficiente, não há tanto lixo aqui. Todos os esforços que o Imperador Roselle fez na Campanha Patriótica de Saúde foram em vão!",
  [1152359321626368] = "Como acabei como funcionário público, procurando nos esgotos? Isso não está de acordo com a estética do Imperador Roselle!",
  [1152359321626112] = "Polícia... O Imperador Roselle disse que todos são responsáveis ​​pela ascensão e queda do país. Se não fosse a reprovação no teste de aptidão física, seríamos colegas.",
  [1152359321625856] = "Desculpe, na verdade sou um policial. Eu acidentalmente vim aqui enquanto investigava um caso. Você sabe alguma coisa sobre a situação próxima?",
  [1152359321625600] = "O que? Eu sou Leo, um inspetor enviado pela prefeitura, atualmente disfarçado de vagabundo para fazer uma busca!",
  [1152359321625344] = "Você é inspetor de saúde? Então quem sou eu?",
  [1152359321625088] = "Senhor, sou um inspetor de saúde enviado pela prefeitura. Posso perguntar onde fica a saída do esgoto?",
  [1152359321624832] = "<P_Heart> (Não posso revelar minha identidade a estranhos. Devo usar um disfarce.) </>",
  [1152359321624576] = "Obrigado, corajoso {Sr.{Sra.|}}.",
  [1152359321624320] = "Ajuda! Os ratos estão comendo pessoas!",
  [1152359321624064] = "O jargão está vindo do banheiro, o reparador desapareceu misteriosamente... A fonte do jargão deve estar dentro do espaço do conhecimento. Encontre o item de origem e você poderá quebrar o espaço!",
  [1152359321623808] = "Entrou no espaço com sucesso! Isso é... um esgoto? Eu me lembro, fui 'jogado' pelo ralo do vaso sanitário?",
  [1152359321623552] = "Um lugar tão profundo e escuro que chama meu olhar... ir ao banheiro... preciso usar... o banheiro...",
  [1152359321623296] = "Eu deveria dar uma olhada em outros lugares... Não, eu não quero... Eu deveria dar uma olhada em outros lugares... Não, preciso dar mais umas olhadas...",
  [1152359321623040] = "Muito bem, deixe-me cuidar deste mero banheiro dourado.",
  [1130369089882368] = "Claro.",
  [1152359321622784] = "Pelo banheiro entra-se no Espaço do Conhecimento...",
  [1152359321622528] = "Por favor, se apresse.",
  [1152359321622272] = "Ei, eu ainda queria ver se conseguia tirar um rato gigante do banheiro!",
  [1152359321622016] = "Pessoal, preciso usar alguns métodos de investigação confidenciais agora. Por favor, não me perturbe.",
  [1152359321621760] = "<P_Heart> (Por favor, pessoas comuns, saiam para que eu possa conduzir uma investigação mais completa.) </>",
  [1152359321621504] = "<P_Heart> (Incidente de desaparecimento... ressentimento misterioso, parece que este é realmente um incidente Beyonder.) </>",
  [1152359321621248] = "Devo adiantar que este assunto não tem nada a ver com o feudo.",
  [1152359321620992] = "Ele saiu logo após entrar no banheiro. Procuramos por toda a mansão, mas não encontramos nenhum vestígio dele.",
  [1152359321620736] = "Esquerda?",
  [1152359321620480] = "...Ele foi embora.",
  [1152359321620224] = "Ouvi do manobrista que um reparador veio esta manhã. Ele diagnosticou o motivo do mau funcionamento?",
  [1130369089365248] = "OK.",
  [1152359321619968] = "Afinal, o lançamento da Campanha Patriótica de Saúde pelo Imperador Roselle ocorreu há centenas de anos. No actual Loen, o sistema de esgotos é suficientemente completo, então porquê continuar a desperdiçar recursos financeiros?",
  [1152359321619712] = "Você também acha?",
  [1152359321619456] = "Essa foi uma quantia significativa. Na sua opinião, foi um sério obstáculo à economia de Tingen.",
  [1152359321619200] = "Certa vez, Hubert propôs um plano em uma reunião para cortar o financiamento para a gestão de esgotos de Tingen.",
  [1152495149647872] = "As luzes se apagam e a apresentação é interrompida novamente.",
  [1152495149658112] = "O pingente de cristal amarelo gira no sentido anti-horário, movendo-se rapidamente. \n... A resposta é uma negação muito forte...",
  [1152359321618432] = "Houve algum evento relacionado ao banheiro recentemente?",
  [1152359321618176] = "Este é um banheiro dourado caro. Além do mestre, quem mais poderia usá-lo?",
  [1152359321617920] = "Quem foi a última pessoa a usar o banheiro?",
  [1152359321617664] = "Anteontem à noite, depois de uma visita muito comum ao banheiro.",
  [1152359321617408] = "Quando o banheiro funcionou mal?",
  [1152359321617152] = "Senhor, ainda tenho perguntas a fazer.",
  [1152359321616896] = "Meu mestre é um cavalheiro elegante e nunca jogaria lixo no vaso sanitário. Sua especulação é ofensiva!",
  [1152359321616640] = "Sr. Fred, alguém jogou lixo no vaso sanitário?",
  [1152359321616384] = "Ouvi dizer que recentemente as pessoas costumam usar banheiros para esconder coisas. Poderia estar entupido porque alguém jogou algo dentro?",
  [1152359321616128] = "O vaso sanitário não dá descarga; deve estar entupido.",
  [1152359321615872] = "Você encontrou as pistas que precisava?",
  [1152359321615616] = "Um caso... por favor, siga-me.",
  [1152359321615360] = "A polícia suspeita que o banheiro esteja relacionado a um caso. Por favor, deixe-me entrar no banheiro para investigar.",
  [1152359321615104] = "Em nossa opinião, este é apenas um mau funcionamento comum do banheiro. Por que incomodaria um oficial vir?",
  [1152359321614848] = "Sim, eu sou o mordomo aqui, Fred. A mansão foi afetada pelo cheiro que emana do banheiro, e o Sr. Hubert teve que se mudar temporariamente para outra residência.",
  [1152359321614592] = "Senhor, a delegacia recebeu uma denúncia de que houve um defeito anormal no banheiro da casa do vereador Hubert Chase?",
  [1152359321614336] = "Antes de tomar o remédio, tenho que lavar as mãos!",
  [1152359321614080] = "Beba esta garrafa de Orvalho da Doce Noite; isso o ajudará a estabilizar sua mente.",
  [1152359321613824] = "Parece que você descobriu algo errado.",
  [1152359321613568] = "Derrotei o Senhor do Lixo nos esgotos, testemunhei a Campanha Patriótica de Saúde e obtive o precioso vaso sanitário dourado!",
  [1152359321613312] = "Viajei do banheiro até os esgotos, eliminei os ratos, resolvi os quebra-cabeças, finalmente derrotei o Senhor do Lixo, encontrei o banheiro dourado, conheci o Imperador Roselle, encontrei as evidências de corrupção e voltei pelo banheiro.",
  [1152359321613056] = "Os esgotos?",
  [1152359321612800] = "A corrupção foi esclarecida. Além disso, encontrei provas da corrupção do vereador Hubert nos esgotos e já as entreguei ao pessoal competente.",
  [1152359321612544] = "Disseram que você desapareceu no banheiro, qual é a situação agora?",
  [1152359321612288] = "Desculpe, proteger o público é dever da polícia.",
  [1152359321612032] = "...Eu sou o mordomo aqui.",
  [1152359321611776] = "Sr. Fred, por favor, saia primeiro.",
  [1152359321611264] = "...Isso mesmo, vivi tudo isso sozinho.",
  [1152359321611008] = "Heroico como você é, você mesmo descobriu evidências da corrupção de Hubert nos esgotos. Tudo correu tão bem quanto um sonho, não foi?",
  [1152359321610752] = "Os moradores inocentes que morreram por causa dele também podem descansar em paz.",
  [1152359321610496] = "Isso mesmo, policial, agora podemos sair do trabalho limpos e arrumados!",
  [1152359321610240] = "A higiene é a base da saúde; isso é o que o Imperador nos ensinou.",
  [1152359321609984] = "Foi ele quem implantou o conceito de higiene na mente dos moradores, permitindo que até mesmo os moradores das favelas vivessem de forma relativamente limpa.",
  [1152359321609728] = "Se não fosse pela Campanha Patriótica de Higiene, minha avó provavelmente teria morrido de peste, e muito menos dado à luz meus pais.",
  [1152359321609472] = "...Sim, jurei proteger o sistema de esgoto inventado pelo Imperador Roselle.",
  [1152359321609216] = "Você realmente adora o grande imperador Roselle.",
  [1152359321608960] = "Com isso, posso seguir os passos do Imperador, abrir um caso para investigação e prender todos eles!",
  [1152359321608704] = "O Imperador Roselle disse que quando você encontra um rato, significa que a casa já foi ocupada por ratos.",
  [1152359321608448] = "Sr. Leo, encontrei evidências da corrupção de Hubert!",
  [1152359321607936] = "Quão desprezível! Oficial, acho que posso fazer isso de novo. Ainda existem alguns lugares próximos que não foram revistados. Você está disposto a me ajudar?",
  [1152359321607680] = "Na verdade... Os esgotos perderam o financiamento para o controlo de roedores e os ratos estão à solta. As águas residuais das fábricas não podem ser drenadas porque as tubulações não recebem manutenção, fermentando constantemente e produzindo um odor desagradável... Afetou até mesmo os banheiros das casas dos moradores.",
  [1152359321607424] = "<P_Heart> (Esse recibo esfarrapado é uma prova importante... o ressentimento no banheiro vem dos moradores de rua mortos...) </>",
  [1152359321607168] = "Segundo relatos, ele desviou os fundos de manutenção do esgoto, causando a morte de muitos moradores de rua que viviam nos esgotos!",
  [1152359321606912] = "Sim! Visto que você também veio do banheiro... pensei que a polícia soubesse disso.",
  [1152359321606656] = "Hubert é corrupto?!",
  [1152359321606400] = "Claro, é porque o vereador Hubert é suspeito de corrupção, e as provas muito provavelmente estão escondidas nos esgotos!",
  [1152359321606144] = "Acalmar! Pense na sua missão! Por que você veio aqui!",
  [1152359321605888] = "Eu só queria ser um herói como o Imperador. Se eu não quisesse ser esse herói, não teria aceitado esse trabalho. Se eu não aceitasse esse trabalho...",
  [1152359321605632] = "O Imperador Roselle disse que não se deve abandonar o que está próximo para perseguir o que está longe. Por que me esforcei para assumir esse trabalho difícil? Eu vou ficar preso aqui...",
  [1152359321605120] = "Oficial, você encontrou a saída?",
  [1152359321604864] = "Drenar o esgoto pode resolver o problema...",
  [1152359321604608] = "O esgoto da fábrica é a fonte da praga?",
  [1152359321604352] = "Isto é – uma imagem do Imperador Roselle!",
  [1152359321604096] = "O que devo fazer a seguir, continue... Hah!",
  [1152359321603840] = "Aterrorizante! Eles veem um rato como se tivessem visto um inimigo jurado!",
  [1152359321603584] = "Ele escapou do alcance do poder Beyonder?",
  [1152359321603328] = "Eh? Como ele voltou a ser humano?",
  [1152359321603072] = "Fui para a porta errada... O que aconteceu com ele?",
  [1152359321602560] = "É esta porta?",
  [1152359321602304] = "Lembre-se de trazer seu distintivo policial.",
  [1152359321602048] = "Independentemente disso, precisamos fazer uma viagem à Mason Factory.",
  [1152359321601792] = "Isto é um presságio espiritual? Leonard disse antes que você é especial.",
  [1152359321601536] = "O que é ainda mais estranho é que você sonhou com a garota do caso de antemão.",
  [1152359321601280] = "Sim, as imagens do sonho eram um pouco estranhas.",
  [1152359321601024] = "O céu se transformou em uma torrente... A jovem desapareceu de repente...",
  [1152359321600768] = "Não, não tenho ideia de quem ela é.",
  [1152359321600512] = "Vocês se conhecem?",
  [1152359321600256] = "Essa garota... eu a vi em meu sonho ontem...",
  [1152359321600000] = "Já que você se juntou ao Vigias Noturnos , vamos dar uma olhada nos casos recentes juntos.",
  [1152359321599744] = "(Não admira que o Sr. Star tenha dito que Frye é um capitão confiável.)",
  [1152359321599488] = "Se o detectarmos precocemente, talvez possamos evitar sacrifícios desnecessários.",
  [1152359321599232] = "Ainda não é certo. Mas com base na experiência passada, se um grande número de eventos anômalos ocorrer em uma área, há uma grande probabilidade de que altos Sequência poderes ocultos estejam presentes.",
  [1152359321598976] = "Acabei de ouvir que um Sequência 0 Artefato Selado escapou... Tingen estará em perigo?",
  [1152359321598720] = "Obrigado, Rozanne.",
  [1152359321598464] = "Capitão, aqui está o café que você pediu. Além disso, os últimos arquivos do Departamento de Polícia de Tingen foram entregues.",
  [1152359321598208] = "Lembre-se, se você descobrir quaisquer objetos em forma de coroa ou eventos anormais, não os alerte, não os perturbe e informe imediatamente.",
  [1152359321597952] = "Você parece já conhecer o perigo de um Artefato Selado de Grau 0.",
  [1152359321597696] = "É isso mesmo, ele voltou correndo para as Luvas Vermelhas por causa disso.",
  [1152359321597440] = "Artefato Selado Grau 0?! Então o Sr. Leonard saiu ontem à noite...",
  [1152359321597184] = "Sem ser selado, o seu poder é suficiente para destruir um país, ou mesmo o mundo inteiro.",
  [1152359321596928] = "Grau 0 significa que é extremamente perigoso, não deve ser questionado, não deve ser divulgado, não deve ser descrito, não deve ser espiado...",
  [1152359321596672] = "Artefato Selado Grau 0?",
  [1152359321596416] = "Um artefato selado de grau 0 da Igreja do Deus do Vapor e da Máquina em Intis escapou. Atualmente não se sabe se escapou para Loen.",
  [1152359321596160] = "O que aconteceu?",
  [1152359321595904] = "Sim, estou investigando os casos recentes em Tingen.",
  [1152359321595648] = "Capitão, você estava apenas realizando Mediunidade Espiritual?",
  [1152359321595392] = "N-nada... Primeiro vou fazer uma xícara de café para o Capitão. Se você estiver procurando por ele, pode ir direto para o quarto de dormir.",
  [1152359321595136] = "Sra. Rozanne, por que você ficou em silêncio de repente?",
  [1152359321594880] = "Minha Deusa, estou começando a suspeitar que ele mudou para o Sleepless Caminho... ficar acordado até tarde não é um bom hábito; sua linha do cabelo diminuirá, sua pele ficará flácida e você se tornará...",
  [1152359321594624] = "Ele passou a noite inteira ontem no quarto de dormir do Portão Chanis. Ele parece estar investigando alguma coisa e até mudou uma mesa para lá.",
  [1152359321594368] = "Sim, ele está aqui?",
  [1152359321594112] = "Quem sabe, talvez seja algum aniversário da Revolução Steam... A propósito, você está aqui para ver o Capitão Frye?",
  [1152359321593856] = "Sim, ele mudou toda a era. Mas por que o 'Jornal do Homem Honesto de Tingen' de repente começaria a reportar os feitos do Imperador Roselle?",
  [1152359321593600] = "Embora eu seja um Loenese, toda vez que leio sobre a vida do Imperador, não posso deixar de suspirar – o Imperador Roselle é realmente um gênio sem precedentes!",
  [1152359321593344] = "(Não admira que o Sr. Louco tenha dito que o Imperador Roselle não deixou nenhuma chance para os retardatários se exibirem.)",
  [1152359321593088] = "(Aquele predecessor transmigrador na Névoa da História, ele realmente fez tantas coisas.)",
  [1152359321592832] = "\"Pioneiro da História - Imperador Roselle e a Onda da Revolução do Vapor\" .",
  [1152359321592576] = "Bom dia, Sra. Rozanne! O que você está lendo?",
  [1152359321592320] = "São vários relatórios consecutivos sobre o Imperador Roselle. Estou começando a suspeitar que o 'Jornal do Homem Honesto de Tingen' foi adquirido secretamente pela Intis...",
  [1152359321592064] = "Sim, vamos falar primeiro com o Capitão Frye.",
  [1152359321591808] = "Juntar-se ao esquadrão Vigias Noturnos e participar no tratamento de casos Extraordinários em Tingen... talvez seja uma boa escolha.",
  [1152359321591552] = "O apocalipse está chegando, também preciso digerir a poção o mais rápido possível e equilibrar a corrupção em meu corpo.",
  [1152359321591296] = "Uma missão que exige que o Sr. 'Star' cuide pessoalmente... deve ser muito perigosa.",
  [1121575948518913] = "...Miau.",
  [1152359321591040] = "Posso sentir dor... o sonho acabou, devo dar uma olhada primeiro.",
  [1152359321590784] = "Outra nota?",
  [1152359321590528] = "Tudo agora... foi um sonho...",
  [1152359321590016] = "Não tenho escolha a não ser sair e dar uma olhada.",
  [1152359321589760] = "Nenhuma resposta...",
  [1152359321589504] = "Como a pessoa desapareceu de repente... Sra. Rozanne! Sra.",
  [1152359321589248] = "Sra. Rozanne, quem deixou esse bilhete para mim?",
  [1152359321588992] = "Ir para a entrada da Blackthorn Security Company? Que mensagem estranha, e nem está assinada...",
  [1152359321588736] = "...Uma pessoa muito especial.",
  [1152288991241216] = "O que você está procurando?",
  [1152359321588480] = "Você está muito preocupado com {{PlayerName}}. Quem exatamente é {{ele|ela}}?",
  [1152359321588224] = "Eu deveria ir. Ajude-me a passar esta nota para {{PlayerName}}. Entrar na névoa cinzenta da história consumiu muito espiritualidade . Deixe {{ele | ela}} ter um bom descanso em Blackthorn esta noite.",
  [1152359321587712] = "Só quero ficar em Tingen e proteger este lugar.",
  [1152359321587456] = "Se você quiser buscar mais da verdade, as Luvas Vermelhas são sempre acolhedoras.",
  [1152359321587200] = "No Mundo Extraordinário, não existe um verdadeiro “acidente”, mas sim uma série de “coincidências” cuidadosamente planeadas.",
  [1152359321586944] = "O que você acha?",
  [1152359321586688] = "Isso também não foi um acidente, certo?",
  [1152359321586432] = "Eu sei, há cinco anos, “0-08” também tinha apenas uma descrição simples.",
  [1152359321586176] = "Sendo o nível de segurança mais alto, a busca por um Artefato Selado de Grau 0 sempre transmitiu apenas informações vagas. Você deve ser muito claro sobre isso.",
  [1152359321585920] = "De acordo com a descrição verbal de um membro do Red Glove, ele aparece em forma de coroa, mas seu poder foi restringido por algum motivo. Isso é tudo.",
  [1152359321585664] = "Artefato Selado Grau 0... no que preciso prestar atenção?",
  [1152359321585408] = "Um artefato selado de grau 0 da Igreja do Deus do Vapor e da Máquina em Intis escapou e seu paradeiro é desconhecido. As 'Luvas Vermelhas' conduzirão investigações em Loen.",
  [1152359321585152] = "Existe um caso de emergência?",
  [1152359321584384] = "Ele só bate em uma porta por vez, e toda vez ele bate em uma <P_Yellow> porta </> diferente. Da última vez foi a porta ao lado da <P_Yellow> lareira </>...",
  [1152359321584128] = "O outro, você pode ver se recuar alguns passos.",
  [1152359321583872] = "Existem duas portas nesta mansão, uma está na sua frente.",
  [1152359321583616] = "Isto? Batendo na porta?",
  [1152359321583104] = "Ouça, este quarto não está limpo. \"Isso\" está lá fora.",
  [1152359321582848] = "Você também foi enganado para vir aqui por causa daquele pedaço de papel? Droga, eu deveria ter queimado no momento em que vi!",
  [1152359321582592] = "Ah, uma nova vítima? ...",
  [1152359321582080] = "Sucesso.",
  [1152359321581056] = "Nem pense em entrar...",
  [1152359321580800] = "Não... não...",
  [1152359321580544] = "Está tranquilo por enquanto... isso foi por pouco...",
  [1152359321580288] = "Eu tenho que bloquear a porta!",
  [1152359321580032] = "Ah não, algo está tentando entrar do lado de fora da porta...",
  [1152359321578752] = "Mas não quero agir como um babuíno de cabelos cacheados!",
  [1152359321578496] = "Embora às vezes eu sinta um pouco de inveja.",
  [1152359321578240] = "É melhor deixar esta honra aos nossos colegas que estão na luz.",
  [1152359321577984] = "Esta é a recompensa que nossa figura-chave do dia merece.",
  [1152359321577728] = "Ninguém quer ver notícias de vítimas nos jornais.",
  [1152359321577472] = "Graças a você, os reféns conseguiram evacuar com segurança.",
  [1152359321577216] = "Este é um caso de imitação maliciosa que causou um impacto negativo. Levamos o pessoal envolvido à justiça e notificamos o gerente do restaurante, Douglas, para retornar a Tingen para investigação. Por favor, peça aos cidadãos que reduzam o pânico...",
  [1152359321576960] = "Posso perguntar: qual a sua opinião sobre o incidente em que J. Durand, o gerente assistente do Restaurante Bonaparte, imitou o Açougueiro Sangrento?",
  [1152359321576704] = "Os repórteres têm um olfato muito apurado, não é?",
  [1152359321576448] = "Limpar.",
  [1152359321576192] = "Insetos! Sair! Do meu! Casa!",
  [1152359321575680] = "Já estou me esforçando ao máximo!",
  [1152359321575424] = "Baterista! Não consigo ouvir suas batidas! Aumente o volume!",
  [1152359321575168] = "Ação de palmas do jogador restaurada",
  [1152359321574912] = "Choramingar!",
  [1152359321574656] = "Uau! Uau, au, au! Uau!",
  [1152359321574400] = "Cachorro se finge de morto restaurado",
  [1152359321573888] = "Ação de sentar restaurada",
  [1152359321573632] = "Uau—",
  [1152359321573120] = "<P_Heart> (Com o que devo brincar?) </>",
  [1152359321572864] = "<P_Heart> (Temo que não conseguirei dormir bem por muito tempo...) </>",
  [1152359321572608] = "Volte e descanse primeiro; você precisa de um bom sono.",
  [1152359321572352] = "A Beyonder da Bruxa Caminho ... Vou mandar alguém investigar. Você se saiu bem.",
  [1152359321572096] = "Depois que a corrupção foi esclarecida, ela desapareceu. Suspeito que ela esteja usando as pessoas afetadas pela corrupção.",
  [1152359321571840] = "Dona Vera?",
  [1152359321571584] = "A propósito, capitão. A dona do Salão Noturno de Primavera, Dona Vera, ela pode ser uma Beyonder.",
  [1152359321571328] = "É assim mesmo? Sua expressão diz o contrário.",
  [1152359321571072] = "Nada, a batalha foi um pouco intensa.",
  [1152359321570816] = "...É melhor você não saber.",
  [1152359321570560] = "Que conhecimento?",
  [1152359321570304] = "Aprendi muito... sobre o \"conhecimento\" do Imperador Roselle.",
  [1152359321570048] = "Você parece um pouco... abatido. O que aconteceu lá?",
  [1152359321569792] = "Sim, foi tratado.",
  [1152359321569536] = "Você está de volta. A corrupção foi esclarecida?",
  [1152359321569280] = "Não... não posso afundar mais...",
  [1152359321569024] = "Gosto de pessoas que são honestas sobre seus desejos.",
  [1152359321568768] = "Ainda quero experimentar mais uma vez... esse sentimento.",
  [1152359321568512] = "Que fofo, ainda hesitando? Esqueça, o jogo deve terminar aqui.",
  [1152359321568256] = "<P_Heart> (Por que, por que não consigo fazer isso?) </>",
  [1152359321568000] = "Chega, sua bruxa!",
  [1152359321567744] = "Eu te dei o maior prazer, mas você quer me matar?",
  [1152359321567488] = "Que pena... Você foi muito mais interessante ontem à noite do que quando está sóbrio.",
  [1152359321567232] = "Pare de me chamar de Vossa Majestade! Droga, quase esqueci... minha missão é encontrar e eliminar você, essa 'Bruxa'!",
  [1152359321566976] = "O que há de errado, Majestade? O amor não conhece gênero. Você não se divertiu ontem à noite?",
  [1152359321566720] = "Então, ontem à noite eu estava com... <P_Heart> (Roselle!!! Seu gosto é demais...!) </>",
  [1152359321566464] = "Uma bruxa que costumava ser um homem.",
  [1152359321566208] = "O que diabos você é?!",
  [1152359321565952] = "Ah, então você viu. O verdadeiro eu.",
  [1152359321565696] = "Você, seu rosto...",
  [1152359321565440] = "O que há de errado, minha Majestade?",
  [1152359321565184] = "Você está ainda mais bonita agora. Deixe-me olhar para você na luz da manhã...",
  [1152359321564928] = "Só ontem à noite?",
  [1152359321564672] = "Ontem à noite você estava realmente linda.",
  [1152359321564416] = "Esta noite, vamos realizar o sonho... certo?",
  [1152359321564160] = "Nos últimos três dias, sonhei com você todas as noites. Sonhei com sua voz, suas mãos... e muito mais.",
  [1152359321563904] = "Prossiga.",
  [1152359321563648] = "Um último segredo...",
  [1152359321563392] = "Excitado. Só de imaginar a expressão no seu rosto quando você leu a carta... me faz sentir quente e incomodado.",
  [1152359321563136] = "Nervoso?",
  [1152359321562880] = "Tem mais uma coisa... Na verdade, quando eu estava escrevendo aquela carta, minhas mãos tremiam o tempo todo.",
  [1152359321562624] = "Você pode sentir isso? Está batendo por você.",
  [1152359321562368] = "Você me fez perceber que meu coração ainda está vivo.",
  [1152359321562112] = "Na verdade, depois que meu marido faleceu, uma vez pensei que meu coração também havia morrido.",
  [1152359321561856] = "Para saborear... a temperatura dos seus lábios.",
  [1152359321561600] = "Para comemorar?",
  [1152359321561344] = "Deixe-me contar outro segredo. Depois de beijar você naquela noite, bebi sozinho mais três taças de vinho quente.",
  [1152359321561088] = "Todas as noites. Sou como uma jovem apaixonada.",
  [1152359321560832] = "Todas as noites?",
  [1152359321560576] = "Você sabe? Depois daquela noite, escondi o lenço que cheirava a você debaixo do travesseiro.",
  [1152359321560320] = "Agora... é hora de conquistar tudo de mim.",
  [1152359321560064] = "Há três dias... aquele beijo... meu coração já foi conquistado por você naquele momento.",
  [1152359321559808] = "Meu coração? Você realmente não entende? Vossa Majestade...",
  [1152359321559552] = "<P_Heart> (O Imperador nunca diria 'não' a ​​uma mulher bonita! Pense novamente...) </>",
  [1152359321559296] = "E agora, eu só quero conquistar seu coração.",
  [1152359321559040] = "Ouça, Lua. Eu sou Roselle Gustav, conquistei reinos e mudei a história.",
  [1152359321558784] = "<P_Heart> (Então ela estava preocupada comigo...) </>",
  [1152359321558528] = "Por que você é tão gentil comigo? Você é o Imperador Roselle, a pessoa mais nobre de todo o reino. E eu sou apenas uma viúva sem nada... Não me atrevo a imaginar como as pessoas iriam fofocar sobre você.",
  [1152359321558272] = "<P_Heart> (Não, o Imperador Roselle nunca seria indiferente. Pense novamente...) </>",
  [1152359321558016] = "Shh, não fale.",
  [1152359321557760] = "Sua... Sua Majestade?",
  [1152359321557504] = "Você não é louca, Luna. Você é apenas uma mulher honesta consigo mesma.",
  [1152359321557248] = "Mas, ao mesmo tempo, o eu louco e impulsivo que tenho dentro de mim está ansioso para ver você novamente esta noite... para tocá-lo novamente... Devo estar louco!",
  [1152359321556992] = "E aquela carta - 'Espere você provar o meu eu completo'... Oh meu Deus, como eu poderia ter escrito tais palavras? Nos últimos dias, me arrependi dessa promessa a cada momento.",
  [1152359321556736] = "Eu... eu não sei. O álcool me deu coragem para fazer a coisa mais louca da minha vida. Beijar você na frente de todos e depois fugir como um covarde.",
  [1152359321556480] = "O que você quer dizer?",
  [1152359321556224] = "Não! Não é isso! Aquele beijo não teve nada a ver com eles!",
  [1152359321555968] = "Então aquele beijo naquela noite foi só para se livrar deles?",
  [1152359321555712] = "Duke Lanster, Duke Soton, Visconde Miller... eles enviam presentes caros e me importunam em diversas ocasiões.",
  [1152359321555456] = "A verdade é que... sou viúva, Majestade. Meu marido faleceu há três anos. Desde então, os homens sentem que sou uma presa fácil.",
  [1152359321555200] = "Não foi isso que eu quis dizer, só queria saber a verdade.",
  [1152359321554944] = "Você também acha... que sou uma mulher frívola?",
  [822505833664256] = "<P_Heart> (assustado) </> N-nada. Eu estava pensando em uma coisa...",
  [822505833666816] = "Obrigado! Embora sua música fosse... embora isso...",
  [804913646940672] = "Claro!",
  [804913646963200] = "O que você quer dizer?",
  [1152359321554688] = "Que homem patético. No entanto, o que ele disse é verdade?",
  [822505833450240] = "Por favor, faça uma pausa na agitação deste momento e venha para o meu lado.",
  [1152359321554432] = "Sua Majestade?",
  [822505833285376] = "E tenta bater na porta de vez em quando!",
  [822505833111296] = "Houve pelo menos sete acidentes com falhas em máquinas de fábrica nos últimos seis meses.",
  [822505833171200] = "Você ouviu os gritos do paciente? Esta clínica está muito errada.",
  [822505833003776] = "Ei, você já ouviu falar do 'Sonho Dourado'? Dizem que as velas daquele navio se transformam em cristal sob o luar!",
  [822505833054464] = "Sim—",
  [1152359322107904] = "Sem dinheiro? Então pare de varrer aqui! Esses ossos velhos deveriam estar no asilo.",
  [1152359321976832] = "Meu nome é {{PlayerName}}. Você tem mais alguma coisa para comprar? Posso ajudá-lo a carregar suas sacolas de compras.",
  [1152359321845760] = "Você me assustou até a morte, então a vovó só queria recolher o lixo.",
  [1152359321830400] = "Graças a Deus você está aqui. Senti a flutuação espiritual em você, Beyonder amigo, preciso de ajuda!",
  [1152359321553152] = "Ferir? Você quebrou meu coração, mas agora diz que estou machucando você? Posso te dar tudo, a posição de Duquesa, toda a riqueza...",
  [1152359321552896] = "Duque Lanster, você está me machucando...",
  [1152359321552640] = "Vejo você em três dias, Sra. Luna.",
  [1152359321552384] = "Um jogo difícil de conseguir. No entanto... já que estou atuando como 'Roselle', posso muito bem entrar no jogo e ver o que ela realmente quer fazer.",
  [1152359321552128] = "Mas, caramba, ela despertou meu interesse com sucesso - como 'Imperador Roselle'.",
  [1152359321551872] = "Que mulher astuta...",
  [1152359321551360] = "A senhora de vestido preto já saiu.",
  [1152359321551104] = "Uma nota? Assinado por Lua. Onde ela está?",
  [1152359321550848] = "Muito bem, seu vinho tinto. Além disso, isso me foi dado por uma senhora para passar a você.",
  [1152359321550592] = "Traga-me uma taça de vinho tinto.",
  [1152359321550336] = "Não, me dê um momento. Eu preciso... me acalmar. Só uma taça de vinho, eu prometo.",
  [1152359321550080] = "Ai meu Deus... o que foi que eu fiz... está muito calor aqui, preciso ir ao terraço tomar um pouco de ar.",
  [1152359321549824] = "Você. Só você. Suas mãos estão tão quentes... ou estou com muito calor?",
  [1152359321549568] = "Esse era o meu eu diurno, o eu sóbrio, o eu contido. Mas agora... o álcool me torna honesto. O eu da noite quer outra coisa.",
  [1152359321549312] = "No salão, pensei que você fosse um inocente amante da arte.",
  [1152359321549056] = "<P_Heart> (Oh meu Deus, por que meu coração está batendo tão rápido? Acalme-se... estou apenas agindo como 'Roselle'!) </>",
  [1152359321548800] = "Como uma mariposa olhando para uma chama, sabendo que ela será queimada, mas incapaz de evitar se aproximar. Sua Majestade, você sabe o quão perigoso você é?",
  [1152359321548544] = "Sim, coragem dada pelo álcool. Caso contrário, como eu ousaria olhar para você assim?",
  [1152359321548288] = "Luna, me chame de Luna. Assim como a lua pertence ao céu, a Luna desta noite pertence a você.",
  [1152359321548032] = "Ainda não sei seu nome.",
  [862028122260225] = "Uau...",
  [1152359321547776] = "Senhora inteligente. Seu lenço, devolvido ao seu dono.",
  [1152359321547520] = "Ser capaz de distinguir rapidamente a autenticidade do trabalho do pintor real Ramsay e derrotar sem esforço vários Sequência 8 especialistas. Olhando para todo o Intis, temo que você não encontre uma segunda pessoa.",
  [1152359321547264] = "Sua Majestade, você chegou mais rápido do que eu esperava.",
  [1152359321547008] = "Eu pareço bem? Eu queria que você visse um lado diferente de mim.",
  [1152359321546752] = "Você trocou de roupa?",
  [1152359321546496] = "Isto não está de acordo com o estilo do Imperador Roselle. Ele nunca perderia nenhuma mulher bonita, devo ir e procurar seu rastro.",
  [1152359321546240] = "O Imperador Roselle nunca perderia nenhuma mulher bonita, devo ir e procurar seu rastro.",
  [1152359321545984] = "Se fosse o Imperador Roselle, o que ele faria neste momento?",
  [1152359321545728] = "Foi deixado pela senhora de antes, e seu perfume de rosa ainda permanece no lenço.",
  [1152359321545472] = "Suficiente! Vocês dois estão conspirando para me humilhar!",
  [1152359321545216] = "Não creio que ele se importaria se, afinal, esse erro fosse tão bonito quanto você.",
  [1152359321544960] = "Obrigado pela correção. Parece que não fui diligente o suficiente ao recitar as máximas do Imperador.",
  [1152359321544704] = "Além disso, por favor, perdoe minha presunção, minha senhora. As palavras originais do Imperador foram: 'O verdadeiro ouro não teme o tempero do fogo.'",
  [1152359321544448] = "Na verdade, este não é o trabalho de Ramsay.",
  [1152359321544192] = "<P_Heart> (Hmm? É minha imaginação ou esta senhora está olhando para mim? Tosse, tosse... é hora de mostrar o charme de Roselle.) </>",
  [1152359321543936] = "O Imperador Roselle disse uma vez: 'O verdadeiro ouro não teme o teste do fogo'. As verdadeiras obras de arte não temem a avaliação de ninguém.",
  [1152359321543680] = "Heh, hoje em dia qualquer um se atreve a falar besteiras sobre arte.",
  [1152359321543424] = "Ramsay é hábil em usar pinceladas fragmentadas para criar uma sensação de névoa fluida. Mas vejam... a pincelada desta pintura é regular, como se imitasse uma impressão da memória em vez de capturar uma nebulosidade momentânea.",
  [1152359321543168] = "Estúpido, como ousa caluniar minha coleção!",
  [1152359321542912] = "Parece que depois de ‘me tornar’ o Imperador Roselle, adquiri alguns de seus conhecimentos.",
  [1152359321542656] = "<P_Heart> (Essas são... pinturas de Ramsay? Ele era o pintor da corte real, e suas pinturas estavam penduradas no quarto do Imperador Roselle...) </>",
  [1152359321542400] = "Oh não. Tosse, tosse... Eu gostaria de andar sozinho, vocês todos podem ir.",
  [1152359321542144] = "Sua Majestade, é raro você sair à paisana. A exposição de arte não é do seu agrado desta vez?",
  [1152359321541888] = "<P_Heart> (Lady Villa disse que o Imperador Roselle era um namorador...) </>",
  [1152359321541632] = "<P_Heart> (Uh... vamos usar um método mais seguro. Minha identidade atual é Roselle, então se eu agir de acordo com a lógica dele, devo ser capaz de encontrar aquela senhora.) </>",
  [1152359321541376] = "<P_Heart> (Atualmente estou agindo como Roselle... se eu agir de acordo com a lógica dele, poderei encontrar aquela senhora.) </>",
  [1152359321541120] = "Mas como devo encontrá-la?",
  [1152359321540864] = "Resolva-a e poderei sair deste lugar... essa é a única maneira por enquanto.",
  [1152359321540608] = "Pensando bem, a voz que me conduziu... a senhora da pintura deve estar escondida em algum lugar deste mundo.",
  [1152359321540352] = "Droga... o que devo fazer agora...",
  [1152359321540096] = "Não, isso deve ser uma ilusão dentro da pintura... Estou, estou preso na pintura?",
  [1152359321539840] = "Roselle?! Eu me tornei o Imperador Roselle?",
  [1152359321539584] = "Sim, Imperador Roselle. Hoje é dia do Salão Nacional de Arte e as exposições aguardam sua apreciação.",
  [1152359321539328] = "Sua Majestade? Você está me ligando?",
  [1152359321539072] = "Hmm, é de fato uma habilidade que só uma Bruxa teria. Preciso investigar esta pintura com cuidado.",
  [1152359321538816] = "Como eu disse isso sem perceber...",
  [1152359321538560] = "Uma senhora parente de Roselle... charme irresistível... poderia ser...",
  [1152359321538304] = "Certa vez, ele escreveu poemas de amor para uma empregada que acabara de conhecer no salão do parlamento e até flertou com sua esposa na frente dos nobres do palácio... Mas mesmo uma Roselle como essa só poderia se curvar diante dela.",
  [1152359321538048] = "Como ele pôde ser tão...",
  [1152359321537792] = "Uh-huh. Há rumores de que Roselle era uma completa... colecionadora. Certa vez, ele disse: 'Posso resistir a tudo, exceto à tentação de mulheres bonitas'.",
  [1152359321537536] = "Roselle e ela...?",
  [1152359321537280] = "Uma... senhora encantadora. Até o Imperador Roselle, em seus primeiros anos, ficou apaixonado por ela.",
  [1152359321537024] = "Quem é ela?",
  [1152359321536768] = "Escutando, meu jovem?",
  [1152359321536512] = "O que diabos eles estão fazendo lá? Não parece normal.",
  [1152359321536256] = "Eu sou seu servo mais leal! Faz três dias e três noites que não fecho os olhos, só para olhar para você mais uma vez!",
  [1152359321536000] = "Estou disposto a engolir mil agulhas de prata por você, apenas implorando por sua pena.",
  [1152359321535744] = "{{PlayerName}}, pedirei ao meu mestre que escreva seu nome na primeira linha dos agradecimentos.",
  [1152359321535488] = "Meu nome é {{PlayerName}}.",
  [1152359321535232] = "Posso ter a honra de saber seu nome?",
  [1152359321534976] = "Depois de trabalharmos juntos por tanto tempo, deveríamos ter desenvolvido um pouco de confiança um no outro.",
  [1152359321534720] = "Obrigado pela sua ajuda durante este período. Quero lhe dar uma recompensa suficientemente generosa.",
  [1152359321534464] = "Se eu ouvir aquela desculpa terrível “meu gato está deitado na máquina de escrever e não me deixa escrever” de novo, realmente não poderei deixar de enviar um telegrama ao editor para relatar todas as suas desculpas anteriores por falta de prazos.",
  [1152359321534208] = "Preciso voltar e supervisionar a escrita dela.",
  [1152359321533952] = "Mas depois que aprendi a falar e a incentivei a abandonar o hábito de atrasar os manuscritos, ela me jogou pela janela para aprender a arte da fala humana.",
  [1152359321533696] = "Sim, essa também é a razão pela qual ela me fez beber a poção.",
  [1152359321533440] = "Essa oportunidade provavelmente não existe. Ela tem muito medo do contato com o mundo exterior, mesmo sendo uma pessoa tão solitária...",
  [1152359321533184] = "Uma Beyonder muito especial, se houver uma chance de vê-la no futuro...",
  [1152359321532928] = "Sim, ela é inundada com cartas instando-a a escrever assim que abre a porta. Só eu posso sair pela janela para coletar alguns materiais para ela.",
  [1152359321532672] = "Seu proprietário também é um Beyonder ? Foi ela quem lhe contratou para coletar materiais?",
  [1152359321532416] = "Isto é, desde que ela me dê a oportunidade de perdoá-la.",
  [1152359321532160] = "Se minha mestra fosse tão eficiente quanto você, eu a perdoaria por me usar como desculpa para atrasar seu manuscrito da última vez.",
  [1152359321531904] = "<P_Heart> (Devo investigar?) </>",
  [1152359321531648] = "Uma nova pista apareceu... uma estranha música de gaita e um cadáver no asilo...",
  [1152359321531392] = "Na área onde os pobres se reúnem... o asilo. Tem um cadáver ali, sim, tem um cadáver!",
  [1152359321531136] = "Onde você ouviu o som?",
  [1152359321530880] = "É uma gaita! Eu não poderia ter ouvido mal! O som da gaita ecoa por toda parte, mas não consigo ver a pessoa que a toca...",
  [1152359321530624] = "O que fez aquele som?",
  [1152359321530112] = "...OK.",
  [1152359321529856] = "Entre no mar da mente e procure as respostas escondidas no subconsciente.",
  [1152359321529600] = "<P_Heart> (Por uma questão de cautela, vamos observar os arredores.) </>",
  [1152359321529344] = "<P_Heart> (No mundo do misticismo, um Espectador não é apenas um espectador.) </>",
  [1152359321529088] = "Não se preocupe comigo, sou apenas um espectador.",
  [1152359321528576] = "Um cachorro chamado Cat, interessante.",
  [1152359321528320] = "É melhor <P_Yellow> ativar Visão Espiritual </> para investigar.",
  [1152359321528064] = "Há uma caixa de fósforos antigos por perto. Isso poderia envolver um incidente Beyonder?",
  [1152359321527808] = "Ainda respirando, mas por que estão inconscientes?",
  [1152359321527552] = "Parece que não há resposta...",
  [1152359321526784] = "Escrevi uma nota de suicídio. Se você não me responder esta noite, irei segui-lo até o mundo da pintura!",
  [1152359321526528] = "Essas flores também têm vergonha de sua própria beleza diante de você e murcham, assim como meu coração...",
  [1152359321526272] = "Olhe para mim! Por favor, olhe para mim! Escrevi mil poemas de amor, cada um elogiando a sua beleza!",
  [1152359321526016] = "Minha Deusa! Meu único amor! Estou disposto a oferecer toda a minha riqueza a você!",
  [1152359321525760] = "Contanto que você consiga fazê-los relaxar a guarda na porta da frente, posso aproveitar esta oportunidade.",
  [1152359321525504] = "Posso tentar controlar os ratos, entrar furtivamente pela porta lateral do restaurante e criar um caos lá dentro. Depois de ouvir a comoção, você pode agir.",
  [1152359321525248] = "Minha Deusa, você dizendo isso realmente salvou esta rua. {{PlayerName}}, você tem alguma maneira de evitar um confronto direto?",
  [1152359321524992] = "<P_Heart> (Precisa entrar furtivamente? A habilidade de corpo espiritual threads nas notas Leano que a Sra. Fors me emprestou pode ser útil. Posso tentar usá-la para controlar </> <P_Yellow> ratos </> <P_Heart> para entrar e criar o caos...) </>",
  [1152359321524736] = "Esta é uma batalha Beyonder; se entrarmos em conflito frontal, será difícil garantir a sobrevivência das pessoas comuns. Mas há reféns lá dentro que precisamos resgatar, e o tempo é muito curto...",
  [1152359321524480] = "Quando os rastreamos até aqui, a festa de degustação já havia começado e os reforços ainda estão a caminho.",
  [1152359321524224] = "{{PlayerName}}! Agradeça à Deusa por deixar você aparecer. Os imitadores do Açougueiro Sangrento controlaram Bonaparte. A festa de degustação é uma armadilha e há pelo menos dois Sequência 8 Beyonders lá dentro.",
  [1152359321523968] = "Luo Yao, Carey, o que aconteceu aqui?",
  [1152359321523200] = "Esta é uma... terapia muito especial. Parece eficaz, requer apenas um pouco de coragem.",
  [1152359321522432] = "Um amigo meu me confiou para vir aqui e conferir.",
  [1152359321522176] = "Ouvi dizer que esta clínica é muito eficaz.",
  [1152359321521920] = "Você está aqui para ver um médico também?",
  [1152359321517056] = "Entendo... Isso é realmente maravilhoso... <P_Heart> (A figura se dissipa gradualmente) </> Não fique triste por mim, todas as coisas têm um fim, e posso finalmente... retornar ao abraço da Terra...",
  [1152359321516800] = "Talvez influenciado pelo poder da Terra, este local é rico em produtos e tem colheitas constantes durante todo o ano. As pessoas da cidade costumam realizar festivais de colheita para elogiar as dádivas da Terra.",
  [1152359321516544] = "Seus companheiros e o Artefato Selado que você mencionou permaneceram no Lago Dourado Outono, sempre protegendo esta terra.",
  [1152359321516288] = "A guerra que você mencionou acabou. Agora não há conflito entre a Igreja da Terra e a Igreja do Conhecimento, mas em Loen, a Igreja do Conhecimento não pode construir igrejas ou pregar como a Igreja da Terra.",
  [1152359321516032] = "Como estão o Bispo e os outros? Nós vencemos? O Artefato Selado ainda está lá?",
  [1152359321515520] = "Naquele dia, eu tinha acabado de plantar as sementes quando o pessoal da Igreja do Conhecimento lançou um ataque furtivo... Eu era o único na logística, então...",
  [1152359321515264] = "Lembro de tudo agora... não preciso mais digerir a poção, eu... já estou morto.",
  [1152359321515008] = "O que você tem?",
  [1152359321514752] = "<P_Heart> (Olhando fixamente sem falar) </> ...",
  [1152359321514496] = "As colheitas foram plantadas, mas foram comidas novamente... Isto conta como uma agricultura bem sucedida?",
  [1152359321514240] = "As plantas estão prestes a murchar, venha logo!",
  [1152359321513728] = "As pessoas da Igreja do Conhecimento estão em minha perseguição e meu tempo está acabando. Pode me ajudar?",
  [1152359321513472] = "O Arcebispo disse que eu deveria digerir completamente a poção Harvest Priest para me qualificar para o campo de batalha, mas depois de deixar Lenburg, estivemos correndo e não tivemos tempo de cultivar a terra.",
  [1152359321512960] = "<P_Heart> (Sem expressão) </> Agricultura.",
  [1152359321512704] = "Que tipo de logística?",
  [1152359321512448] = "Meu nome é Usha, uma monge da Igreja da Meia Noite, designada aqui para ser responsável pela logística por determinados motivos.",
  [1152359321512192] = "Então aquela coisa foi chamada de fruta estranha... Espere, quem é você? Por que você está aqui?",
  [1152359321511936] = "Então foi você quem comeu a fruta estranha que plantei. Não é à toa que senti uma parte do meu poder sendo drenada agora há pouco.",
  [1152359321511168] = "<P_Heart> (Reclamando) </> O noivo de Linna ainda está por perto, fale baixo, irei verificar daqui a pouco.",
  [1152359321510400] = "Sequência espaço reservado, não exibido",
  [1152359321510144] = "Um dia, contarei a todos o meu nome: Emma Larcham! Assim como a Sra. Edwina, farei parte das lendas do mar!",
  [1152359321509120] = "Mesmo que eu não consiga encontrar um tesouro, navegar sob o luar, beber Lerali e cantar canções de marinheiro, só de pensar nisso é maravilhoso...",
  [1152359321508864] = "Tosse, tosse, a fonte não importa... Um dia, navegarei em busca dos tesouros do mar. Quantas libras deveria ser minha recompensa? Hahaha...",
  [1152359321507584] = "Isso mesmo! Senhor/Senhora, você também deve querer embarcar no magnífico e misterioso 'Golden Dream', certo!",
  [1152359321506816] = "Sim, a linda e ótima Sra. Edwina Edwards! O mentor sábio que nos guia, o professor erudito e versátil!",
  [1152359321506048] = "Esta garrafa de vinho... está chamando pela mãe?",
  [1152359321505536] = "...Hmm, nada que eu goste de comer.",
  [1152359321505280] = "Na verdade, depois desse segmento, você entrará em um avião e um bando de cachorros sairá correndo para latir e morder você, mas como a função ainda não está pronta, estou escrevendo aqui por enquanto. Se você vir esta frase, presuma que já foi mordido até a morte pelos cães!",
  [1152359321505024] = "Só tome um pouquinho, só um pouquinho está bem...",
  [1152359321504768] = "...Tudo bem, pelo menos peguei um pedaço de carne.",
  [1152359321504512] = "<P_Heart> (O cachorrinho apenas ri estupidamente e nada acontece.) </>",
  [1152359321504256] = "Que barriga tão macia... Hmm, cachorrinho, guarde o dinheiro.",
  [1152359321504000] = "Então é assim que é—",
  [1152359321503744] = "Anúncio importante?",
  [1152359321503488] = "Ah, não é de admirar que eles sempre proclamem generosamente que essas máquinas são “dispositivos de fé” – acontece que é porque esses dispositivos podem render alguns centavos!",
  [1152359321495552] = "(Hesita) O que exatamente você quer fazer?",
  [1152359321494784] = "(Suspiros) Você... o reino encontrou alguma coisa recentemente?",
  [1152359321493504] = "(Parabéns, Professor Hamer, parece que você encontrou uma maneira melhor.)",
  [1152359321493248] = "(Livros mais vendidos e peças universitárias? A história também parece ter se tornado popular.)",
  [1152359321492992] = "Obrigado pela sua compreensão, com certeza encontrarei a melhor maneira de fazer os alunos realmente se apaixonarem pela história.",
  [1152359321492736] = "Embora o método seja problemático, você é um bom professor e não vou denunciá-lo à escola.",
  [1152359321492480] = "Embora existam circunstâncias atenuantes, você violou a lei e as regras da escola e deve aceitar a punição que merece.",
  [1152359321492224] = "Acho que o Escritório de Integridade Acadêmica enviou você. Vamos, voltarei com você para me render. <P_Yellow> (Escolhas diferentes afetarão a direção do enredo) </>",
  [1152359321491968] = "Mas você se esforçou tanto para me pegar que não deveria ser apenas para discutir métodos de ensino comigo.",
  [1152359321491712] = "Isso faz sentido... você me deu uma nova perspectiva...",
  [1152359321491456] = "Uma nova maneira...",
  [1152359321491200] = "Você deve usar <P_Yellow> maneiras mais novas e interessantes </> de atrair o interesse dos alunos.",
  [1152359321490688] = "Você deve ensinar história de uma forma que todos <P_Yellow> possam entender e compreender facilmente </> .",
  [1152359321490432] = "O conteúdo dos livros didáticos é complicado e obscuro, por isso os alunos não têm paciência para aprender desde o início.",
  [1152359321490176] = "Suspiro... Eu realmente não sei o que fazer para que os alunos realmente tenham vontade de estudar história...",
  [1152359321489920] = "O que você disse faz sentido, eu mesmo sei que esta não é uma forma de resolver o problema fundamental.",
  [1152359321489664] = "Mas isto não é justo para os estudantes que trabalham arduamente, e os estudantes que tomam atalhos não contribuirão para a história no futuro.",
  [1152359321489408] = "No meu coração, a história não é apenas um assunto, mas uma virtude. Eu só... queria demais que todos possuíssem isso, mesmo sabendo que meus métodos estavam errados.",
  [1152359321489152] = "Admiro sua paixão pela história.",
  [1152359321488896] = "E somente diminuindo assim a dificuldade dos exames é que mais alunos estarão dispostos a continuar escolhendo o curso de história em prol de créditos e diplomas.",
  [1152359321488640] = "Só assim os alunos que não ouvem as aulas aprenderão um pouco de conhecimento histórico dos 'materiais internos' para poderem enfrentar os exames.",
  [1152359321488384] = "Como você pode ver, a história está se movendo para os cantos da história. Para acabar com tudo isto, comecei a vender “materiais internos” aos estudantes.",
  [1152359321488128] = "Na verdade, já vi o pôster da sua palestra no quadro de avisos antes, mas ela foi cancelada porque havia poucas inscrições.",
  [1152359321487872] = "A escola ainda está cortando o orçamento de pesquisa do departamento de história e agora o número de meus alunos não chega nem à metade do que era há cinco anos.",
  [1152359321487616] = "Há cada vez menos estudantes interessados ​​e apaixonados por história, e mesmo estudantes com talento não querem estudar história.",
  [1152359321487360] = "Suspiro... desde que o Imperador Roselle liderou as reformas no Intis, as máquinas a vapor e as ações saltaram para se tornarem o foco de todo o continente. Todos os estudantes querem estudar engenharia ou finanças, pois essas são as profissões que podem gerar dinheiro.",
  [1152359321486848] = "Suspiro... é só para fazer os alunos aprenderem um pouco mais!",
  [1152359321486592] = "O que?! Você é o professor? Então por que você está vendendo respostas de exames?",
  [1152359321486336] = "Não acredite em mim? Deixe-me dizer, eu sou <P_Yellow> William Hamer </> —o professor deste curso, até as provas foram escritas por mim!",
  [1152359321486080] = "Hmph, mais do que apenas entender? Para ser humilde, há no máximo seis pessoas em todo o Reino de Loen que sabem mais sobre história do que eu!",
  [1152359321485824] = "Eu não esperava que você realmente conhecesse a história.",
  [1152359321485568] = "Na verdade, existem tantas referências? <P_Yellow> 'Ilha Sonia na Guerra dos Vinte Anos', 'Um Século de Rancores: A Comunidade Imaginada de Império e Família', 'A Era do Ferro Negro: Alegorias Políticas dos Estados Modernos' </> ...",
  [1152359321485056] = "Quer que eu continue lendo?",
  [1152359321484800] = "Pergunta 9, medidas tomadas no norte para evitar a invasão Feysac...",
  [1152359321484544] = "Pergunta 8, a inovação dos métodos de negociação de ações do nosso país e seu impacto...",
  [1152359321484288] = "Não negue, olha o que tem na barraca de flores?",
  [1152359321484032] = "Eu, eu não sou! Que materiais!?",
  [1152359321483776] = "Você deve ser o misterioso vendedor de 'informações privilegiadas'!",
  [1152359321483520] = "Ei-",
  [1152359321483264] = "<P_Heart> (Agora que o peguei em flagrante, é hora de fechar a rede!) </>",
  [1152359321483008] = "<P_Heart> (Alguém parece estar vindo.) </>",
  [1152359321482752] = "Este lugar é bem escondido e a vista é clara, vamos emboscar aqui.",
  [1152359321482496] = "Encontre um lugar escondido para se esconder primeiro, espere que ele traga os materiais internos e então pegue-o assim que tiver evidências.",
  [1152359321482240] = "Este deveria ser o lugar.",
  [1152359321481984] = "<P_Heart> (Vou fazer o que ele diz por enquanto, emboscar lá com antecedência e depois pegá-lo em flagrante!) </>",
  [1152359321481728] = "Tudo bem então.",
  [1152359321481472] = "Não, você deve seguir meu caminho.",
  [1152359321481216] = "Vou colocar os itens no <P_Yellow> estande de flores </> com antecedência, você vem buscá-los na hora certa.",
  [1152359321480960] = "4 horas depois, vá até a entrada do <P_Yellow> Back Street Coffee Shop </>, lá tem um canteiro de flores.",
  [1152359321480704] = "O dinheiro está colocado, onde estão os materiais internos?",
  [1152359321480448] = "Há um buraco de árvore embaixo da segunda árvore em frente, coloque o dinheiro e volte para me encontrar.",
  [1152359321480192] = "<P_Heart> (uma voz rouca sai de repente) </> Tosse, tosse... dois soli, pague primeiro, depois pegue a mercadoria.",
  [1152359321479936] = "Isso não parece certo, qual era a palavra-código mesmo?",
  [1152359321479680] = "Então preciso dizer a palavra-código...",
  [1152359321479424] = "Isso não parece certo, deixe-me pensar novamente, quantas pancadas foram?",
  [1152359321479168] = "Vamos tentar o método que ele mencionou. Lembro que o primeiro passo é...",
  [1152359321478912] = "Banca de jornal abandonada... deveria ser isso.",
  [1152359321478656] = "Muito bom, mas a escola está fiscalizando com tanto rigor agora que não sei se aquele vendedor misterioso ainda está lá. Você pode tentar a sorte.",
  [1152359321478400] = "Você se lembrou de tudo que eu acabei de dizer?",
  [1152359321478144] = "Bata na janela <P_Yellow> três vezes </> , e diga para dentro: '<P_Yellow> O conhecimento me guia aqui </> ', e você conseguirá o que deseja.",
  [1152359321477888] = "Ouça com atenção, há uma banca de jornal <P_Yellow> abandonada há muito tempo no lado norte da escola, e as janelas estão cobertas de jornais.</>",
  [1152359321477632] = "<P_Heart> (mostra um sorriso de 'eu entendo') </> Tudo bem, então lembre-se de contar ao seu amigo.",
  [1152359321477376] = "Já que você é tão sincero, vou te contar.",
  [1152359321477120] = "Você realmente quer comprar os 'materiais internos'?",
  [1152359321476864] = "Tinha muita gente lá, vamos conversar aqui.",
  [1152359321476608] = "Hum? Esse é... o aluno de agora?",
  [1152359321476352] = "Eles com certeza escaparam rápido...",
  [1152359321476096] = "Por que não há som nisso? Que tal... <P_Yellow> dizer olá </> para tentar?",
  [1152359321475840] = "Logo... vai acabar, né... <P_Heart> (voz desaparece) </>",
  [1152359321475584] = "Nós ficamos aqui... e ficamos assim... só para acabar com a desolação de Yodra...",
  [1152359321475328] = "<P_Heart> (suspira) </> Não existe mais nenhuma Igreja da Terra em Feneport... e eu já faz muito tempo...",
  [1152359321475072] = "<P_Heart> (Curioso) </> Você pode sair do Golden Autumn Lake depois de usar isso?",
  [1152359321474816] = "É isso! Obrigado... Que a terra te abençoe.",
  [1152359321474560] = "<P_Heart> (entrega) </> Este é o amuleto de viagem que você perdeu?",
  [1152359321474048] = "<P_Heart> (guarda) </> Não é nada.",
  [1152359321473536] = "<P_Heart> (pega o troco) </> Huh, não é isso...",
  [1152359321473280] = "<P_Heart> (casualmente pega algum troco do caixa) </> Aqui está seu ingresso e troco. O trem sai em meia hora, você pode esperar um pouco na sala de espera.",
  [1152359321473024] = "<P_Heart> (entrega 20 Trier) </> Compre um.",
  [1152359321472768] = "Senhor/Senhora, Senhor/Senhora?",
  [1152359321472512] = "<P_Heart> (Minha espiritualidade intuição parece sugerir que o que procuro está nele) </>",
  [1152359321472256] = "Bem-vindo ao trem Golden Autumn que cruza o lago. A primeira classe é 15 Trier, com vista panorâmica do cenário dourado do outono. Senhor/Senhora, gostaria de um ingresso?",
  [1152359321472000] = "Deve ir para um lugar <P_Yellow> mais alto </>... um lugar <P_Yellow> mais alto </>...",
  [1152359321471744] = "Siga a voz da terra e todas as coisas o guiarão na direção certa...",
  [1152359321471232] = "Pegue, meu jovem.",
  [1152359321470976] = "Desta vez, nosso poder não pode mais ser suprimido, mas a Terra já enviou uma revelação…",
  [1152359321470720] = "Por isso, permaneceu aqui por centenas de anos como uma bétula dourada comum. Até recentemente... senti sua mudança, está prestes a acordar...",
  [1152359321470208] = "<P_Heart> (Outro suspiro) </> Yodra trouxe abrigo, mas também trouxe terrível desolação. Então devemos nos tornar assim, nos tornando recipientes para absorver a desolação para que Yodra não destrua esta terra.",
  [1152359321469952] = "...Aquele grupo de lacaios em busca de conhecimento cobiçava o Artefato Selado da Igreja, a Árvore de Yodra, e o perseguiu até aqui. Para detê-los, tive que quebrar as regras e deixar a árvore tocar a terra...",
  [1152359321469696] = "Guerra de Juramentos Quebrados... <P_Heart> (Lembro que começou como um conflito entre a Igreja da Terra e a Igreja do Conhecimento em Feneport...) </>",
  [1152359321469440] = "Isso remonta à Feneport. Deixe-me pensar... Um estudioso que veio coletar costumes populares mencionou isso, chamando-o de 'Guerra dos Juramentos Quebrados'...",
  [1152359321469184] = "<P_Heart> (suspira) </> Isso tudo ficou no passado. Agora sou apenas uma pedra.",
  [1152359321468928] = "Espere, você é mesmo da Igreja da Terra?",
  [1152359321468672] = "Eu sinto isso, a revelação das profundezas da terra... Obrigado, aqui está o presente final.",
  [809242973969920] = "Faça-me um favor, leve-o para passear pela rua e ajude-me a ver como todos - especialmente os gourmets mais exigentes - reagem a ele?",
  [809242974036992] = "Velho, você está procurando alguma coisa?",
  [1152359321468416] = "Acorde todas as estátuas de pedra e volte para me encontrar.",
  [1152359321468160] = "Sua última aura veio da direção da plataforma…",
  [1152359321467904] = "Antes de sair de Lenburg, minha irmã correu até a igreja e me deu um amuleto de viagem. Não importa quanto tempo estejamos separados, podemos usar isso para nos reunir. Mas eu... eu perdi...",
  [1152359321467648] = "<P_Heart> (emite um suspiro fraco e etéreo) </> É aquele que está perto da cachoeira... Eu sei o que Ele quer fazer. Antes disso, você pode me fazer um favor?",
  [1152359321467136] = "<P_Heart> (parece sentir algo) </> Você... tem o poder deixado por Uda em você. Ele te mandou aqui?",
  [1152359321466880] = "Onde diabos eu perdi isso...",
  [1152359321466624] = "O Imperador Roselle parecia dizer que a riqueza está escondida em atividades perigosas... <P_Heart> (uma escolha difícil) </> Vamos dar uma olhada primeiro.",
  [1152359321466368] = "<P_Heart> (um suspiro final e pesado) </> Suspiro...",
  [1152359321466112] = "Se você acha que sou um Deus Maligno, você também pode denunciar isso à igreja mais próxima. É claro que o presente pertencerá a eles.",
  [1152359321465856] = "Depois de tantos anos, mal consigo sentir seu poder. Vá e me ajude a acordá-los. Como recompensa, darei a você o presente deixado pela terra.",
  [1152359321465600] = "<P_Heart> (desanimado) </> Esqueça, estou aqui há quase quinhentos anos... Não sei quanto tempo mais terei que esperar. Jovem, deveria haver muitas ‘estátuas de pedra’ como eu na floresta próxima.",
  [1152359321465344] = "<P_Heart> (Olhando em volta atentamente, não encontrando nenhuma mudança) </> ...Se realmente é um Deus Maligno, não parece muito forte...",
  [1152359321465088] = "<P_Heart> (Um pouco irritado) </> Que rude! Já fui um Abençoado da Igreja da Terra, como posso ser comparado a um Deus Maligno! Eu vou transformar você em um broto de ervilha!",
  [1152359321464832] = "Uma estátua pode falar?! <P_Heart> (Erguendo a arma, preparando-se para lidar com ela) </> Como esperado, encontrei a corrupção de um Deus Maligno!",
  [1152359321464576] = "Eu estou... bem diante dos seus olhos... jovem, você poderia fazer um favor a uma velha...",
  [1152359321464320] = "Mãe... <P_Heart> (um tanto vigilante) </> Quem é você?",
  [1152359321464064] = "Isso é ótimo, alguém pode finalmente me ouvir... Talvez esta seja uma revelação da terra... Louvada seja a Mãe de Todas as Coisas...",
  [1152359321463808] = "<P_Heart> (um barulho estranho vem de repente) </> Você... consegue ouvir minha voz?",
  [1152359321463296] = "Suspiro... suspiro... suspiro... <P_Heart> (suspiro contínuo e incessante) </>",
  [1152359321452544] = "Ignore essa pessoa, vamos embora!",
  [1152359321452288] = "Nós não os compramos, como saberíamos?",
  [1152359321452032] = "Você pode me dizer como posso comprar os materiais internos?",
  [1152359321451776] = "Também tenho um amigo que precisa urgentemente de uma cópia dos materiais internos!",
  [1152359321451520] = "Esse amigo de quem você está falando, não seria você mesmo!",
  [1152359321451264] = "Não! Foi um amigo meu quem os comprou.",
  [1152359321451008] = "Espere, vocês não compraram todos os materiais internos, não é?",
  [1152359321450752] = "Ouvi dizer que esses materiais internos foram vendidos mais baratos que o custo de impressão. Achei que fosse uma farsa, mas não esperava que fossem realmente úteis.",
  [1152359321450496] = "Graças aos materiais internos, consegui uma pontuação perfeita pela primeira vez na minha vida e temo que seja a última...",
  [1152359321450240] = "Oh não, isso explodiu. Receio nunca mais poder comprar materiais internos.",
  [1152359321449984] = "Os alunos atrás parecem estar falando sobre os materiais internos. Vamos escutar.",
  [1152359321449728] = "Muito obrigado! Você pode começar investigando perto do <P_Yellow> quadro de avisos </> no portão da escola; muitas vezes há muitos estudantes lá. Aguardamos suas boas notícias!",
  [1152359321449472] = "Afinal, é mais fácil para vocês, jovens, lidarem com os estudantes. Além disso, pagaremos a você uma bela recompensa.",
  [1152359321449216] = "{Sr.{Sra.|}}, eu sei que isso é um pouco presunçoso, mas você estaria disposto a me ajudar a investigar este assunto e pegar aquele vendedor misterioso?",
  [1152359321448960] = "Isso parece muito estranho.",
  [1152359321448704] = "Porém, todas as provas foram impressas por mim pessoalmente e lacradas com cera até o dia do exame. Investiguei há muito tempo, mas ainda não descobri como as perguntas originais vazaram!",
  [1152359321448448] = "Esses '<P_Yellow> materiais internos </> ' atingiram com precisão o escopo do exame e até previram algumas das questões originais!",
  [1152359321448192] = "Recentemente, um <P_Yellow> vendedor misterioso </> apareceu na escola, vendendo as chamadas 'informações privilegiadas' aos alunos antes dos exames finais.",
  [1152359321447936] = "Um caso de trapaça? O que está acontecendo?",
  [1152359321447680] = "Prazer em conhecê-lo, deixe-me me apresentar. Meu nome é Sam, do Escritório de Integridade Acadêmica da escola e estou investigando um caso sério de <P_Yellow> trapaça em exames </> .",
  [1152359321447424] = "...Desculpe, perdi a compostura.",
  [1152359321447168] = "Vigaristas gananciosos, parasitas acadêmicos, degenerados morais! Se eu pegar esses maus alunos, com certeza darei a eles um bom aperto de mão com minha régua!",
  [1152359321435392] = "Sua perda.",
  [1152359321435136] = "Esqueça.",
  [1152359321403904] = "Espera, não vai ter mais né...",
  [1152359321403648] = "Tsk, depois de confessar por tanto tempo, tudo o que conseguiram confessar foi um bando de ratos na sarjeta.",
  [1152359321403392] = "Período de Expressão de Arrodes",
  [1152359321393152] = "Período 3 do evento Arrodes",
  [1152359321392896] = "Período 2 do evento Arrodes",
  [1152359321392640] = "Período 1 do evento Arrodes",
  [1152359321391616] = "Período de Expressão de Arrodes 3",
  [1152359321391360] = "Período de Expressão de Arrodes 2",
  [1152359321391104] = "Período de Expressão de Arrodes 1",
  [1152359321388544] = "Arrodes faz uma pergunta",
  [1152359321388288] = "Arrodes Resposta 2",
  [1152359321388032] = "Arrodes Resposta 1",
  [1152359321387776] = "O que devo perguntar?",
  [1152359321387520] = "Por favor fale.",
  [1152359321387264] = "Caro Sr. Arrodes, tenho algumas perguntas que gostaria de fazer.",
  [1152359321387008] = "Como você ousa mentir!",
  [1152359321386752] = "Um banheiro pode ser um bom lugar para jantar...",
  [1152359321386496] = "Boa comida sempre leva tempo.",
  [1152359321386240] = "Você gosta de coisas fedorentas?",
  [1152359321385984] = "É a minha vez de perguntar a você.",
  [1152359321385728] = "O Clube do Tarô é um lugar fundado por Bernadette para aprendizado e progresso.",
  [1152359321385472] = "O que é Clube do Tarô ?",
  [1152359321384448] = "Tudo bem, vamos segui-los e escutar...",
  [1152359321384192] = "Como esperado...",
  [1152359321383936] = "Parece que está nessa direção...",
  [1152359321383680] = "A propósito... essas flores no chão...",
  [1152359321383424] = "Suponho que seja isso por enquanto.",
  [1152359321383168] = "Eu sinto o mesmo, é tão chato...",
  [1152359321382912] = "Estranho, eu costumava me refrescar conversando sobre essas coisas, mas por que fico com mais sono quanto mais conversamos...",
  [1152359321382656] = "Você não sabia? Ela se divorciou de Smith! Ouvi dizer que ela ficou com metade dessas casas, então ela ainda é nossa senhoria. Pelo menos será ela quem receberá o aluguel agora.",
  [1152359321382400] = "A propósito, vi a senhoria ontem. Sua saúde finalmente se recuperou. Não foi fácil para ela, considerando que ela insistia em se confessar mesmo quando mal conseguia aguentar.",
  [1152359321382144] = "Não sei o que há de errado com aquele velho. Ele se recusou a reconhecê-lo como seu filho ilegítimo e, de repente, mudou de idéia e doou todas as suas propriedades para o asilo...",
  [1152359321381888] = "Ele não foi herdar os negócios da família? Por que ele está de volta?",
  [1152359321381632] = "Sam correu atrás deles quando descobriu...",
  [1152359321381376] = "Você aposta! Eles conversaram a noite toda, chorando e rindo. Acabei de ouvir Scarlett gritar: 'Então deixe Sam ir para o inferno!', e ela saiu com Melanie numa carruagem.",
  [1152359321381120] = "Inacreditável, eles realmente trabalharam juntos para largar Sam e deixar Tingen?",
  [1152359321380864] = "Hum? Alguém está conversando...",
  [1152359321380608] = "Então eles realmente se mudaram...",
  [1152359321380352] = "Sem problemas! Vou voltar e escrever o relatório agora mesmo!",
  [1152359321380096] = "<P_Heart> (Silêncio por um momento) </> Preciso escrever um relatório para me inscrever; talvez seja necessário fornecer alguns detalhes do sonho.",
  [1152359321379840] = "<P_Heart> (aliviado) </> Então... você poderia talvez deixar isso ser usado para outra coisa? Como uma estante de livros, uma caixa de correio, uma lata de lixo...",
  [1152359321379584] = "Não, provavelmente será avaliado e classificado como Artefato Selado. Felizmente, seus efeitos negativos não são graves e, com algum processamento, podem ser completamente evitados.",
  [1152359321379328] = "<P_Heart> (um tanto nervoso) </> Você vai destruí-lo?",
  [1152359321379072] = "Não é adequado permanecer aqui. Os colegas virão cuidar disso em breve.",
  [1152359321378816] = "<P_Heart> (Dá um tapinha na cabeça) </> ...Não é de admirar.",
  [1152359321378560] = "Qualquer pessoa que se aproxime ou use o confessionário será inconscientemente atraída por fofocas e espalhará boatos ativamente. Com o tempo, eles sofrerão de insônia, pesadelos, neurastenia, falta de concentração e terão tendência a bater a cabeça ao sair.",
  [1152359321378304] = "Quais são os efeitos?",
  [1152359321378048] = "Notei Beyonder poderes ativos enquanto passava e fiquei preocupado com a possibilidade de Beyonder perder o controle. <P_Heart> (Olhando para o confessionário) </> Felizmente, ele apenas foi ativado recentemente, então os efeitos negativos não são significativos.",
  [1152359321377792] = "Capitão Frye! Por que você apareceu de repente?",
  [1152359321377536] = "Essa voz é...",
  [1152359321377280] = "Ela vai, ela vai perdoar tudo.",
  [1152359321377024] = "Enquanto eu não tiver mais que guardar essas confissões, vou guardar qualquer coisa, qualquer coisa mesmo... <P_Heart> (Timidamente) </> Será que a Deusa... perdoará meus pensamentos?",
  [1152359321376768] = "Como uma estante de livros, uma caixa de correio, uma lata de lixo...",
  [1152359321376512] = "Eu... eu tenho uma última coisa da qual me arrepender... <P_Heart> (Pausa) </> Às vezes eu me pergunto, não posso ser um confessionário e ser outra coisa...",
  [1152359321376256] = "Isso, eu disse tudo isso, me desculpe...",
  [1152359321376000] = "Dan sempre adora fofocar sobre os outros, parece que ele tem feito isso com mais frequência ultimamente, mas ele apenas murmura secretamente, ele não tem gritado isso em voz alta...",
  [1152359321375744] = "Knight gosta de roubar coisas. Ele não tem falta de dinheiro; é um problema psicológico onde ele não consegue controlar as mãos, mas promete roubá-lo, brincar com ele por alguns dias e depois devolvê-lo...",
  [1152359321375488] = "O filho de Catherine não tem nada a ver com o Sr. Smith; ela tem um primeiro amor em seu coração que ela nunca poderá esquecer...",
  [1152359321375232] = "O acidente de carro da Sra. Smith foi intencional; ela se jogou nas rodas da carruagem, na esperança de conseguir alguma compensação para os filhos. Smith também só voltou para casa para bancar o mocinho e evitar pagar pensão alimentícia para seu filho ilegítimo...",
  [1152359321374976] = "Depois que Sam descobriu que poderia herdar bilhões, ele planejou largar Melanie e Scarlett e encontrar um novo amante...",
  [1152359321374720] = "Melanie sabia que o noivo de Scarlett era uma desculpa, mas nunca disse nada porque não queria que Scarlett deixasse Tingen e a deixasse sozinha...",
  [1152359321374464] = "Ouvi Scarlett dizer que não gosta nem um pouco de Sam, ela só queria que Melanie terminasse com aquele homem chato...",
  [1152359321374208] = "<P_Heart> (Voz trêmula) </> Eu... eu quero me arrepender, já ouvi tantos, tantos segredos de gente. Não posso deixar de querer dizer tudo...",
  [1152359321373696] = "Venha, arrependa-se piedosamente a Ele e deixe o eterno céu estrelado limpar sua alma.",
  [1152359321373440] = "<P_Heart> (Limpando a garganta) </> Deusa da Noite, mais nobre que o céu estrelado, mais eterna que a eternidade, que você conceda misericórdia e perdão para absolver os pecados do confessor.",
  [1152359321372928] = "Tudo bem, de agora em diante, deixe-me ser o confessionário e você pode fazer sua confissão para mim.",
  [1152359321372672] = "...Certo, tenho uma ideia.",
  [1152359321372416] = "Está tudo bem, a Deusa da Meia Noite vai te perdoar.",
  [1152359321372160] = "<P_Heart> (Faz um som como se estivesse chorando) </> É tudo culpa minha, sou um perdedor, wuwuwu...",
  [1152359321371904] = "<P_Heart> (Ansioso) </> Eu também estou me tornando cada vez mais estranho. Quando não conseguir me conter, direi um monte de coisas como antes... embora meu pai tenha dito que as confissões não deveriam ser conhecidas por outras pessoas...",
  [1152359321371648] = "Eu também não sei... são essas palavras, são cada vez mais, e quando ficam espremidas, ficam assim.",
  [1152359321371392] = "Sim... e os monstros do sonho?",
  [1152359321371136] = "<P_Heart> (Ignorante) </> Reino de Deus? Muito longe? Então é por isso que o avô nunca mais voltou...",
  [1152359321370880] = "Pai... deve ter ido para o Reino de Deus da Deusa, que é um lugar muito distante.",
  [1152359321370624] = "Ele...",
  [1152359321370368] = "Um dia, dois dias... <P_Heart> (Sussurrando) </> Para onde ele foi, quando ele voltará...",
  [1152359321370112] = "<P_Heart> (Abatido) </> Mas de repente, a partir de um dia, o vovô nunca mais voltou. Mais e mais pessoas faziam fila para se confessar, então tive que ouvir as confissões de todos por ele e manter esse sonho para ele.",
  [1152359321369856] = "Quando o Pai ainda estava aqui, ele guardava essas palavras em sonhos e depois dizia para aqueles que chegavam: 'Está tudo bem, a Deusa da Noite Eterna vai te perdoar', e eles saíam daqui felizes.",
  [1152359321369600] = "São tantas, tantas confissões que se transformaram em palavras, mas o confessionário é muito, muito pequeno. Não pode conter todos eles, então eles fugiriam silenciosamente...",
  [1152359321369344] = "<P_Heart> (Aparentemente balançando a cabeça) </> Eu não criei isso; Papai fez. Ele usou isso para armazenar as confissões de todos.",
  [1152359321369088] = "<P_Heart> (Não pode ser descuidado, um confessionário animado equivale a um item Beyonder, é preciso ter cuidado...) </> Por que você criou esse sonho?",
  [1152359321368832] = "<P_Heart> (Parecendo um pouco solitário) </> Papai não vem aqui há muito tempo.",
  [1152359321368576] = "Se você não acredita em mim, pode entrar e ver...",
  [1152359321368320] = "Você está procurando pelo pai? Ele não está aqui. Só sou eu; sempre fui eu falando com você...",
  [1152359321368064] = "<P_Heart> (Chocado) </> Você... é o confessionário?! <P_Heart> (Olhando para a esquerda e para a direita) </> Onde está o clérigo?",
  [1152359321367808] = "<P_Heart> (Tremendo) </> Certo... bem na sua frente...",
  [1152359321367552] = "Então quem é você?",
  [1152359321367296] = "Beyonder ? O que é isso... eu não sou um Beyonder...",
  [1152359321367040] = "<P_Heart> (Olhando fixamente para uma pilha de texto) </> Uh... será que quando um Beyonder dos Insones Caminho perde o controle... eles simplesmente se transformam em um bando de falantes dormindo?",
  [1152359321366784] = "<P_Heart> (Para abruptamente) </> Eu, por que eu disse tudo isso! Wuwuwuwu, estou errado, eu não deveria ter sido capaz de me conter, sou um perdedor...",
  [1152359321366528] = "Ela está com Sam porque—",
  [1152359321366272] = "Scarlett não tem noivo esperando seu retorno; isso é apenas uma desculpa que ela usa para evitar o casamento! Ela e Melanie se conhecem desde a guerra e até se uniram para lidar com um bandido que tentou roubá-las!",
  [1152359321365760] = "O Barão Rupert é infértil, seus filhos, filhas e filhos ilegítimos não são seus!",
  [1152359321365504] = "Ah, não, estou realmente perdendo o controle—",
  [1152359321365248] = "<P_Heart> (Distorção) </> Não... <P_Heart> (Dor) </> Não consigo mais segurar...",
  [1152359321364992] = "<P_Heart> (Não fez nenhum som, espero que ele não tenha perdido o controle...) </>",
  [1152359321364480] = "Você criou o sonho? Sem dormir Caminho ? Poderia ser um membro da igreja?",
  [1152359321364224] = "Sair! Eu sei que você está escondido aí!",
  [1152359321363968] = "Pai? Pai?",
  [1152359321363456] = "Pai, você pode vê-los?",
  [1152359321362944] = "Apareceu novamente... estas palavras...",
  [1152359321362432] = "Deusa da Meia Noite, que é mais nobre que as estrelas e mais eterna que a eternidade, eu me arrependo de você aqui. Quando passei por aqui, ouvi alguém dizer—",
  [1152359321362176] = "Venha, meu querido filho, arrependa-se piedosamente diante dele e deixe o eterno céu estrelado limpar sua alma.",
  [1152359321361920] = "<P_Heart> (Voz etérea e suave) </> Deusa da Noite, que é mais nobre que as estrelas e mais eterna que a eternidade, que você conceda misericórdia e perdão e perdoe os pecados do confessor.",
  [1152359321361408] = "Isso é... um sonho? O que é usado para conter?",
  [1152359321361152] = "Texto sem sentido no quadro de texto",
  [1152359321360896] = "Onde é isso... tanta neblina...",
  [1152359321360640] = "Minha cabeça dói um pouco... Bati a cabeça?",
  [1152359321360384] = "Ainda bem que há um confessionário.",
  [1152359321360128] = "<P_Heart> (Sentindo uma pitada de culpa) </> Suspiro, espionar nunca é uma coisa boa...",
  [1152359321359872] = "Cinco minutos de confissão, três horas de fofoca. <P_Heart> (Alongamentos) </> Na verdade, eu ouvi por três horas...",
  [1152359321359616] = "Espelho vazio da passagem do tempo",
  [1152359321359360] = "Realmente...",
  [1152359321359104] = "Ouvi...",
  [1152359321358848] = "Hmph, quem sabe em quem esse dinheiro vai parar...",
  [1152359321358592] = "Sim, sim, o acidente de carro da Sra. Smith foi bastante grave. Ouvi dizer que eles receberam um pagamento de seguro enorme?",
  [1152359321358336] = "Além disso, a amante dele também o seguiu, e trouxe uma criança de meio ano... Qual era o nome da amante dele... Catherine?",
  [1152359321358080] = "<P_Heart> (Voz fracamente audível) </> Ah, certo, certo, eu vi o proprietário, Sr. Smith, ontem. Acho que a esposa dele se feriu em um acidente de carro e a consciência dele levou a melhor, então ele deixou a amante e foi para casa...",
  [1152359321357824] = "Bem, algumas pessoas simplesmente têm boa sorte. O Imperador Roselle disse: 'Um vizinho é como uma plataforma alta perto da água, mais facilmente favorecida pela lua...'",
  [1152359321357568] = "<P_Heart> (Apitos) </> Tudo foi para aquele garoto, Sam!",
  [1152359321357312] = "Nunca o vi, ninguém viu. Mas dizem que para esperar por aquele homem, ela rompeu os laços com a família e se mudou... Tsk tsk, parece que ela não precisa mais esperar.",
  [1152359321357056] = "Você viu o noivo dela?",
  [1152359321356800] = "Quem teria pensado que uma guerra iria estourar de repente? O noivo dela foi cumprir missão e está desaparecido até agora.",
  [1152359321356544] = "<P_Heart> (Voz baixa) </> Ouvi dizer que Scarlett estava noiva e quase se casou naquela época!",
  [1152359321356288] = "<P_Heart> (Ah, certo, estávamos falando sobre Scarlett...) </>",
  [1152359321356032] = "Ei, você não terminou o que estava dizendo antes...",
  [1152359321355776] = "<P_Heart> (Isso... que tipo de bagunça é essa...) </>",
  [1152359321355520] = "<P_Heart> (Atordoado) </> Eles... eles voltaram a ser melhores amigos assim? Será porque Sam está prestes a herdar bilhões e este é o poder do dinheiro?",
  [1152359321355264] = "Claro, minha querida. Enquanto estivermos juntos, não há dificuldade que não possamos superar.",
  [1152359321355008] = "<P_Heart> (Lágrimas nos olhos) </> Não há nada mais importante no mundo do que Melanie! Decidimos que vamos abrir uma floricultura juntos e os negócios certamente serão melhores do que são agora.",
  [1152359321354752] = "É isso mesmo, não deveríamos ter machucado um ao outro. Não importa o que aconteceu no passado, Scarlett, você sempre será minha irmã.",
  [1152359321354496] = "Passamos a nos arrepender a Deus e orar para que Ele perdoe nossos pecados.",
  [1152359321354240] = "Isso mesmo. Vocês dois são...",
  [1152359321353984] = "Bom dia, vocês dois. Você está aqui para se confessar também?",
  [1152359321353728] = "<P_Heart> (Sussurrando de surpresa) </> Estou vendo coisas... São Melanie e Scarlett? Eles estão confessando juntos?",
  [1152359321353472] = "<P_Heart> (Eh, já está indo embora? O que aconteceu com Scarlett?) </>",
  [1152359321353216] = "<P_Heart> (Pega um relógio de bolso e olha para ele) </> Por que já é tão tarde? Devo me apressar para me confessar, vamos embora.",
  [633389296144896] = "No dia seguinte",
  [1152359321352960] = "Exatamente, mas essa Scarlett...",
  [1152359321352704] = "Scarlett? Você quer dizer Scarlett, que afirma ser a melhor amiga de Melanie?",
  [1152359321352448] = "...É Scarlett, a dona da floricultura ao lado!",
  [1152359321352192] = "Falando na pequena amante, Sam e Melanie discutiram até tarde da noite. Ele finalmente confessou que a pessoa que ele conheceu nos últimos meses não era outro senão...",
  [1152359321351936] = "Isso é certo! Caso contrário, essa enorme fortuna iria apenas para sua pequena amante.",
  [1152359321351680] = "Se eu fosse Melanie, estaria em cima de Sam, amando-o demais.",
  [1152359321351424] = "<P_Heart> (Suspirando) </> Por que esse tipo de sorte idiota não pode cair sobre mim... A propósito, acho que Melanie também não discutirá mais com ele.",
  [1152359321351168] = "Além disso, ouvi dizer que os três filhos biológicos do velho não são dele... Parece que esse filho ilegítimo vai ganhar uma fortuna. Suspiro, os bons dias para esse garoto ainda estão por vir.",
  [1152359321350912] = "Tsk, quem diria que ele de repente se tornaria o filho ilegítimo daquele Barão Rupert? Se fosse você também estaria andando com o nariz empinado!",
  [646721411498752] = "Louvado seja o Louco!",
  [1152359321350656] = "Sam caiu tanto, mas ainda está sorrindo...",
  [1152359321350400] = "Obrigado, não precisamos de nada.",
  [1152359321350144] = "Os dois convidados precisam de alguma coisa? Você pode nos ligar para atendimento em seus assentos.",
  [1152359321349888] = "Vou pedir ao chefe que renuncie.",
  [1152359321349632] = "Restaurante Polvo Chef? Isso é tão legal. Se Massimo for embora, ela poderá escrever um artigo ainda melhor do que 'King of Chefs'.",
  [1152359321349376] = "Definitivamente irá. Vamos voltar para a Baía de Tisi!",
  [1152359321349120] = "Deixe-me cozinhar na frente de todos? Esse dia pode realmente chegar?",
  [1152359321348864] = "...Xian, você quer que seu próprio restaurante cozinhe abertamente?",
  [1152359321348608] = "Lembro que depois que ela comeu sua comida pela primeira vez, ela ficou muito animada, gritando do outro lado do restaurante que com certeza se tornaria uma gourmet no futuro.",
  [1152359321348352] = "Massimo é aquela garotinha!",
  [1152359321348096] = "Essa frase... Cook costumava dizê-la com frequência para uma garotinha quando ainda estava na baía de Tisi.",
  [1152359321347840] = "Também acho difícil imaginar que ela simplesmente iria embora assim.",
  [1152359321347584] = "Quer dizer que ela descobriu que estávamos fingindo, mas mesmo assim foi embora?",
  [1152359321347328] = "Massimo disse que o sabor não foi afetado pelo cozimento de duas pessoas. Mas ela espera que você se lembre do que disse uma vez: 'As pessoas deveriam pelo menos ser honestas diante da comida'.",
  [1152359321347072] = "Ufa, parece que a enganamos com sucesso!",
  [1152359321346816] = "Massimo foi embora.",
  [1152359321346560] = "Deixe Cook responder a esta pergunta para você. Tenho que voltar para escrever meu rascunho. Espero que ainda estejamos saboreando comida deliciosa quando nos encontrarmos na próxima vez. Adeus.",
  [1152359321346304] = "Então você o conhece há muito tempo... Por que não contou a ele?",
  [1152359321346048] = "Muitos anos atrás, Cook disse que as pessoas deveriam pelo menos ser honestas diante da comida. Espero que ele não tenha esquecido o que disse.",
  [1152359321345792] = "Você é verdadeiramente puro.",
  [1152359321345536] = "Sou gourmet, outras coisas não têm nada a ver comigo. Este prato me diz que Cook merece outra chance.",
  [1152359321345280] = "Você não se importa?",
  [1152359321345024] = "O Continente Sul não hesita em discutir essas estranhas criaturas. Já vi alguns lá, só não esperava ver um aqui.",
  [1152359321344768] = "Aquele polvo, você viu também?",
  [1152359321344512] = "Acabei de ver todo o processo de cozimento pela fresta da porta, vocês dois cooperaram bem.",
  [1152359321344256] = "Você sabia?",
  [1152359321344000] = "Diga ao Cook que cozinhar duas pessoas é realmente mais rápido e estável do que uma, e o sabor realmente não foi afetado.",
  [1152359321343744] = "Quase esqueci de dizer adeus!",
  [1152359321343488] = "Parece que você está bastante satisfeito.",
  [1152359321343232] = "Eu fui imprudente agora há pouco. Gostei da refeição hoje; por favor, agradeça ao Cook por mim!",
  [1152359321342976] = "Estou tão feliz que você esteja satisfeito! Não se preocupe, a partir de agora teremos muito cuidado com a higiene da cozinha.",
  [1152359321342720] = "É exatamente igual ao polvo wasabi que comi naquela época! Talvez tenha sido realmente um mal-entendido; Cook não mudou.",
  [1152359321342464] = "Vou verificar a reação do Massimo.",
  [1152359321342208] = "Tudo bem! Vamos... fazer uma aposta!",
  [1152359321341952] = "Não sei qual era o gosto antes, mas está uma delícia!",
  [1152359321341696] = "Rápido, mergulhe mais uma vez em água gelada enquanto ainda está quente, depois comece a temperar e deixe descansar por quinze minutos...",
  [1152359321341440] = "Como ela saberia disso?",
  [1152359321341184] = "Isso mesmo! Massimo mencionou que a carne deve passar várias vezes no gelo antes de ficar totalmente cozida.",
  [1152359321340928] = "Estou pronto. Durante o processo de branqueamento, o polvo precisa ser mergulhado cinco vezes em água gelada... Foi assim que fiz este prato.",
  [1152359321340672] = "Antes de temperar, existem alguns passos cruciais; precisamos preparar alguns cubos de gelo.",
  [1152359321340416] = "Não se preocupe, Cian comanda, Cook e eu seguimos, vamos fazer esse prato juntos!",
  [1152359321340160] = "Não consigo sentir o gosto de nada... Acabou!",
  [1152359321339904] = "O que eu faço? Ainda não consigo me mover. E eu não posso... Não, Cian, você consegue!",
  [1152359321339648] = "O chefe está aqui! Esta é a última chance...",
  [1152359321339392] = "Cozinhe, faça outra porção de polvo wasabi! Se o relatório da Sra. Massimo for publicado, estaremos acabados! Dê o seu melhor; somente satisfazendo as papilas gustativas de Massimo ela poderá nos deixar em paz!",
  [1152359321339136] = "Com processamento especial, pode ficar muito próximo da carne de polvo, mas nunca deve ser mergulhado em água gelada.",
  [1152359321338880] = "Mas depois que Cook comprou o polvo, ainda não consegui superar a barreira psicológica de cozinhar um semelhante, então tive que usar outra carne.",
  [1152359321338624] = "A escrita de Massimo é cruel, mas ela ousa defender suas crenças em relação ao gosto. Se ela descobrir que não tenho mais habilidade para cozinhar...",
  [1152359321338368] = "Se não fosse pelas dificuldades financeiras, eu não teria deixado o Cian ajudar.",
  [1152359321338112] = "Durante este período, todos os pratos do Restaurante Coastline foram confeccionados por mim. Ao longo dos anos, quase aprendi as proporções de cada prato que Cook prepara, por isso não é difícil de replicar.",
  [1152359321337856] = "Você preparou os pratos de hoje?",
  [1152359321337600] = "Estou bem.",
  [1152359321337344] = "Desculpe, eu não sabia sobre seu relacionamento. Você está bem?",
  [1152359321337088] = "Ugh... Cozinhe... corra...",
  [1152359321336832] = "Cian não é um polvo comum. Há oito anos, salvei-a quando ela ficou ferida na Baía de Tisi e vivemos juntos desde então. Há um ano, quando perdi o emprego devido a reclamações de clientes, ela falou pela primeira vez, dizendo que queria me ajudar a cozinhar...",
  [1152359321336576] = "Então como você veio ao Restaurante Coastline e cooperou com Cian?",
  [1152359321336320] = "Há um ano, perdi o paladar. O médico disse que a causa era complexa e difícil de curar, então perdi o emprego. Desde então, não ousei mais cozinhar...",
  [1152359321336064] = "Então você realmente foi um participante voluntário?",
  [1152359321335808] = "Cian me nocauteou quando você entrou na cozinha; ela provavelmente não queria que eu visse vocês dois brigando.",
  [1152359321335552] = "Eu só queria saber a verdade.",
  [1152359321335040] = "Ele simplesmente desmaiou... você foi controlado por ele voluntariamente? Então como você poderia perder sua sanidade?",
  [1152359321334784] = "O que você fez com Cian? Ela é inocente!",
  [1152359321334528] = "Você parece ter sido controlado pelo polvo por um tempo, mas agora está bem.",
  [1152359321334272] = "Este... é você?",
  [1143563229128960] = "Tão simples? Você não tem medo que eu fotografe algo que não deveria?",
  [1152359321334016] = "Por que parece que está preocupado com Cook... Eu deveria verificar Cook primeiro.",
  [1152359321333760] = "Por favor, deixe Cook ir... leve-o para longe do Restaurante Coastline, não deixe que outros descubram...",
  [1152359321333504] = "Você viu algo que não deveria!",
  [1152359321333248] = "Você é aquele polvo na caixa d'água!",
  [1152359321332992] = "Devo ter esquecido alguma coisa... Vou voltar para a cozinha e dar outra olhada.",
  [848824050422784] = "Meu?",
  [1152359321332736] = "Eu sei que algo está errado, mas eu só... Ugh! Não me faça lembrar dessa cena! Eca!",
  [1152359321332480] = "Massimo, algo está errado. O estado de Cook, a situação na cozinha, sua explicação... nada disso está certo.",
  [1152359321332224] = "Então, por favor, explique-se claramente, caso contrário, amanhã haverá um novo rascunho de revisão na mesa do meu editor-chefe!",
  [1152359321331968] = "Cook não está certo, sua aura não parece saudável; não há vestígios de comida nele, mas ele deixou ranho no fogão?",
  [1152359321331712] = "Cook respeita muito a comida e nunca deixaria a cozinha suja. Poderia haver algum mal-entendido?",
  [1152359321331456] = "Harry, a higiene da sua cozinha não está nada de acordo, vou reescrever um artigo para que o público saiba a verdade!",
  [1152359321331200] = "Sra. Faz muito tempo que não te vejo, você não foi para Limon?",
  [1152359321330944] = "Isso é muito errado! Na verdade, escrevi um artigo para um restaurante com sérios problemas de higiene! O chefe deve me dar uma resposta! Espere, ainda não está certo... Como Cook pôde fazer a cozinha assim? O que ele passou...",
  [1152359321330688] = "Algo não está certo.",
  [1152359321330432] = "Desculpe {Sr.{Sra.|}}, fui eu quem trouxe você aqui e fez você comer comida impura.",
  [1152359321330176] = "Ninguém é permitido na cozinha, desculpe, por favor, saia.",
  [1152359321329920] = "Ranho?! Como chef, você realmente deixou ranho no fogão?",
  [1152359321329664] = "É o ranho que deixei acidentalmente para trás por causa do meu resfriado.",
  [1152359321329408] = "Um resfriado? Então aquelas coisas no fogão não estariam...",
  [1152359321329152] = "Talvez tenha sido um descuido momentâneo, estou resfriado há dois dias.",
  [1152359321328896] = "Você e eu sabemos que isso tem pouco a ver com a origem do polvo, há um problema com a forma como a carne é manuseada.",
  [1152359321328640] = "Talvez a origem do polvo Tingen seja diferente da do sul, então o sabor não é exatamente o mesmo.",
  [1152359321328384] = "Queria perguntar a vocês, por que a carne do polvo com mostarda não tem a mastigabilidade anterior?",
  [1152359321328128] = "O que você está fazendo na minha cozinha?",
  [1152359321327616] = "Alguém viu algo que não deveria.",
  [1152359321327104] = "Estou vendo coisas, um polvo está cozinhando?",
  [1152359321326592] = "Olhe para mim, esqueci o caminho tão rapidamente.",
  [1152359321326336] = "O banheiro fica do outro lado.",
  [1152359321326080] = "Dessa vez sou eu quem precisa ir ao banheiro.",
  [1152359321325824] = "Conheci você aqui há pouco tempo e você também disse que precisava ir ao banheiro.",
  [1152359321325568] = "Haha, sim, precisamos ir ao banheiro.",
  [1152359321325312] = "A cozinha fica nos fundos. Vocês dois estão perdidos?",
  [1152359321325056] = "Ainda não posso ter certeza, mas Cook não admite. Talvez a única maneira seja invadir a cozinha...",
  [1152359321324800] = "Quer dizer que este prato não foi feito pelo próprio Cook?",
  [1152359321324544] = "Não... isso deveria ser o resultado de não molhar a carne em água gelada, ele não deveria cometer tal erro...",
  [1152359321324288] = "Será que foi comprado na hora, um pouco apressado, então a qualidade da carne está pior do que antes?",
  [1152359321324032] = "Cook sempre mergulha o polvo em água gelada cinco vezes antes de estar totalmente cozido, o que confere à carne uma mastigabilidade maravilhosa. Mas esse polvo mostarda... a carne desapareceu e a textura também está muito estranha...",
  [1152359321323776] = "O que está errado? Você acha que não tem um gosto bom?",
  [1152359321323520] = "Está muito próximo do sabor anterior, mas ainda não está certo...",
  [1152359321323264] = "Há algo errado?",
  [1152359321323008] = "Ok, vá em frente.",
  [1152359321322752] = "Sra. Massimo, vou dar uma olhada.",
  [1152359321322496] = "É realmente o Sr. Cook!",
  [1152359321321984] = "Espere... ok, vou tentar... espere um momento, tenho que comprar um polvo aqui perto...",
  [1152359321321472] = "<P_Heart> (Me pergunto se Massimo notou...) </>",
  [1152359321321216] = "<P_Heart> (Este não é o verdadeiro motivo, Cook está escondendo algo...) </>",
  [1152359321320960] = "Não, eu... tenho um animal de estimação que parece um polvo. É como uma família para mim, então não quero cozinhar polvos parecidos com ele. Todos os pratos com polvo foram retirados do cardápio.",
  [1152359321320704] = "Por que? É só porque você não faz polvo há muito tempo? Ou a sua atitude em relação à culinária mudou?",
  [1152359321320448] = "...Lamento muito, este prato não está no cardápio e também não cozinho polvo há muito tempo.",
  [1152359321320192] = "Senhor Cook, vim aqui por reputação, gostaria de lhe pedir que fizesse um polvo com mostarda.",
  [1152359321319680] = "Não, essa não é a atitude dele em relação à culinária... Devo ser responsável pelo artigo que escrevi. Vamos pedir um polvo mostarda, tenho uma impressão profunda deste prato, se houver algum problema posso prová-lo imediatamente.",
  [1152359321319424] = "Quer dizer... a comida não foi feita por ele? Como chefe de cozinha, talvez ele não precise cozinhar pessoalmente?",
  [1152359321319168] = "Isso mesmo, ele é muito estranho. Os chefs trabalham no fogão, é inevitável que saia fumaça oleosa, mas não há cheiro algum no Cook.",
  [1152359321318912] = "O estado de Cook é um pouco...",
  [1152359321318656] = "Cozinhe, espere um momento.",
  [1152359321318400] = "Sra. Massimo, uma palavra por favor.",
  [1152359321318144] = "Estranho, por que Cook parece inquieto? Vamos dar uma olhada com Visão Espiritual .",
  [1152359321317888] = "Cozinhar? Eu sou Massimo. Aquele artigo aí na porta, eu escrevi para você. Você leu?",
  [1152359321317632] = "Cozinheira, faz muito tempo que não nos vemos.",
  [1152359321317376] = "Então é por isso que você me pediu para fazer fila para você.",
  [1152359321317120] = "Shh, eu só quero saborear a comida em silêncio. O dono do restaurante, Harry, estava por perto, tenho medo que ele me reconheça.",
  [1152359321316864] = "Você é Massimo, aquele crítico gastronômico?",
  [1152359321316608] = "Você leu meu artigo com atenção! Isso mesmo, além disso, a quantidade de óleo também foi rigorosamente proporcionada, tornando-o delicioso e saudável!",
  [1152359321316352] = "Fervido e selado por vários dias, depois adicionado com vários vegetais do sul.",
  [1152359321316096] = "E é saudável também. Geralmente, os alimentos fritos aumentam a carga sobre o corpo humano, mas a banha que Cook usa é...",
  [1152359321315840] = "Tão perfumado! Os vegetais fritos na banha não são nada gordurosos.",
  [1152359321315584] = "O garçom está aqui, vamos deixar primeiro um tempo para a comida.",
  [1152359321315328] = "Você parece ter muitas pesquisas sobre comida.",
  [1152359321315072] = "Convidar as pessoas para saborear comidas deliciosas nunca é um problema! E as verdadeiras iguarias têm um “período de floração”, é uma honra permitir que mais pessoas as provem nesse período.",
  [1152359321314816] = "Acabei de ajudar você na fila, não há necessidade de tantos problemas.",
  [1152359321314560] = "Você me ajudou, é claro que tenho que pagar por você.",
  [1152359321314304] = "Por que duas porções?",
  [1152359321314048] = "Chegando.",
  [1152359321313792] = "Ufa! Dê-me os legumes fritos na banha, Isao, duas tortas de porco e dois copos de chá gelado doce.",
  [1152359321313536] = "Você precisa fazer o pedido agora?",
  [1152359321313280] = "{Sr.{Sra.|}}, siga-me.",
  [1152359321312768] = "O convidado número 103 está aqui?",
  [1152359321312512] = "Obrigado! Sou o número 103, se o garçom ligar você entra primeiro.",
  [1152359321312256] = "Ok... mas tenho outras coisas para fazer, só posso te ajudar por um tempo.",
  [1152359321312000] = "Vamos lá, você não ficará desapontado com as habilidades de Cook! Eu sou o próximo, fique aqui um pouco e você será a pessoa que poderá saborear a comida mais rápido hoje!",
  [1152359321311744] = "Estou só de passagem, não pretendo comer.",
  [1152359321311488] = "Com tanta gente na fila, o sabor deve ser muito bom.",
  [1152359321311232] = "Tão repentino... <P_Heart> (Mas estou realmente um pouco curioso.) </>",
  [1152359321310976] = "Este {Sr.{Sra.|}}, você pode me ajudar a manter meu lugar na fila? Estou esperando há horas e realmente não aguento mais, tenho que ir ao banheiro... Podemos jantar juntos mais tarde!",
  [1152359321310720] = "Essa é a atitude rigorosa de Massimo em relação à comida!",
  [1152359321310464] = "A língua de Massimo é afiada e venenosa; os chefs que ela repreendeu poderiam fazer fila para East Balam, o que você acha?",
  [1152359321310208] = "Nunca questione a capacidade de Massimo de apreciar a comida.",
  [1152359321309952] = "Legumes fritos na banha é um prato simples, quão delicioso pode ser?",
  [1152359321309696] = "O dono do Restaurante Coastline postou a matéria em um estande.",
  [1152359321309440] = "Você ainda não leu este “Rei dos Chefs”? Este é o melhor trabalho de Massimo!",
  [1152359321309184] = "O artigo foi publicado no 'Tingen Honest Man'? Não tenho lido jornal ultimamente...",
  [1152359321308928] = "O artigo de Massimo tem uma influência incrível.",
  [1152359321308672] = "Sim, Cook é o chef mais popular de Tingen no momento!",
  [1152359321308416] = "O negócio do Restaurante Coastline é tão bom por causa deste 'Rei dos Chefs'?",
  [1152359321308160] = "\"Rei dos Chefs\"? Um título tão exagerado?",
  [1152359321307904] = "Mas isso é muito exagerado, Massimo até chamou Cook de “Rei dos Chefs”!",
  [1152359321307648] = "O cozinheiro deve ter algumas habilidades, caso contrário, como ele poderia se tornar o chefe de cozinha logo após chegar ao Restaurante Coastline!",
  [1152359321307136] = "Foi este o artigo que Massimo escreveu? Na verdade, ocupou uma página inteira do 'Homem Honesto de Tingen'!",
  [822505833664768] = "Sim, estou pensando... em dar este buquê para o <P_Yellow> caixa do café do outro lado da rua </> .",
  [1143563229129472] = "Não se preocupe, é apenas uma foto. Esta é uma lembrança para mim e também um presente de gratidão que o corvo queria lhe dar.",
  [1139165182860288] = "Não... por favor, não pegue meu ingresso...",
  [1130369089388544] = "...Então vamos, venha comigo até a base. Você me salvou, eu deveria te ajudar. Além disso, meu nome é Lange.",
  [1130369089387776] = "Quero confirmar uma coisa. Mas não se preocupe, se eu tivesse intenções maliciosas, não teria salvado você agora.",
  [1130369089386752] = "Aniversário?",
  [1130369089386496] = "Notícias do Reino? Aniversário do Ministro do Interior hoje, isso conta?",
  [1130369089385728] = "E para nós, a melhor coisa que podemos esperar todos os dias é que alguém como você esteja disposto a enfiar a mão no bolso e nos jogar alguma coisa, pedindo-nos para ajudar a carregar a bagagem, conduzir um cavalo ou entregar uma carta.",
  [1130369089385472] = "Sim. {Sr.{Sra.|}}, você é o tipo de pessoa que vive com dinheiro.",
  [1130369089383680] = "Nada, conheci antes uma criança que dizia ser Ministro das Finanças, ele me pediu algum dinheiro, ele também é seu súdito?",
  [822505833691136] = "Ótimo! Obrigado! Minha casa é fácil de encontrar; é a pequena cabana mais próxima da beira do lago!",
  [822505833690880] = "Talvez eu possa ajudá-lo a buscar o chapéu?",
  [822505833690624] = "Espero aqui todos os dias, querendo cumprimentá-lo com minha aparência mais linda, mas hoje esqueci meu chapéu em casa.",
  [822505833690368] = "Ah, olá! Estou esperando meu marido aqui. Ele saiu da pequena cidade para trabalhar e deve voltar dentro de alguns dias.",
  [822505833690112] = "Senhora, você parece muito perturbada.",
  [822505833668608] = "<P_Heart> (Embora o efeito tenha sido alcançado, por que parece diferente do que eu esperava.) </>",
  [822505833668352] = "<P_Heart> (sincero) </> Gostaria de se inscrever em uma aula de canto? Conheço um professor que ensina muito bem.",
  [822505833668096] = "Contanto que o efeito tenha sido alcançado.",
  [822505833667840] = "Quase fui surpreendido pelo seu tom agudo quando corri para a porta.",
  [822505833667072] = "Embora o quê?",
  [822505833666304] = "Ela, ela aceitou! Ela disse que também está me notando há muito tempo!",
  [822505833666048] = "<P_Heart> (Ele precisa de um pouco de coragem. A canção do Bardo é útil.) </>",
  [822505833665792] = "Com medo que ela recuse. Com medo de dizer a coisa errada. Com medo que ela ria de mim. Com medo... com medo de tudo.",
  [822505833665536] = "Você está com medo?",
  [822505833665280] = "Eu não me atrevo. Estou sentado aqui há duas horas e minhas pernas estão fracas.",
  [822505833665024] = "Então por que você não entra?",
  [1147890944710912] = "O que está errado?",
  [822505833664512] = "Este buquê é seu?",
  [822505833664000] = "O que você tem? Você não está se sentindo bem?",
  [822505833286400] = "Ouça, está vindo de novo! Rápido... preciso bloquear a porta!",
  [822505833207040] = "Está tudo bem, querido! Por que você não leva Walter até lá para comprar um jornal? Tudo bem, vá em frente!",
  [822505833206784] = "Pai, mãe, o que aconteceu?",
  [822505833206272] = "Inferno, do que você está falando? Ele fez uma fortuna enorme no Intis e ainda tenho aquela carta comigo!",
  [822505833206016] = "Não, quero dizer que aquele porteiro sujo se parece exatamente com Bill!",
  [822505833177088] = "Obrigado pela sua ajuda, {Sr.{Sra.|}}. Este é um pequeno símbolo de reunião, aguardando ansiosamente nossa próxima reunião.",
  [822505833176832] = "Hmm, eles também têm bordões facilmente identificáveis, elogiando uns aos outros como <P_Yellow> bem-humorados, espirituosos e engraçados </> .",
  [822505833176576] = "Isso não parece algo difícil.",
  [822505833176320] = "Espero que você possa me ajudar a descobrir mais humor nesta cidade, e eu lhe darei a recompensa correspondente.",
  [822505833176064] = "Hmm... esse tipo de humor alternativo também pode ser considerado uma forma de arte da fala.",
  [822505833175808] = "Ao mesmo tempo, isto também me permite aprender mais sobre a arte da fala humana.",
  [822505833175552] = "Fui contratado para coletar algumas conversas humanas interessantes para fornecer inspiração para a escrita de um determinado autor.",
  [822505833175296] = "Eu gostaria de perguntar a você, no âmbito da linguagem humana, essa conversa agora pode ser considerada interessante?",
  [822505833175040] = "Você pode me chamar de \"Poirot\".",
  [822505833174784] = "Um gato falante... você é um verdadeiro espectador?",
  [822505833174528] = "Olá, {Sr.{Sra.|}}.",
  [822505833171968] = "Não me interpretem mal, não tenho medo de injeções.",
  [822505833171712] = "É melhor eu dar outra olhada.",
  [822505833113344] = "Ha! Não admira que o representante da empresa de inspeção de qualidade chame o orçamento de segurança de \"alimentar as máquinas com comida vegetariana\"... Talvez a seguir proponham alimentar as caldeiras com tortas para reduzir acidentes!",
  [822505833113088] = "<P_Heart> (lendo em voz alta) </> Pessoas honestas que participaram do leilão beneficente revelaram que o relógio de bolso da empresa de inspeção de qualidade chefe é suficiente para ser trocado por vinte válvulas de segurança!",
  [822505833112576] = "<P_Heart> (Abaixa a voz) </> Alguns conselheiros sugerem confiar este assunto à Igreja da Deusa da Noite Eterna para investigação... Você sabe, eles são muito bons em lidar com coisas como assombrações de Espíritos Malignos.",
  [822505833112320] = "Você está dizendo que há uma história oculta por trás disso?",
  [822505833112064] = "Você sabe, todas as caldeiras envolvidas passaram na inspeção de “Grau Premium” da empresa de inspeção de qualidade no início do ano.",
  [822505833111808] = "Mas todos os relatórios de investigação dizem que “o fracasso não pode ser reproduzido”. Você não acha que isso é suspeito?",
  [822505833007104] = "Eu, eu quero viver uma vida curta e apaixonada, não uma vida longa e chata.",
  [822505833006848] = "Isso ainda é melhor do que ficar preso no cais pelo resto da vida! Pelo menos aqueles marinheiros e piratas viram as verdadeiras lendas do mar!",
  [822505833006592] = "Mas o mar é perigoso... Dizem que as coisas mais terríveis no mar nem são as tempestades, mas sim aquelas coisas invisíveis.",
  [822505833006080] = "Onde você conseguiu isso? Como o mapa de rotas deles poderia cair em suas mãos? É real?",
  [822505833005824] = "Olhar! Recebi o mapa de rotas deles há três anos! Diz-se que o 'Sonho Dourado' enterrou um tesouro imensurável em uma ilha misteriosa!",
  [822505833005568] = "Mas o Velho Tom disse que viu com os próprios olhos! Quando o 'Sonho Dourado' passar, até mesmo a onda do mar irá parar!",
  [822505833005312] = "Como isso soa como uma história inventada por marinheiros bêbados...",
  [822505833004800] = "Isso é incrível.",
  [822505833004544] = "Ouvi dizer que há uma biblioteca no navio dela e os livros dentro dela viram as páginas sozinhos!",
  [813709740592384] = "Haha, tem um gosto ótimo, certo? É a receita secreta da minha família; você não encontrará cerveja artesanal tão perfumada nem no Intis.",
  [809242974038784] = "Muito obrigado! Essas páginas devem estar perto do Lago Golden Autumn, conto com você!",
  [809242974038528] = "Deixe-me ajudá-lo a encontrá-los juntos.",
  [809242974038272] = "Então gravei tudo, mas agora... estão todos espalhados...",
  [809242974038016] = "Sofro de amnésia intermitente e todos os dias que acordo esqueço o que aconteceu ontem.",
  [809242974037760] = "Suas memórias?",
  [809242974037504] = "Devo encontrá-los; são minhas únicas lembranças.",
  [519041161495296] = "...Eu também.",
  [519041161495040] = "Parece que... esqueci.",
  [519041161492992] = "Querida, também espero que ele esteja nos esperando na porta quando chegarmos em casa.",
  [519041161492224] = "Mãe, o pai estará no próximo trem?",
  [519041161489152] = "Será, será mais alto que eu, mais alto que você, mais alto que todos nós!",
  [519041161488896] = "Esta árvore crescerá mais alta do que eu no futuro?",
  [519041161488640] = "Um pouco mais fundo, para que as raízes possam firmar-se com firmeza!",
  [519041161488384] = "Pai, quanto mais fundo precisamos cavar?",
  [519041161487872] = "Essa árvore... não me lembro... Você, você se parece muito com meu filho...",
  [519041161487616] = "Padre, você se lembra? Esta árvore foi plantada por você.",
  [519041161470720] = "Posso me juntar à gangue Dragon Hunter? Eu também quero caçar dragões! Onde está Chefe Kevin? Quero encontrá-lo para um autógrafo!",
  [519041161099776] = "Miau...",
  [519041161096704] = "Deusa da Meia Noite, que é mais nobre que as estrelas e mais eterna que a eternidade",
  [360778595294720] = "Ah-",
  [360778595294464] = "......Você está varrendo o chão ou lutando? Use menos força, mantenha seu núcleo estável......",
  [360778595294208] = "Venha, experimente.",
  [360778595293952] = "Você é ainda mais intrometido do que esse velho saco de ossos.",
  [360778595293696] = "Só não esperava que alguém estivesse disposto a defender um varredor.",
  [360778595293440] = "Você...",
  [360778595293184] = "Se eles não forem razoáveis, também sei algumas coisas sobre luta.",
  [360778595292928] = "Se eles forem razoáveis, eu serei razoável.",
  [360778595292416] = "Jovem, boas habilidades. Mas... na verdade, você não precisou intervir.",
  [360778595268096] = "Hmm... ir ao antigo castelo pode trazer algum perigo.",
  [360778595102208] = "O que devo fazer?",
  [360778595055616] = "Sr. Cozinheiro!",
  [360778595055360] = "Ah não... ah não...",
}
